CFG.FX_CLEAVE_AOE  = 200.0   -- ban kinh van cua "cleave"
CFG.FX_REDUCE_CAP  = 0.10    -- tran cung cua "reduce" -- xem mota A006
CFG.FX_BUFF_TIME   = 12.0    -- giay cua "buff"
CFG.FX_BUFF_ARMOR  = 30.0    -- giap cong them khi buff

