-- Ngan sach: 10,000 vang ca van, 50 moi wave thuong (mot nguoi choi).
--
-- Gia 10 cho ca hai lo: nam lo moi wave neu tieu het. Ban truoc dat
-- 40/30 (mot lo mot wave); chu du an chot lai 10.
