-- san cua game nen khong nam quyen. Tu dem luot thi ket qua giong nhau
-- o moi ban, khong phu thuoc du lieu goc.
--
-- CHUA DO: mot item co san nhu 'phea' khi dung co tru MOT luot roi giu
