-- CHUA CAI LOI CHOI NAO. Bang nay moi la ban do -- no cho biet dinh lam
-- gi o dau, de khi bat tay vao thi khong phai quyet lai tu dau. Xem
-- docs/02-he-thong/phan-vung.md va ADR 0014.
