--   chia ra roi dong bo   Tam The Tran (13)
--   ba cho, giu lien tuc  Linh Mach    (17)
--   moi nguoi mot vai     Tam Dao Mon  (3)
--   mot nguoi bi khoa     Tran Ma Thap (5)
