--   17 cach 1 song ngang + 1 doc   -- vung lam thuong xuyen nhat
--   13 cach 2 + 2                  -- su kien, tam ban do
--    3 cach 2 + 4
--    5 cach 4 + 4                  -- xa nhat, kho nhat
