API = {}

-- Frame chi de NHIN thi phai tat tuong tac.
--
-- Frame con nam de len nut se NUOT cu bam: bam dung vao chu tren nut thi
-- khong an, lech ra vai pixel moi an. Chu cang dai thi vung chet cang
-- rong -- nen loi nay luc co luc khong, rat de tuong la may.
--
-- Ap cho MOI frame khong phai nut: chu, icon, vach ke, nen.
local function frameDead(f)
  if f ~= nil and BlzFrameSetEnable ~= nil then BlzFrameSetEnable(f, false) end
  return f
end
API.frameDead = frameDead

-- Nen co vien that, thay cho mot o mau phang.
--
-- BlzCreateFrameByType("BACKDROP", ...) chi cho mot hinh chu nhat tron,
-- phai tu dap texture vao. Ma texture chac chan ton tai o moi ban
-- (TeamColor) lai la mot o mau DAC 1x1 pixel -- nen ket qua luon la mot
-- hinh chu nhat phang, khong vien, canh cung.
--
-- BlzCreateFrame dung TEMPLATE co san trong giao dien game, nen no keo
-- theo ca vien, bo goc va hoa tiet. Doi lai: ten template khong co that
-- thi tra ve nil, nen phai thu lan luot roi moi lui ve cach cu.
--
-- Tra ve ca frame LAN TEN da dung -- khong ghi lai duoc thi khong co
-- cach nao biet no dang ve bang duong nao, dung kieu im lang cua
-- ADR 0012.
local function backdrop(names, parent, pid, fallbackTex)
  if BlzCreateFrame ~= nil and names ~= nil then
    for i = 1, #names do
      local f = BlzCreateFrame(names[i], parent, 0, pid)
      if f ~= nil then return f, names[i] end
    end
  end
  if BlzCreateFrameByType == nil then return nil, "thieu native" end
  local f = BlzCreateFrameByType("BACKDROP", "FlatBackdrop", parent, "", pid)
  if f ~= nil and fallbackTex ~= nil and BlzFrameSetTexture ~= nil then
    BlzFrameSetTexture(f, fallbackTex, 0, true)
  end
  return f, "o mau phang (lui ve)"
end
API.backdrop = backdrop

-- Co chu. Khong co native thi bo qua -- chu ve co mac dinh, van doc duoc.
local function frameScale(f, s)
  if f ~= nil and s ~= nil and BlzFrameSetScale ~= nil then
    BlzFrameSetScale(f, s)
  end
end
API.frameScale = frameScale

-- ---------- Tien ich ----------

local function msg(pid, text)
  if pid == nil then
    for i = 0, bj_MAX_PLAYERS - 1 do
      DisplayTimedTextToPlayer(Player(i), 0, 0, CFG.MSG_TIME, text)
    end
  else
    DisplayTimedTextToPlayer(Player(pid), 0, 0, CFG.MSG_TIME, text)
  end
end

local function dbg(text)
  if CFG.DEBUG then msg(nil, CFG.C_GREY .. "[dbg] " .. text .. CFG.C_END) end
end

local function clamp(v, lo, hi)
  if v < lo then return lo end
  if v > hi then return hi end
  return v
end

local function round(v)
  return math.floor(v + 0.5)
end

-- 12345 -> "12,345"
local function num(n)
  local s = tostring(math.floor(n))
  local out, neg = "", false
  if s:sub(1, 1) == "-" then neg = true; s = s:sub(2) end
  while #s > 3 do
    out = "," .. s:sub(-3) .. out
    s = s:sub(1, -4)
  end
  out = s .. out
  if neg then out = "-" .. out end
  return out
end

-- UnitAlive la native 1.31+; lui ve nguong 0.405 cua Warcraft III.
local function alive(u)
  if u == nil then return false end
  if UnitAlive ~= nil then return UnitAlive(u) end
  return GetUnitState(u, UNIT_STATE_LIFE) > 0.405
end

-- Chay f sau delay giay (mot lan).
local function after(delay, f)
  local t = CreateTimer()
  TimerStart(t, delay, false, function()
    local d = GetExpiredTimer()
    f()
    DestroyTimer(d)
  end)
  return t
end

-- ---------- Vet khoi dong ----------
-- PreloadGenEnd ghi mot file text vao Documents\Warcraft III\. Moi
-- buoc ta ghi lai TOAN BO danh sach, nen sau khi game sap, dong cuoi
-- trong file chinh la buoc cuoi cung da chay xong.
local traceSteps = {}

local function trace(step)
  if not CFG.TRACE then return end
  traceSteps[#traceSteps + 1] = step
  PreloadGenClear()
  PreloadGenStart()
  for i = 1, #traceSteps do
    Preload(traceSteps[i])
  end
  PreloadGenEnd(CFG.TRACE_FILE)
end

-- Doi mot unit/ability id tro lai chuoi bon ky tu. Dung phep chia chu
-- khong dung toan tu bit -- khong phai ban Lua nao cua WC3 cung co.
local function idToStr(v)
  if type(v) ~= "number" then return "?" end
  local a = math.floor(v / 16777216) % 256
  local b = math.floor(v / 65536) % 256
  local c = math.floor(v / 256) % 256
  local d = v % 256
  return string.char(a, b, c, d)
end

API.idToStr = idToStr
API.trace = trace
API.msg   = msg
API.dbg   = dbg
-- Hieu ung roi tu huy sau khi dien xong.
local function fx(model, x, y)
  if model == nil then return end
  DestroyEffect(AddSpecialEffect(model, x, y))
end

API.fx    = fx
API.alive = alive
API.clamp = clamp
API.round = round
API.num   = num
API.after = after
end
