--#region 1_nen/3_sync.lua
do
-- ============================================================
--  3_sync.lua  --  Kenh dong bo: mot may bam, moi may cung lam
--
--  VAN DE. Su kien bam frame chi no tren may nguoi bam. Warcraft III
--  chay lockstep: moi may mo phong cung mot van co, cung mot nhip. Doi
--  trang thai game ngay trong su kien do thi may day di truoc hai may
--  kia -- lech nhip la bi da ra khoi tran.
--
--  Nen: bam KHONG doi gi. No gui mot con so. Moi may nhan duoc con so
--  do cung mot nhip roi MOI doi trang thai.
--
--  BA DUONG GUI, chon bang CFG.SYNC_MODE:
--
--  "blz"   -- BlzSendSyncData + BlzTriggerRegisterPlayerSyncEvent.
--             Co tu 1.31. La su kien, khong phai quet, nen khong co khe
--             thoi gian nao mo ho. Duong tot nhat neu ban nay co.
--
--  "cache" -- StoreInteger + SyncStoredInteger tren game cache. Co tu
--             ban 1.00 nen chac chan ton tai. Khong co su kien bao tin
--             den, phai quet bang timer.
--
--  "local" -- khong dong bo, chay thang. CHI DUNG KHI CHOI MOT MINH.
--
--  "auto" (mac dinh) uu tien blz, roi cache, roi local.
--
--  Duong nao dang chay ghi ro trong file vet, va xem duoc trong game
--  bang lenh -sync.
--
--  KHUON TIN. Moi tin la MOT so nguyen 32 bit:
--
--      packed = op * 10^7  +  seq * 10^5  +  arg
--               op  1..200      seq 0..99     arg 0..99999
--
--  seq co mat chi de phan biet hai tin GIONG HET NHAU gui lien tiep
--  (bam "Dot pha" hai lan). Khong co no thi duong cache -- von so sanh
--  gia tri cu voi moi -- se nuot tin thu hai.
--
--  arg chi 5 chu so, nen KHONG gui duoc id kieu FourCC (H001 la hon 1,2
--  ti). Gui SO THU TU trong bang tinh (CFG.HEROES, danh sach choices)
--  roi tra nguoc ra id o dau ben kia.
--
--  Nho: goi ham cua file khac phai qua API.
-- ============================================================

local OP_MUL  = 10000000
local SEQ_MUL = 100000
local ARG_MAX = 99999
local OP_MAX  = 200
local MISSION = "d"
local PREFIX  = "DTT"

S.sync = {
  mode     = "local",
  handlers = {},      -- [op] = f(pid, arg)
  seen     = {},      -- [pid] = so doc duoc lan cuoi (duong cache)
  seq      = 0,       -- CUC BO: moi may dem rieng, khong phai trang thai game
  cache    = nil,
  timer    = nil,
  trig     = nil,
  pingSeen = {},
  native   = {},
}

local function keyOf(pid) return "p" .. pid end

local function pack(op, seq, arg)
  return op * OP_MUL + (seq % 100) * SEQ_MUL + arg
end

local function unpackMsg(v)
  local op   = math.floor(v / OP_MUL)
  local rest = v - op * OP_MUL
  local seq  = math.floor(rest / SEQ_MUL)
  return op, seq, rest - seq * SEQ_MUL
end

-- ---------- Do xem ban nay co gi ----------

local function probe()
  local t = {}
  t.blzSend = (BlzSendSyncData ~= nil)
  t.blzData = (BlzGetTriggerSyncData ~= nil)
  -- HAI ten. Ban 1.31 dat ten native la BlzTriggerRegisterPlayerSyncEvent;
  -- tai lieu tren mang hay viet thieu tien to Blz. Do ca hai roi hay ket
  -- luan la ban nay khong co dong bo.
  t.blzRegBlz = (BlzTriggerRegisterPlayerSyncEvent ~= nil)
  t.blzRegOld = (TriggerRegisterPlayerSyncEvent ~= nil)
  t.gc = (InitGameCache ~= nil and StoreInteger ~= nil
      and SyncStoredInteger ~= nil and GetStoredInteger ~= nil
      and HaveStoredInteger ~= nil and FlushGameCache ~= nil
      and FlushStoredInteger ~= nil)
  return t
end

local function blzUsable(t)
  return t.blzSend and t.blzData and (t.blzRegBlz or t.blzRegOld)
end

local function chooseMode(t)
  local m = CFG.SYNC_MODE
  if m == "local" then return "local" end
  if m == "blz"   then return blzUsable(t) and "blz" or "local" end
  if m == "cache" then return t.gc and "cache" or "local" end
  if blzUsable(t) then return "blz" end
  if t.gc         then return "cache" end
  return "local"
end

-- ---------- Nhan tin ----------

local function dispatch(pid, packed)
  local op, _, arg = unpackMsg(packed)
  local f = S.sync.handlers[op]
  if f == nil then
    API.trace("sync: tin la op=" .. op .. " tu pid " .. pid)
    return
  end
  f(pid, arg)
end

-- ---------- Duong blz ----------

local function blzStart()
  local reg = BlzTriggerRegisterPlayerSyncEvent or TriggerRegisterPlayerSyncEvent
  S.sync.trig = CreateTrigger()
  for i = 1, #S.pids do
    reg(S.sync.trig, Player(S.pids[i]), PREFIX, false)
  end
  TriggerAddAction(S.sync.trig, function()
    local v = tonumber(BlzGetTriggerSyncData())
    if v == nil then return end
    dispatch(GetPlayerId(GetTriggerPlayer()), v)
  end)
  return true
end

local function blzSendRaw(packed)
  BlzSendSyncData(PREFIX, tostring(packed))
end

-- ---------- Duong cache ----------

local function cachePoll()
  local sy = S.sync
  if sy.cache == nil then return end
  for i = 1, #S.pids do
    local pid = S.pids[i]
    local k = keyOf(pid)
    if HaveStoredInteger(sy.cache, MISSION, k) then
      local v = GetStoredInteger(sy.cache, MISSION, k)
      if v > 0 and v ~= sy.seen[pid] then
        sy.seen[pid] = v
        dispatch(pid, v)
      end
    end
  end
end

local function cacheStart()
  local c = InitGameCache(CFG.SYNC_CACHE)
  if c == nil then return false end

  -- Game cache SONG QUA nhieu van trong cung mot phien Warcraft III, va
  -- no nam tren dia TUNG MAY. Khong xoa thi vao van moi may nay con tin
  -- cu cua van truoc, may kia thi khong -- lech ngay tu giay dau.
  FlushGameCache(c)
  c = InitGameCache(CFG.SYNC_CACHE)
  if c == nil then return false end

  S.sync.cache = c
  for i = 1, #S.pids do S.sync.seen[S.pids[i]] = 0 end

  S.sync.timer = CreateTimer()
  TimerStart(S.sync.timer, CFG.SYNC_POLL, true, cachePoll)
  return true
end

local function cacheSendRaw(pid, packed)
  local sy = S.sync
  if sy.cache == nil then return end
  local k = keyOf(pid)
  StoreInteger(sy.cache, MISSION, k, packed)
  SyncStoredInteger(sy.cache, MISSION, k)

  -- XOA BAN CUC BO NGAY SAU KHI GUI.
  -- StoreInteger ghi thang vao cache cua may nay. Neu de nguyen, bo quet
  -- cua chinh may nguoi gui thay tin o nhip ke tiep (0.1 giay), trong khi
  -- hai may kia phai doi goi tin qua mang. Nguoi gui lam truoc mot nhip
  -- -- lech tran. Xoa di thi may nguoi gui cung phai doi goi tin quay ve
  -- nhu moi nguoi.
  --
  -- Dua tren mot gia dinh CHUA DO DUOC TREN 1.31.1: SyncStoredInteger
  -- dong goi gia tri ngay luc goi, nen xoa sau khong huy duoc no. Neu
  -- gia dinh sai thi tin khong bao gio ve -- nut chet, KHONG lech tran.
  -- Hong kieu do thay duoc ngay khi test; lech tran thi khong. Bo tu
  -- kiem ben duoi do dung viec nay va ghi ket qua vao file vet.
  FlushStoredInteger(sy.cache, MISSION, k)
end

-- ---------- Gui ----------

-- CHI may cua chinh nguoi choi do moi gui. Goi duoc tu su kien cuc bo
-- (bam frame) lan su kien dong bo (chat) deu an toan.
local function send(pid, op, arg)
  arg = math.floor(arg or 0)
  if op < 1 or op > OP_MAX then
    API.trace("sync: op ngoai khoang: " .. tostring(op))
    return
  end
  if arg < 0 or arg > ARG_MAX then
    API.trace("sync: arg ngoai khoang: " .. tostring(arg))
    return
  end
  if GetLocalPlayer() ~= Player(pid) then return end

  local sy = S.sync
  sy.seq = (sy.seq + 1) % 100
  local packed = pack(op, sy.seq, arg)

  if sy.mode == "blz" then
    blzSendRaw(packed)
  elseif sy.mode == "cache" then
    cacheSendRaw(pid, packed)
  else
    dispatch(pid, packed)   -- mot nguoi choi
  end
end

local function on(op, f)
  S.sync.handlers[op] = f
end

-- ---------- Tu kiem ----------
-- Moi nguoi gui mot tin PING luc vao map. Tin ve duoc nghia la duong
-- dang chon that su chay. Ket qua vao file vet, khong lam phien ai.

local function selfTest()
  on(CFG.OP_PING, function(pid, arg)
    S.sync.pingSeen[pid] = true
    API.trace("sync: ping ve tu pid " .. pid .. " (arg " .. arg .. ")")
  end)

  for i = 1, #S.pids do
    send(S.pids[i], CFG.OP_PING, S.pids[i])
  end

  API.after(CFG.SYNC_TEST_WAIT, function()
    local ve, mat = {}, {}
    for i = 1, #S.pids do
      local pid = S.pids[i]
      if S.sync.pingSeen[pid] then ve[#ve + 1] = pid else mat[#mat + 1] = pid end
    end
    API.trace("sync: tu kiem [" .. S.sync.mode .. "] ping ve tu " ..
      #ve .. "/" .. #S.pids .. " nguoi" ..
      (#ve > 0 and (" (player " .. table.concat(ve, ",") .. ")") or "") ..
      (#mat > 0 and (" -- MAT player " .. table.concat(mat, ",")) or ""))
    -- KHONG tu doi duong o day. Neu hai may ket luan khac nhau thi moi
    -- may chay mot kieu -- dung cai muon tranh ngay tu dau. Bao ra roi
    -- de nguoi sua CFG.SYNC_MODE, build lai.
    if #mat > 0 and S.sync.mode ~= "local" then
      API.msg(nil, CFG.C_RED .. "Dong bo [" .. S.sync.mode ..
        "] khong nhan duoc tin cua player " .. table.concat(mat, ",") ..
        " -- nut trong bang se khong an." .. CFG.C_END)
      API.msg(nil, CFG.C_GOLD .. "Doi CFG.SYNC_MODE trong 1_config.lua sang " ..
        (S.sync.mode == "cache" and "\"blz\"" or "\"cache\"") ..
        " roi build lai. Go -sync de xem chi tiet." .. CFG.C_END)
    end
  end)
end

-- ---------- Bao cao ----------

local function statusLines()
  local t = S.sync.native
  local out = {}
  out[#out + 1] = "Duong dang chay: " .. CFG.C_GOLD .. S.sync.mode .. CFG.C_END ..
                  "   (CFG.SYNC_MODE = " .. tostring(CFG.SYNC_MODE) .. ")"
  out[#out + 1] = "BlzSendSyncData .................. " .. tostring(t.blzSend)
  out[#out + 1] = "BlzGetTriggerSyncData ............ " .. tostring(t.blzData)
  out[#out + 1] = "BlzTriggerRegisterPlayerSyncEvent  " .. tostring(t.blzRegBlz)
  out[#out + 1] = "TriggerRegisterPlayerSyncEvent ... " .. tostring(t.blzRegOld)
  out[#out + 1] = "Game cache (Store/Sync/Flush) .... " .. tostring(t.gc)

  -- Ghi ro tung nguoi mot. Truoc day gop thanh mot danh sach so, nen
  -- "Ping ve tu player: 0" doc ra hai nghia trai nguoc nhau: player so 0
  -- da ve, hay khong ai ve. Bang chan doan ma doc nham duoc thi te hon
  -- la khong co.
  for i = 1, #S.pids do
    local pid = S.pids[i]
    out[#out + 1] = "Ping player " .. pid .. ": " ..
      (S.sync.pingSeen[pid] and (CFG.C_JADE .. "da ve" .. CFG.C_END)
                            or (CFG.C_RED .. "CHUA VE" .. CFG.C_END))
  end
  return out
end

local function onChat(pid)
  local lines = statusLines()
  API.msg(pid, CFG.C_GOLD .. "=== Dong bo ===" .. CFG.C_END)
  for i = 1, #lines do API.msg(pid, lines[i]) end
  send(pid, CFG.OP_PING, pid)
  API.msg(pid, CFG.C_GREY ..
    "Da gui mot ping. Go -sync lai sau 1 giay de xem no ve chua." .. CFG.C_END)
end

local function startSync()
  local t = probe()
  S.sync.native = t
  S.sync.mode   = chooseMode(t)

  if S.sync.mode == "blz" then
    if not blzStart() then S.sync.mode = "local" end
  elseif S.sync.mode == "cache" then
    if not cacheStart() then S.sync.mode = "local" end
  end

  API.trace("sync: mode=" .. S.sync.mode ..
    " blzSend=" .. tostring(t.blzSend) ..
    " blzReg=" .. tostring(t.blzRegBlz) ..
    " regCu=" .. tostring(t.blzRegOld) ..
    " cache=" .. tostring(t.gc))

  if S.sync.mode == "local" then
    API.msg(nil, CFG.C_RED .. "Khong co kenh dong bo nao -- bang chi dung duoc " ..
      "khi choi MOT MINH. Go -sync de xem chi tiet." .. CFG.C_END)
  end

  selfTest()
end

API.syncSend   = send
API.syncOn     = on
API.syncMode   = function() return S.sync.mode end
API.syncChat   = onChat
API.syncStatus = statusLines
API.startSync  = startSync
end
--#endregion 1_nen/3_sync.lua

--#region 1_nen/4_geometry.lua
do
-- ============================================================
--  4_geometry.lua  --  Luoi 25 o va cac dong song ngan cach
--
--  Mot truc (vd truc X, 5 cot) duoc chia nhu sau:
--
--    |<-le->|block|song|block|song|block|song|block|song|block|<-le->|
--
--  Kich thuoc block suy ra tu vung choi duoc that su cua map luc chay,
--  khong hard-code. Phan du sau khi chia deu duoc day ra hai bien lam
--  le, nen luoi luon nam chinh giua vung choi duoc.
--
--  Module nay chi tinh TOA DO. No khong ve dia hinh -- Lua cua WC3
--  khong tao duoc nuoc luc chay. Xem docs/04-map/luoi-25-o.md.
-- ============================================================

-- ---------- Toa do co ban ----------

local function polarX(x, dist, angDeg) return x + dist * Cos(angDeg * bj_DEGTORAD) end
local function polarY(y, dist, angDeg) return y + dist * Sin(angDeg * bj_DEGTORAD) end

local function angleXY(x1, y1, x2, y2)
  return bj_RADTODEG * Atan2(y2 - y1, x2 - x1)
end

local function distXY(x1, y1, x2, y2)
  local dx, dy = x2 - x1, y2 - y1
  return SquareRoot(dx * dx + dy * dy)
end

local function playableRect()
  local r = bj_mapInitialPlayableArea
  return GetRectMinX(r), GetRectMinY(r), GetRectMaxX(r), GetRectMaxY(r)
end

-- Chia totalTiles thanh n block ngan cach boi (n-1) con song.
-- Tra ve: so o moi block, so o le moi ben.
local function splitAxis(totalTiles, n, riverTiles)
  local block = CFG.BLOCK_TILES_OVERRIDE
  if block <= 0 then
    block = math.floor((totalTiles - (n - 1) * riverTiles) / n)
  end
  if block < 1 then block = 1 end
  local used = n * block + (n - 1) * riverTiles
  -- Lam tron xuong: goc luoi phai roi dung ranh gioi o dia hinh, neu
  -- khong thi khong con dem o trong World Editor duoc. Nua o du neu co
  -- bi day sang bien phai/tren.
  local margin = math.floor((totalTiles - used) / 2)
  return block, margin
end

local function buildGrid()
  local minX, minY, maxX, maxY = playableRect()
  local T     = CFG.TILE
  local cols  = CFG.GRID_COLS
  local rows  = CFG.GRID_ROWS
  local river = CFG.RIVER_TILES

  local tilesW = API.round((maxX - minX) / T)
  local tilesH = API.round((maxY - minY) / T)

  local bw, marginX = splitAxis(tilesW, cols, river)
  local bh, marginY = splitAxis(tilesH, rows, river)

  S.grid = {
    cols = cols, rows = rows,

    -- don vi the gioi
    blockW  = bw * T,
    blockH  = bh * T,
    river   = river * T,
    originX = minX + marginX * T,
    originY = minY + marginY * T,

    -- don vi o dia hinh, de doi chieu voi World Editor
    tilesW = tilesW, tilesH = tilesH,
    blockTilesW = bw, blockTilesH = bh,
    riverTiles = river,
    marginTilesX = marginX, marginTilesY = marginY,

    playMinX = minX, playMinY = minY, playMaxX = maxX, playMaxY = maxY,
  }

  -- pitch = tu mep trai block nay toi mep trai block ke tiep
  S.grid.pitchX = S.grid.blockW + S.grid.river
  S.grid.pitchY = S.grid.blockH + S.grid.river
  S.grid.spanX  = cols * S.grid.blockW + (cols - 1) * S.grid.river
  S.grid.spanY  = rows * S.grid.blockH + (rows - 1) * S.grid.river

  return S.grid
end

-- Keo mot diem ve trong vung choi duoc cua map.
local function clampToMap(x, y)
  local r = bj_mapInitialPlayableArea
  if r == nil then return x, y end
  local pad = 256.0
  return API.clamp(x, GetRectMinX(r) + pad, GetRectMaxX(r) - pad),
         API.clamp(y, GetRectMinY(r) + pad, GetRectMaxY(r) - pad)
end

-- Block dem tu 1, goc duoi-trai la (1,1) -- cung chieu voi toa do WC3.
local function blockIndex(col, row)
  return (row - 1) * S.grid.cols + col
end

local function blockBounds(col, row)
  local g = S.grid
  local x0 = g.originX + (col - 1) * g.pitchX
  local y0 = g.originY + (row - 1) * g.pitchY
  return x0, y0, x0 + g.blockW, y0 + g.blockH
end

local function blockCenter(col, row)
  local x0, y0, x1, y1 = blockBounds(col, row)
  return (x0 + x1) * 0.5, (y0 + y1) * 0.5
end

-- Tra ve col, row neu diem nam trong mot block.
-- Tra ve nil neu diem nam duoi song hoac ngoai luoi.
local function blockAt(x, y)
  local g = S.grid
  local dx, dy = x - g.originX, y - g.originY
  if dx < 0 or dy < 0 or dx >= g.spanX or dy >= g.spanY then return nil end

  local col = math.floor(dx / g.pitchX) + 1
  local row = math.floor(dy / g.pitchY) + 1
  if col > g.cols then col = g.cols end
  if row > g.rows then row = g.rows end

  -- Phan du sau mep phai block chinh la long song.
  if dx - (col - 1) * g.pitchX > g.blockW then return nil end
  if dy - (row - 1) * g.pitchY > g.blockH then return nil end
  return col, row
end

local function inRiver(x, y)
  local g = S.grid
  local dx, dy = x - g.originX, y - g.originY
  if dx < 0 or dy < 0 or dx >= g.spanX or dy >= g.spanY then return false end
  return blockAt(x, y) == nil
end

-- Cac long song doc: { {x0, x1}, ... }, tu trai sang phai.
local function riverColumns()
  local g, out = S.grid, {}
  for i = 1, g.cols - 1 do
    local x0 = g.originX + (i - 1) * g.pitchX + g.blockW
    out[#out + 1] = { x0 = x0, x1 = x0 + g.river }
  end
  return out
end

-- Cac long song ngang: { {y0, y1}, ... }, tu duoi len tren.
local function riverRows()
  local g, out = S.grid, {}
  for i = 1, g.rows - 1 do
    local y0 = g.originY + (i - 1) * g.pitchY + g.blockH
    out[#out + 1] = { y0 = y0, y1 = y0 + g.river }
  end
  return out
end

local function forEachBlock(f)
  for row = 1, S.grid.rows do
    for col = 1, S.grid.cols do
      local x0, y0, x1, y1 = blockBounds(col, row)
      f(col, row, blockIndex(col, row), x0, y0, x1, y1)
    end
  end
end

-- Doi toa do the gioi sang chi so o dia hinh cua World Editor.
-- Tien khi can go toa do vao WE de ve song cho khop.
local function worldToTile(x, y)
  local g = S.grid
  return API.round((x - g.playMinX) / CFG.TILE), API.round((y - g.playMinY) / CFG.TILE)
end

-- ---------- Vung tao trong World Editor ----------
-- WE sinh moi vung thanh mot bien toan cuc ten gg_rct_<Ten>, tao trong
-- CreateRegions() do main() goi. Bootstrap chay sau khi main() xong nen
-- luc do chung da ton tai.

local function region(name)
  return _G["gg_rct_" .. name]
end

local function regionCenter(r)
  if r == nil then return nil, nil end
  return GetRectCenterX(r), GetRectCenterY(r)
end

-- Liet ke moi vung WE nhin thay duoc. Dung khi ten trong CFG khong khop.
local function listRegions()
  local out = {}
  for k, _ in pairs(_G) do
    if type(k) == "string" and k:sub(1, 7) == "gg_rct_" then
      out[#out + 1] = k:sub(8)
    end
  end
  table.sort(out)
  return out
end

-- Ten vung: mot chuoi, hoac mot danh sach ung vien thu lan luot.
local function regionNames(names)
  if type(names) == "string" then return { names } end
  return names
end

-- Nhan mot ten hoac danh sach ten. Thu khop chinh xac truoc, roi moi
-- khop khong phan biet hoa thuong.
local function findRegion(names)
  local list = regionNames(names)

  for i = 1, #list do
    local r = region(list[i])
    if r ~= nil then return r, list[i] end
  end

  local have = listRegions()
  for i = 1, #list do
    local lower = list[i]:lower()
    for j = 1, #have do
      if have[j]:lower() == lower then return region(have[j]), have[j] end
    end
  end
  return nil, nil
end

-- Ten de hien trong thong bao.
local function regionLabel(names)
  return table.concat(regionNames(names), " / ")
end

-- Bao khong tim thay vung, KEM danh sach vung World Editor that su co.
-- Khong phu thuoc CFG.DEBUG: go sai ten vung la loi rat kho doan neu
-- chi bao "khong thay".
local function regionMissing(cfgKey, name)
  API.msg(nil, CFG.C_RED .. "Khong tim thay vung " .. name ..
    "  (" .. cfgKey .. ")" .. CFG.C_END)
  local rgns = listRegions()
  if #rgns == 0 then
    API.msg(nil, "  World Editor chua co vung nao. Tao vung, Save, roi chay lai build.py.")
  else
    API.msg(nil, "  Vung dang co: " .. table.concat(rgns, ", "))
  end
end

-- ---------- Vai tro cua tung block ----------
--
-- Block khong khai bao trong CFG.BLOCKS thi la "hoang" -- chua giao
-- viec. Tra ve "hoang" chu khong tra nil: goi ben ngoai khong phai kiem
-- nil truoc moi lan dung.
local function blockRole(idx)
  local b = CFG.BLOCKS[idx]
  return (b ~= nil and b.vai) or "hoang"
end

local function blockRoleDef(idx)
  return CFG.BLOCK_ROLE[blockRole(idx)] or CFG.BLOCK_ROLE.hoang
end

local function blockRoleName(idx)
  return API.pick(blockRoleDef(idx))
end

-- Vung World Editor cua mot block: gg_rct_Blk07. Tra ve nil neu chua
-- chay w3region.py -- goi ben ngoai phai chiu duoc chuyen do.
local function blockRegion(idx)
  return region(string.format("%s%02d", CFG.BLOCK_RGN_PREFIX, idx))
end

API.blockRole     = blockRole
API.blockRoleDef  = blockRoleDef
API.blockRoleName = blockRoleName
API.blockRegion   = blockRegion

API.regionNames   = regionNames
API.regionLabel   = regionLabel
API.regionMissing = regionMissing
API.region       = region
API.regionCenter = regionCenter
API.listRegions  = listRegions
API.findRegion   = findRegion

API.polarX       = polarX
API.polarY       = polarY
API.angleXY      = angleXY
API.distXY       = distXY
API.clampToMap   = clampToMap
API.playableRect = playableRect
API.buildGrid    = buildGrid
API.blockIndex   = blockIndex
API.blockBounds  = blockBounds
API.blockCenter  = blockCenter
API.blockAt      = blockAt
API.inRiver      = inRiver
API.riverColumns = riverColumns
API.riverRows    = riverRows
API.forEachBlock = forEachBlock
API.worldToTile  = worldToTile
end
--#endregion 1_nen/4_geometry.lua

--#region 1_nen/5_natives.lua
do
-- ============================================================
--  5_natives.lua  --  Ban 1.31.1 nay co nhung gi
--
--  Moi lan doan xem mot native co ton tai hay khong, du an nay deu doan
--  sai. Lan dat nhat: doan "1.31.1 khong co dong bo" trong khi chi la
--  viet thieu tien to Blz -- ba bang giao dien am tham lui ve che do mot
--  nguoi choi suot may ngay ma khong ai biet (ADR 0012).
--
--  Nen: khong doan nua. Do mot lan luc vao map, ghi vao file vet, va cho
--  xem lai bang lenh -nat.
--
--  Goi mot ten toan cuc chua dinh nghia trong Lua tra ve nil chu khong
--  no loi -- nen chi can so sanh voi nil la do duoc.
--
--  Nho: goi ham cua file khac phai qua API.
-- ============================================================

-- Moi muc: { ten hien thi, gia tri, giai thich neu THIEU }
local function groups()
  return {
    { ten = "Su kien sat thuong", muc = {
      { "EVENT_PLAYER_UNIT_DAMAGED",  EVENT_PLAYER_UNIT_DAMAGED,
        "khong co chu bay, khong lam duoc gi theo sat thuong" },
      { "EVENT_PLAYER_UNIT_DAMAGING", EVENT_PLAYER_UNIT_DAMAGING,
        "khong chan duoc sat thuong TRUOC khi no vao mau" },
      { "BlzSetEventDamage",          BlzSetEventDamage,
        "khong sua duoc so sat thuong -- ne don phai hoi mau bu" },
      { "BlzGetEventDamageTarget",    BlzGetEventDamageTarget, "" },
      { "BlzGetEventAttackType",      BlzGetEventAttackType, "" },
      { "BlzGetEventDamageType",      BlzGetEventDamageType, "" },
      { "UnitDamageTarget",           UnitDamageTarget,
        "khong tu gay sat thuong duoc -- moi skill tu viet deu hong" },
    }},

    { ten = "Sua so lieu ability luc CHAY", muc = {
      { "BlzGetUnitAbility",            BlzGetUnitAbility, "" },
      { "BlzGetUnitAbilityByIndex",     BlzGetUnitAbilityByIndex, "" },
      { "BlzSetAbilityRealLevelField",  BlzSetAbilityRealLevelField,
        "moi con so phai nam san trong war3map.w3a" },
      { "BlzSetAbilityIntegerLevelField", BlzSetAbilityIntegerLevelField, "" },
      { "BlzSetAbilityStringLevelField",  BlzSetAbilityStringLevelField, "" },
      { "BlzGetAbilityRealLevelField",    BlzGetAbilityRealLevelField, "" },
      { "ABILITY_RLF_DAMAGE_HCA1",        ABILITY_RLF_DAMAGE_HCA1, "" },
      { "BlzSetUnitAbilityCooldown",      BlzSetUnitAbilityCooldown, "" },
      { "BlzSetUnitAbilityManaCost",      BlzSetUnitAbilityManaCost, "" },
    }},

    { ten = "Ky nang tu viet", muc = {
      { "EVENT_PLAYER_UNIT_SPELL_EFFECT", EVENT_PLAYER_UNIT_SPELL_EFFECT,
        "khong biet luc nao nguoi choi bam skill" },
      { "GetSpellAbilityId",     GetSpellAbilityId, "" },
      { "GetSpellTargetUnit",    GetSpellTargetUnit, "" },
      { "GetUnitAbilityLevel",   GetUnitAbilityLevel,
        "khong doc duoc level -- khong tra bang so lieu duoc" },
      { "BlzGetAbilityIcon",     BlzGetAbilityIcon, "" },
      { "BlzFrameSetEnable",     BlzFrameSetEnable,
        "chu tren nut se nuot cu bam -- bam dung chu thi khong an" },
    }},

    { ten = "Chi so & ten unit", muc = {
      { "BlzSetUnitName",           BlzSetUnitName,
        "quai giu ten goc cua mau linh (Footman, Ghoul...) -- nhin vao" ..
        " con quai khong biet no thuoc canh gioi nao, tang may" },
      { "BlzGetUnitBaseDamage",     BlzGetUnitBaseDamage, "" },
      { "BlzSetUnitBaseDamage",     BlzSetUnitBaseDamage, "" },
      { "BlzGetUnitArmor",          BlzGetUnitArmor, "" },
      { "BlzSetUnitArmor",          BlzSetUnitArmor, "" },
      { "BlzSetUnitMaxHP",          BlzSetUnitMaxHP, "" },
    }},
  }
end

local function countGroup(g)
  local co, thieu = 0, {}
  for i = 1, #g.muc do
    if g.muc[i][2] ~= nil then co = co + 1
    else thieu[#thieu + 1] = g.muc[i][1] end
  end
  return co, thieu
end

-- Mot dong moi nhom cho file vet: du ngan de doc luot, du chi tiet de
-- biet thieu cai nao.
local function traceAll()
  local gs = groups()
  for i = 1, #gs do
    local co, thieu = countGroup(gs[i])
    local line = "native [" .. gs[i].ten .. "] co " .. co .. "/" .. #gs[i].muc
    if #thieu > 0 then line = line .. " -- THIEU " .. table.concat(thieu, " ") end
    API.trace(line)
  end
end

local function has(name)
  local gs = groups()
  for i = 1, #gs do
    for j = 1, #gs[i].muc do
      if gs[i].muc[j][1] == name then return gs[i].muc[j][2] ~= nil end
    end
  end
  return false
end

-- Liet ke MOI hang so toan cuc co ten chua <loc>. Vi du: "-nat regen".
--
-- Can thiet vi ten hang so moi ban moi khac: ban 1.31.1 KHONG co
-- ABILITY_RLF_DAMAGE_HCA1 nhung cac ham Blz*AbilityField thi co du.
-- Doan ten hang la sai im lang, nen quet thang trong _G roi doc.
--
-- Truoc day ham nay chi quet tien to "ABILITY_", nen "-nat regen" tra
-- ve 0 ket qua va nguoi doc ket luan nham la ban nay khong co truong
-- hoi mau. Gio quet moi ten VIET HOA -- UNIT_RF_*, UNIT_IF_*,
-- ITEM_RF_*, ABILITY_* deu ra.
local function fields(pid, loc)
  loc = loc:upper()
  -- Chat bi cat o CFG.NAT_FIELD_MAX vi man hinh co han. FILE VET thi
  -- khong -- truoc day no ghi cung mot danh sach da cat, nen loc rong
  -- mot chut la mat luon cai minh can tim. Gio ghi DU.
  local hit, tatCa, n = {}, {}, 0
  for k, _ in pairs(_G) do
    if type(k) == "string" and k == k:upper() and #k > 3
       and k:find(loc, 1, true) then
      n = n + 1
      tatCa[#tatCa + 1] = k
      if n <= CFG.NAT_FIELD_MAX then hit[#hit + 1] = k end
    end
  end
  table.sort(tatCa)
  table.sort(hit)
  API.msg(pid, CFG.C_GOLD .. "Hang so chua [" .. loc .. "]: " .. n ..
    CFG.C_END)
  for i = 1, #hit do API.msg(pid, "   " .. hit[i]) end
  if n > #hit then
    API.msg(pid, CFG.C_GREY .. "   ... con " .. (n - #hit) ..
      " cai nua, loc hep hon di." .. CFG.C_END)
  end
  -- Preload() CAT chuoi dai (do duoc: dong ghi ra chi con 278 ky tu,
  -- 7 ten tren 414). Nen chia nho ra nhieu dong chu khong noi mot chuoi
  -- -- mot file vet bi cat lang le con te hon khong ghi gi, vi no trong
  -- nhu da ghi du.
  API.trace("nat fields [" .. loc .. "] = " .. n)
  local dong, phan = {}, 0
  for k = 1, #tatCa do
    dong[#dong + 1] = tatCa[k]
    if #dong >= 6 or k == #tatCa then
      phan = phan + 1
      API.trace("  [" .. loc .. " " .. phan .. "] " .. table.concat(dong, " "))
      dong = {}
    end
  end
end

local function report(pid)
  local gs = groups()
  API.msg(pid, CFG.C_GOLD .. "=== Ban " .. CFG.VERSION .. " co nhung gi ===" .. CFG.C_END)
  for i = 1, #gs do
    local co, thieu = countGroup(gs[i])
    local mau = (#thieu == 0) and CFG.C_JADE or CFG.C_RED
    API.msg(pid, mau .. gs[i].ten .. ": " .. co .. "/" .. #gs[i].muc .. CFG.C_END)
    for k = 1, #thieu do
      API.msg(pid, "   " .. CFG.C_RED .. "thieu " .. thieu[k] .. CFG.C_END)
    end
  end
end

-- ---------- O trong command card ----------
--
-- Command card la luoi 4x3. Moi ability chiem mot o do abpx/abpy trong
-- war3map.w3a quyet dinh, va HAI ability cung o thi de len nhau -- cai
-- sau che cai truoc, khong loi nao bao.
--
-- w3skill.py xep bay ky nang cua Hart vao bay o, dua tren mot cau ghi
-- trong chinh no: "lenh co ban chiem (0,0)-(3,0) va (0,1)". Cau do
-- KHONG DUOC DO bao gio. Neu that ra Move/Stop/Patrol/Hold nam o hang
-- DUOI (y=2) -- nhu tri nho cua moi nguoi ve Warcraft -- thi bon ky
-- nang bi dong dang nam dung cho bon lenh co ban.
--
-- Voi SKILL_START_COUNT = 0 thi khong ai thay: hero vao map tay khong.
-- Voi ca bay phat san thi no hien ra ngay. Nen do, dung doan.
local X_FIELD = "ABILITY_IF_BUTTON_POSITION_NORMAL_X"
local Y_FIELD = "ABILITY_IF_BUTTON_POSITION_NORMAL_Y"

local CO_BAN = {
  { "Amov", "Move" }, { "Astp", "Stop" }, { "Ahol", "Hold" },
  { "Apat", "Patrol" }, { "Aatk", "Attack" },
}

local function oCua(u, aid)
  if BlzGetUnitAbility == nil or BlzGetAbilityIntegerField == nil then
    return nil, "thieu BlzGetUnitAbility / BlzGetAbilityIntegerField"
  end
  local fx, fy = _G[X_FIELD], _G[Y_FIELD]
  if fx == nil or fy == nil then
    return nil, "ban nay khong co " .. X_FIELD
  end
  local ab = BlzGetUnitAbility(u, aid)
  if ab == nil then return nil, "unit khong co ability nay" end
  return BlzGetAbilityIntegerField(ab, fx), nil,
         BlzGetAbilityIntegerField(ab, fy)
end

-- In o that cua ca lenh co ban lan bay ky nang, va bao o nao bi hai
-- ability cung nhan.
--
-- DA DO (2026-09-16): Warcraft KHONG dat lenh co ban bang truong nay.
-- Amov va Aatk deu tra ve (0,0), con Astp / Ahol / Apat thi unit khong
-- he co nhu mot ability. Vi tri that cua chung do game quyet dinh.
--
-- Nen chi dem trung o giua BAY KY NANG. Lan dau ham nay dem ca lenh co
-- ban va bao do "1 o bi hai ability cung nhan" -- bao dong gia, vi Move
-- va Attack deu doc ra (0,0). Mot cai thuoc bao sai con te hon khong co
-- thuoc: no lam nguoi ta di sua thu dang dung.
local function card(pid)
  local d = S.p[pid]
  local u = d and d.hero or nil
  if u == nil then
    API.msg(pid, CFG.C_RED .. "Chua co hero -- pick hero roi go lai." .. CFG.C_END)
    return
  end

  API.msg(pid, CFG.C_GOLD .. "=== O command card (4x3) ===" .. CFG.C_END)

  local chiem = {}
  -- dem = true: o cua frame nay tinh vao viec do trung o.
  local function ghi(ten, aid, dem)
    local x, err, y = oCua(u, aid)
    if x == nil then
      API.msg(pid, CFG.C_GREY .. "   " .. ten .. ": " .. (err or "?") .. CFG.C_END)
      API.trace("card " .. ten .. ": " .. (err or "?"))
      return
    end
    local o = x .. "," .. y
    if not dem then
      API.msg(pid, CFG.C_GREY .. "   (" .. o .. ") " .. ten ..
              "  -- game tu dat, so nay khong tin duoc" .. CFG.C_END)
      API.trace("card [lenh] " .. ten .. " = (" .. o .. ")")
      return
    end
    local cu = chiem[o]
    chiem[o] = (cu and (cu .. " + " .. ten)) or ten
    local mau = cu and CFG.C_RED or CFG.C_JADE
    API.msg(pid, "   " .. mau .. "(" .. o .. ")" .. CFG.C_END .. " " .. ten ..
            (cu and (CFG.C_RED .. "  DE LEN " .. cu .. CFG.C_END) or ""))
    API.trace("card " .. ten .. " = (" .. o .. ")")
  end

  for i = 1, #CO_BAN do ghi(CO_BAN[i][2], FourCC(CO_BAN[i][1]), false) end

  local sk = CFG.SKILLS[GetUnitTypeId(u)]
  if sk ~= nil then
    for i = 1, #sk do ghi(API.pick(sk[i]), sk[i].id, true) end
  end

  local n = 0
  for _, v in pairs(chiem) do if v:find("+", 1, true) then n = n + 1 end end
  if n > 0 then
    API.msg(pid, CFG.C_RED .. n .. " o bi hai KY NANG cung nhan -- sua " ..
      "O_CHUDONG/O_BIDONG trong w3skill.py roi chay lai 'gen'." .. CFG.C_END)
  else
    API.msg(pid, CFG.C_JADE .. "Bay ky nang, bay o, khong o nao trung." .. CFG.C_END)
  end
end

-- ---------- Do hoi mau that cua hero ----------
--
-- Cau hoi: dat BlzSetUnitRealField(hero, <truong hoi mau>, x) co an
-- khong, va no co bi xoa khi chi so hero doi khong?
--
-- Doc lai truong bang BlzGetUnitRealField KHONG tra loi duoc: no cho
-- biet truong GHI gi, khong cho biet engine hoi bao nhieu mau. Nen do
-- mau that: ha mau xuong nua, cho N giay, xem len bao nhieu.
--
-- Do LUON HAI LAN, truoc va sau khi cong chi so, vi hai cau hoi khac
-- nhau tron trong cung mot phep do:
--   lan 1  truong co an khong
--   lan 2  cong Str co XOA mat khong, va mot diem Str dang gia bao nhieu
--
-- Cong Str lam TANG mau toi da VA mau hien tai cung mot luc, nen phai
-- ghi lai mau SAU khi cong roi moi bam gio lan hai -- khong thi phan
-- mau Str tang len bi tinh nham thanh hoi mau.
-- Mot khuon cho CA HAI: mau va mana. Hai phep do giong het nhau, chi
-- khac ten truong, o trang thai, va chi so nao cong vao.
--
-- Dung chung mot ham chu khong chep doi: neu chep thi sua mot ben quen
-- ben kia, va hai con so do bang hai doan code khac nhau thi khong con
-- so sanh duoc voi nhau.
local DO_LOAI = {
  hp = {
    ten    = "mau",
    truong = "UNIT_RF_HIT_POINTS_REGENERATION_RATE",
    cur    = function() return UNIT_STATE_LIFE end,
    max    = function() return UNIT_STATE_MAX_LIFE end,
    doc    = function(u) return GetHeroStr(u, false), GetHeroStr(u, true) end,
    ghi    = function(u, v) SetHeroStr(u, v, true) end,
    chiSo  = "Str",
  },
  mana = {
    ten    = "mana",
    truong = "UNIT_RF_MANA_REGENERATION",
    cur    = function() return UNIT_STATE_MANA end,
    max    = function() return UNIT_STATE_MAX_MANA end,
    doc    = function(u) return GetHeroInt(u, false), GetHeroInt(u, true) end,
    ghi    = function(u, v) SetHeroInt(u, v, true) end,
    chiSo  = "Int",
  },
}

local REG_TEST = 7.0
local REG_STEP = 10

local function regen(pid, giay, loai)
  giay = giay or 8.0
  local L = DO_LOAI[loai or "hp"]
  if L == nil then L = DO_LOAI.hp end

  local d = S.p[pid]
  local h = d and d.hero or nil
  if h == nil then
    API.msg(pid, CFG.C_RED .. "Chua co hero -- pick hero roi go lai." .. CFG.C_END)
    return
  end

  local F = _G[L.truong]
  API.msg(pid, CFG.C_GOLD .. "=== Do hoi " .. L.ten .. " (" .. giay ..
          "s x2) ===" .. CFG.C_END)
  API.msg(pid, "   hang so " .. L.truong .. ": " ..
          (F ~= nil and (CFG.C_JADE .. "CO" .. CFG.C_END)
                    or (CFG.C_RED .. "KHONG CO -- go '-nat regen'" .. CFG.C_END)))
  if F == nil or BlzGetUnitRealField == nil or BlzSetUnitRealField == nil then
    API.msg(pid, CFG.C_RED .. "   thieu native BlzGet/SetUnitRealField -- dung." .. CFG.C_END)
    return
  end

  -- KIEU hoi mau, chi co ben mau. Neu hero la Night/Blight thi dat rate
  -- bao nhieu cung bang 0 ngoai dieu kien do, va phep do se ra 0 ma
  -- khong noi duoc TAI SAO.
  if loai ~= "mana" then
    local TF = _G["UNIT_IF_HIT_POINTS_REGENERATION_TYPE"]
    if TF ~= nil and BlzGetUnitIntegerField ~= nil then
      local v, ten = BlzGetUnitIntegerField(h, TF), "?"
      local bang = { "NONE", "ALWAYS", "DAY", "NIGHT", "BLIGHT" }
      for k = 1, #bang do
        if _G["REGENERATION_TYPE_" .. bang[k]] == v then ten = bang[k] end
      end
      local xau = (ten == "NIGHT" or ten == "BLIGHT" or ten == "NONE")
      API.msg(pid, "   kieu hoi mau (uhrt)        : " ..
              (xau and CFG.C_RED or CFG.C_JADE) .. ten .. CFG.C_END)
    end
  end

  API.msg(pid, CFG.C_GREY ..
    "   Dung danh nhau luc do -- mot cu danh vao hero la so sai het." .. CFG.C_END)

  -- Ha xuong 10%, khong phai 50%.
  --
  -- Voi 50% thi be mana (75) day lai sau 5.4 giay, va phep do 15 giay
  -- chia cho ca 15 giay do -> ra 2.50 thay vi 7.00. So do KHONG sai mot
  -- chut nao, no la trung binh dung -- nhung no tra loi mot cau hoi
  -- khac voi cau minh hoi. Be mau (425) khong bao gio day kip nen ben
  -- mau khong lo, va do la ly do loi nay chi lo ra o ben mana.
  local maxV = GetUnitState(h, L.max())
  SetUnitState(h, L.cur(), maxV * 0.10)

  local truoc = BlzGetUnitRealField(h, F)
  BlzSetUnitRealField(h, F, REG_TEST)
  API.msg(pid, "   truong truoc / sau khi dat : " ..
          string.format("%.3f", truoc) .. " -> " ..
          string.format("%.3f", BlzGetUnitRealField(h, F)))

  -- In CA HAI chi so. Neu goc va tong bang nhau thi phep do KHONG phan
  -- biet duoc "engine dung chi so goc" voi "dung chi so tong" -- noi
  -- thang ra thay vi de nguoi doc tu suy.
  local sGoc, sTong = L.doc(h)
  API.msg(pid, "   " .. L.chiSo .. " goc / tong" ..
          string.rep(" ", 16 - #L.chiSo) .. ": " .. sGoc .. " / " .. sTong ..
          (sGoc ~= sTong and (CFG.C_GOLD .. "  <- khac nhau, phan biet duoc" .. CFG.C_END)
                          or (CFG.C_GREY .. "  (bang nhau -- khong phan biet duoc)" .. CFG.C_END)))

  -- Cham tran thi so trung binh vo nghia -- phai BAO, dung de nguoi doc
  -- tuong day la toc do hoi that.
  local function bao(pid2, nhan, r, cuoi)
    local day = (cuoi >= maxV - 0.01)
    API.msg(pid2, (day and CFG.C_RED or CFG.C_JADE) ..
            "   hoi THAT " .. nhan .. " : " .. string.format("%.2f", r) ..
            " " .. L.ten .. "/giay" .. CFG.C_END ..
            (day and (CFG.C_RED .. "  -> DA DAY BINH, so nay VO NGHIA." ..
                      " Go '-reg " .. (loai == "mana" and "mana " or "") ..
                      "3' cho ngan lai." .. CFG.C_END) or ""))
    return day
  end

  local v0 = GetUnitState(h, L.cur())
  API.after(giay, function()
    local c1 = GetUnitState(h, L.cur())
    local r1 = (c1 - v0) / giay
    bao(pid, "lan 1", r1, c1)

    L.ghi(h, sGoc + REG_STEP)
    local sau = BlzGetUnitRealField(h, F)
    API.msg(pid, "   truong sau +" .. REG_STEP .. " " .. L.chiSo .. " : " ..
            string.format("%.3f", sau) ..
            (math.abs(sau - REG_TEST) > 0.01
             and (CFG.C_RED .. "  -> DA BI TINH LAI" .. CFG.C_END)
             or  (CFG.C_JADE .. "  -> giu nguyen" .. CFG.C_END)))

    SetUnitState(h, L.cur(), maxV * 0.10)
    local v1 = GetUnitState(h, L.cur())
    API.after(giay, function()
      local c2 = GetUnitState(h, L.cur())
      local r2 = (c2 - v1) / giay
      local day = bao(pid, "lan 2", r2, c2)
      API.msg(pid, (day and CFG.C_GREY or CFG.C_GOLD) ..
              "   => mot diem " .. L.chiSo .. " = " ..
              string.format("%.4f", (r2 - r1) / REG_STEP) .. " " ..
              L.ten .. "/giay" .. CFG.C_END)
      L.ghi(h, sGoc)
      API.trace("reg[" .. L.ten .. "]: r1=" .. r1 .. " r2=" .. r2 ..
                " truong_sau=" .. sau)
    end)
  end)
end

-- Liet ke hang so ABILITY_* cua TUNG ky nang, tra theo ma ability GOC.
--
-- Vi sao can: mot ability nhan ban van GIU NGUYEN hieu ung cua ability
-- goc. Chuong la ban sao cua Shockwave nen no tu gay 110 sat thuong cua
-- Shockwave, roi fxLine cua du an cong them mot lan nua -- bang ghi 39.6
-- ma man hinh hien 111.
--
-- Muon tat hieu ung goc thi phai goi Blz*AbilityRealLevelField voi dung
-- ten hang so, ma ten hang so moi ban moi khac. Do, dung doan.
local function spells(pid)
  local d = S.p[pid]
  local u = d and d.hero or nil
  local sk = (u ~= nil) and CFG.SKILLS[GetUnitTypeId(u)] or nil
  if sk == nil then
    API.msg(pid, CFG.C_RED .. "Chua co hero -- pick hero roi go lai." .. CFG.C_END)
    return
  end

  API.msg(pid, CFG.C_GOLD .. "=== Hang so theo ability goc ===" .. CFG.C_END)
  for i = 1, #sk do
    local g = sk[i].goc
    if g == nil then
      API.msg(pid, CFG.C_GREY .. "   " .. API.pick(sk[i]) ..
              ": chua ghi 'goc' trong CFG.SKILLS" .. CFG.C_END)
    else
      -- Bo chu cai dau (A/O/H/u...) de khop rong hon: "AOsh" -> "OSH".
      local loc = g:sub(2):upper()
      local hit = {}
      for k, _ in pairs(_G) do
        if type(k) == "string" and k:sub(1, 8) == "ABILITY_"
           and k:find(loc, 1, true) then
          hit[#hit + 1] = k
        end
      end
      table.sort(hit)
      API.msg(pid, CFG.C_JADE .. "   " .. API.pick(sk[i]) .. CFG.C_END ..
              "  goc " .. g .. "  -> " .. #hit .. " hang so")
      for k = 1, #hit do
        if k > 6 then break end
        API.msg(pid, "      " .. hit[k])
      end
      API.trace("spell " .. g .. ": " .. table.concat(hit, " "))
    end
  end
  API.msg(pid, CFG.C_GREY ..
    "   Day du nam trong DarknessTrace.txt." .. CFG.C_END)
end

local function onChat(pid, raw)
  -- "-nat card" -> in o command card that cua hero dang cam
  if raw ~= nil then
    if raw:match("^%s*%-nat%s+card%s*$") ~= nil then return card(pid) end
    if raw:match("^%s*%-nat%s+spell%s*$") ~= nil then return spells(pid) end
    -- "-nat dam" -> liet ke hang so ability co ten chua "dam"
    local loc = raw:match("^%s*%-nat%s+(%S+)")
    if loc ~= nil then return fields(pid, loc) end
  end
  return report(pid)
end

local function startNatives()
  traceAll()
end

API.nativeHas    = has
API.nativeChat   = onChat
API.nativeFields = fields
API.nativeCard   = card
API.nativeSpells = spells
API.nativeRegen  = regen
API.startNatives = startNatives
end
--#endregion 1_nen/5_natives.lua

--#region 1_nen/6_lang.lua
do
-- ============================================================
--  6_lang.lua  --  Chu hien cho nguoi choi, hai thu tieng
--
--  CFG.LANG chon tieng. build.py --lang en|vi ghi de len no, nen mot
--  bo nguon xuat ra duoc hai ban map.
--
--  HAI CACH, dung cho hai thu khac nhau:
--
--  1. API.t("key")  -- chu co dinh cua giao dien. Nam trong bang T ben
--     duoi, mot cho duy nhat, de doi chieu xem thieu cau nao.
--
--  2. API.pick(tbl) -- ten nam trong bang du lieu (canh gioi, ky nang,
--     hero). Khong tach ra khoi bang du lieu vi ten di lien voi so lieu
--     cua no; tach ra la hai bang phai giu dong bo bang tay.
--
--  THIEU CAU THI TRA VE CHINH CAI KEY, khong tra ve nil va khong sap.
--  Chu la mot khoa lo ra tren man hinh, de thay, sua sau cung duoc --
--  khac han voi nil lam no giua tran.
--
--  Nho: goi ham cua file khac phai qua API.
-- ============================================================

local T = {}

T.en = {
  -- Bang nhan vat
  panel_close     = "ESC / %s to close",
  panel_close_esc = "ESC to close",
  panel_skill     = "Skills",
  panel_gear      = "Gear",
  panel_root      = "Spirit Root",
  panel_treasure  = "Treasures",
  panel_linhkhi   = "Spirit Qi",
  panel_level     = "lv",
  panel_max       = "max",
  panel_cd        = "cd",
  panel_mana      = "mana",
  col_rank        = "Rank",
  col_realm       = "Realm",
  col_power       = "Power",
