local function lang()
  return T[CFG.LANG] and CFG.LANG or "en"
end

-- Thieu cau thi tra ve chinh cai key. Mot chuoi la tren man hinh de
-- thay ngay va sua sau duoc; nil thi no giua tran.
local function t(key, ...)
  local s = T[lang()][key]
  if s == nil then
    API.trace("lang: THIEU cau [" .. tostring(key) .. "] tieng " .. lang())
    return tostring(key)
  end
  if select("#", ...) == 0 then return s end
  return string.format(s, ...)
end

-- Ten nam trong bang du lieu: { ten = "Pham Nhan", en = "Mortal" }
-- Tieng Viet giu o khoa "ten" vi bang du lieu viet bang tieng Viet truoc.
local function pick(tbl)
  if tbl == nil then return "?" end
  if lang() == "en" then return tbl.en or tbl.ten or "?" end
  return tbl.ten or tbl.en or "?"
end

-- Doi chieu hai bang: thieu cau nao thi bao ngay luc vao map, dung de
-- tinh co mo dung the do moi phat hien.
local function checkAll()
  local thieu = {}
  for k, _ in pairs(T.en) do
    if T.vi[k] == nil then thieu[#thieu + 1] = "vi:" .. k end
  end
  for k, _ in pairs(T.vi) do
    if T.en[k] == nil then thieu[#thieu + 1] = "en:" .. k end
  end
  if #thieu > 0 then
    API.trace("lang: LECH BANG -- " .. table.concat(thieu, " "))
  else
    API.trace("lang: " .. lang() .. ", hai bang khop nhau")
  end
end

API.t         = t
API.pick      = pick
API.lang      = lang
API.langCheck = checkAll
end
--#endregion 1_nen/6_lang.lua

--#region 2_nguoi_choi/1_player.lua
do
-- ============================================================
--  1_player.lua  --  Dang ky nguoi choi va quan he dong minh
--
--  Buoc 1 chi lam dung hai viec: biet ai dang choi, va dat quan he
--  ba nguoi choi <-> phe dich. Chua co hero, chua co chi so.
-- ============================================================

local function initPlayers()
  S.pids = {}
  S.p = {}

  for i = 1, #CFG.PLAYER_SLOTS do
    local pid = CFG.PLAYER_SLOTS[i]
    local p = Player(pid)
    -- Slot trong hoac do may giu deu bi bo qua, nen choi mot minh van vao duoc.
    if GetPlayerSlotState(p) == PLAYER_SLOT_STATE_PLAYING
       and GetPlayerController(p) == MAP_CONTROL_USER then
      S.p[pid] = { active = true, hero = nil, heroCount = 0,
                   slots = {},
                   linhKhi = 0, linhKhiTotal = 0,
                   linhCan = 1, fctGold = 0,

                   tb = {},       -- [so thu tu o trang bi] = cap
                   tbUps = 0,     -- tong so lan da nang, de tra gia
                   pk = {} }      -- [ma phap khi] = true
      S.pids[#S.pids + 1] = pid
    end
  end

  -- Ba nguoi choi la dong minh, chung tam nhin.
  for i = 1, #S.pids do
    for j = 1, #S.pids do
      if i ~= j then
        SetPlayerAllianceStateBJ(Player(S.pids[i]), Player(S.pids[j]), bj_ALLIANCE_ALLIED_VISION)
      end
    end
  end

  -- Phe dich doi dau voi tat ca.
  S.enemy = Player(CFG.ENEMY_SLOT)
  for i = 1, #S.pids do
    SetPlayerAllianceStateBJ(S.enemy, Player(S.pids[i]), bj_ALLIANCE_UNALLIED)
    SetPlayerAllianceStateBJ(Player(S.pids[i]), S.enemy, bj_ALLIANCE_UNALLIED)
  end

  -- Nha chinh dung slot rieng, khong thuoc ve rieng ai. No la dong minh
  -- cua ca ba nguoi choi va CHUNG TAM NHIN -- nho vay tam nhin 1500 cua
  -- no moi co ich cho ho. Va no doi dau voi phe dich de bi nham lam
  -- muc tieu.
  S.houseOwner = Player(CFG.HOUSE_SLOT)
  for i = 1, #S.pids do
    SetPlayerAllianceStateBJ(Player(S.pids[i]), S.houseOwner, bj_ALLIANCE_ALLIED_VISION)
    SetPlayerAllianceStateBJ(S.houseOwner, Player(S.pids[i]), bj_ALLIANCE_ALLIED_VISION)
  end
  SetPlayerAllianceStateBJ(S.houseOwner, S.enemy, bj_ALLIANCE_UNALLIED)
  SetPlayerAllianceStateBJ(S.enemy, S.houseOwner, bj_ALLIANCE_UNALLIED)

  -- Tat quyen dieu khien chung mot cach TUONG MINH.
  -- bj_ALLIANCE_ALLIED_VISION o tren da tat san, nhung dat lai ro rang
  -- thi doc code khong phai tra xem hang so BJ do bat/tat nhung gi.
  if SetPlayerAlliance ~= nil and ALLIANCE_SHARED_CONTROL ~= nil then
    for i = 1, #S.pids do
      local p = Player(S.pids[i])
      SetPlayerAlliance(p, S.houseOwner, ALLIANCE_SHARED_CONTROL, false)
      SetPlayerAlliance(S.houseOwner, p, ALLIANCE_SHARED_CONTROL, false)
      if ALLIANCE_SHARED_ADVANCED_CONTROL ~= nil then
        SetPlayerAlliance(p, S.houseOwner, ALLIANCE_SHARED_ADVANCED_CONTROL, false)
        SetPlayerAlliance(S.houseOwner, p, ALLIANCE_SHARED_ADVANCED_CONTROL, false)
      end
    end
  end

  -- Slot nha chinh trung slot nguoi choi hoac slot dich thi quan he
  -- dong minh o tren se da nhau. Bao ngay thay vi de no hong am tham.
  if CFG.HOUSE_SLOT == CFG.ENEMY_SLOT then
    API.msg(nil, CFG.C_RED .. "CFG.HOUSE_SLOT trung ENEMY_SLOT -- nha chinh dang"
      .. " thuoc phe dich." .. CFG.C_END)
  end
  for i = 1, #CFG.PLAYER_SLOTS do
    if CFG.PLAYER_SLOTS[i] == CFG.HOUSE_SLOT then
      API.msg(nil, CFG.C_RED .. "CFG.HOUSE_SLOT trung slot nguoi choi "
        .. CFG.HOUSE_SLOT .. "." .. CFG.C_END)
    end
  end

  return #S.pids
end

-- ---------- Khoa hero: kinh nghiem & ky nang ----------
--
-- SuspendHeroXP chan viec NHAN kinh nghiem, nen hero dung yen o cap
-- hien tai. Goi nhieu lan len cung mot unit la vo hai, nen bo quet co
-- the chay lai thoai mai.

-- Rut sach diem ky nang.
--
-- Warcraft III khong co native doc so diem ky nang hien co, nen tru dan
-- tung diem toi khi native bao khong tru duoc nua. Chan 20 vong de
-- khong bao gio treo du native co tra ve gi.
local function stripSkillPoints(u)
  if not CFG.STRIP_SKILL_POINTS then return 0, "tat" end
  if UnitModifySkillPoints == nil then return 0, "native khong ton tai" end

  local n = 0
  for _ = 1, 20 do
    if not UnitModifySkillPoints(u, -1) then break end
    n = n + 1
  end
  return n, "ok"
end

-- Phat diem ky nang. Dung o che do "learn" -- goi luc tao hero, hoac
-- bat cu khi nao ban muon thuong (don sach dot quai, moc thoi gian...).
local function grantSkillPoints(u, n)
  if u == nil or n == nil or n <= 0 then return false end
  if UnitModifySkillPoints == nil then return false end
  if CFG.STRIP_SKILL_POINTS then
    API.msg(nil, CFG.C_RED .. "Phat diem ky nang khi STRIP_SKILL_POINTS con bat" ..
      " -- bo quet se an mat ngay." .. CFG.C_END)
  end
  return UnitModifySkillPoints(u, n)
end

-- Do danh sach ability THAT cua hero ra file vet. Moi unit chi do mot
-- lan de khong lam ngap file.
--
-- Day la cach lay ID that thay vi doan: danh sach ID hero skill tren
-- mang khong dang tin, va doan sai thi UnitRemoveAbility im lang khong
-- lam gi -- kieu that bai kho phat hien nhat.
local function dumpAbilities(u)
  if not CFG.TRACE or S.dumped[u] then return end
  if BlzGetUnitAbilityByIndex == nil or BlzGetAbilityId == nil then
    API.trace("abil: khong co BlzGetUnitAbilityByIndex de liet ke")
    S.dumped[u] = true
    return
  end
  S.dumped[u] = true

  local list = {}
  for i = 0, 40 do
    local ab = BlzGetUnitAbilityByIndex(u, i)
    if ab == nil then break end
    list[#list + 1] = API.idToStr(BlzGetAbilityId(ab))
  end
  API.trace("abil " .. GetUnitName(u) .. " (" .. #list .. "): " ..
            table.concat(list, " "))
end

-- Go ky nang goc, va GHI LAI ket qua tung id.
--
-- UnitRemoveAbility tra ve boolean: true nghia la unit CO ability do va
-- da go duoc, false nghia la unit khong he co no. Day la cach duy nhat
-- con lai de biet id doan dung hay sai, vi 1.31.1 khong co
-- BlzGetUnitAbilityByIndex de liet ke truc tiep.
local function removeStockAbilities(u)
  local report = (CFG.TRACE and not S.abilReported[u])
  if report then S.abilReported[u] = true end

  local hits = {}
  for i = 1, #CFG.HERO_REMOVE_ABILITIES do
    local aid = CFG.HERO_REMOVE_ABILITIES[i]
    local ok = UnitRemoveAbility(u, aid)
    if report and ok then hits[#hits + 1] = API.idToStr(aid) end
  end

  if report then
    if #hits == 0 then
      API.trace("remove " .. GetUnitName(u) .. ": KHONG id nao trung " ..
                "(" .. #CFG.HERO_REMOVE_ABILITIES .. " id da thu)")
    else
      API.trace("remove " .. GetUnitName(u) .. ": go duoc " ..
                table.concat(hits, " "))
    end
  end
end

local function lockHero(u)
  if u == nil then return false end
  if not IsUnitType(u, UNIT_TYPE_HERO) then return false end

  if CFG.LOCK_HERO_XP then SuspendHeroXP(u, true) end

  local n, how = stripSkillPoints(u)
  if not S.spReported[u] then
    S.spReported[u] = true
    API.trace("skillpoint " .. GetUnitName(u) .. ": rut " .. n .. " diem (" .. how .. ")")
  end

  dumpAbilities(u)
  removeStockAbilities(u)
  return true
end

-- Quet moi unit trong vung choi duoc. Bat duoc ca nhung hero sinh ra o
-- cho code nay khong goi toi.
local function sweepHeroes()
  if not (CFG.LOCK_HERO_XP or CFG.STRIP_SKILL_POINTS) then return 0 end
  local g = CreateGroup()
  GroupEnumUnitsInRect(g, bj_mapInitialPlayableArea, nil)

  local n = 0
  local u = FirstOfGroup(g)
  while u ~= nil do
    GroupRemoveUnit(g, u)
    if lockHero(u) then n = n + 1 end
    u = FirstOfGroup(g)
  end

  DestroyGroup(g)
  return n
end

local function startHeroLock()
  local n = sweepHeroes()
  API.trace("lockHero: quet dau tien khoa " .. n .. " hero")
  if CFG.HERO_XP_SWEEP > 0 then
    S.xpTimer = CreateTimer()
    TimerStart(S.xpTimer, CFG.HERO_XP_SWEEP, true, sweepHeroes)
  end
end

-- ---------- BA DONG TIEN ----------
--
--   Linh Khi   bien rieng, hien o bang phim R   <- quai thuong, 1/con
--   Vang       thanh tai nguyen VANG cua Warcraft <- quai thuong, 1/con
--   Go         thanh tai nguyen GO cua Warcraft   <- tinh anh 1, boss 5
--
-- Vi sao Linh Khi khong con nam tren thanh tai nguyen: thanh do chi co
-- HAI o ma gio co BA dong tien. Vang va Go duoc uu tien vi chung la thu
-- nguoi choi tieu lien tuc (shop moi wave, ky nang moi tinh anh); Linh
-- Khi chi tieu o DUNG MOT cho (Linh Can), nen nam trong bang la du.
--
-- Hai dong tien cu, Ngo Tinh va Tinh Thach, da bo: Ngo Tinh thanh Go,
-- con Tinh Thach khong con he nao tieu sau khi Phap Khi bi khoa -- giu
-- lai la de nguoi choi nhin mot con so tang mai ma khong bao gio dung
-- duoc. Xem docs/02-he-thong/kinh-te.md

-- ---------- Linh Khi ----------
local function addLinhKhi(pid, amount)
  if amount == nil or amount == 0 then return end
  local d = S.p[pid]
  if d == nil then return end
  d.linhKhi = (d.linhKhi or 0) + amount
  if d.linhKhi < 0 then d.linhKhi = 0 end
  if amount > 0 then
    d.linhKhiTotal = (d.linhKhiTotal or 0) + amount
    API.fctOnLinhKhi(pid, amount)
  end
end

local function getLinhKhi(pid)
  local d = S.p[pid]
  return (d ~= nil) and (d.linhKhi or 0) or 0
end

local function spendLinhKhi(pid, amount)
  if getLinhKhi(pid) < amount then return false end
  addLinhKhi(pid, -amount)
  return true
end

-- ---------- Vang (thanh tai nguyen) ----------
local function addVang(pid, amount)
  if amount == nil or amount == 0 then return end
  local p = Player(pid)
  local cur = GetPlayerState(p, PLAYER_STATE_RESOURCE_GOLD)
  local moi = cur + amount
  if moi < 0 then moi = 0 end
  SetPlayerState(p, PLAYER_STATE_RESOURCE_GOLD, moi)
end

local function getVang(pid)
  return GetPlayerState(Player(pid), PLAYER_STATE_RESOURCE_GOLD)
end

local function spendVang(pid, amount)
  if getVang(pid) < amount then return false end
  addVang(pid, -amount)
  return true
end

-- ---------- Go (thanh tai nguyen) ----------
local function addGo(pid, amount)
  if amount == nil or amount == 0 then return end
  local p = Player(pid)
  local cur = GetPlayerState(p, PLAYER_STATE_RESOURCE_LUMBER)
  local moi = cur + amount
  if moi < 0 then moi = 0 end
  SetPlayerState(p, PLAYER_STATE_RESOURCE_LUMBER, moi)
end

local function getGo(pid)
  return GetPlayerState(Player(pid), PLAYER_STATE_RESOURCE_LUMBER)
end

local function spendGo(pid, amount)
  if getGo(pid) < amount then return false end
  addGo(pid, -amount)
  return true
end

local function activeCount()
  local n = 0
  for i = 1, #S.pids do
    if S.p[S.pids[i]].active then n = n + 1 end
  end
  return n
end

API.addLinhKhi       = addLinhKhi
API.getLinhKhi       = getLinhKhi
API.spendLinhKhi     = spendLinhKhi
API.addVang          = addVang
API.getVang          = getVang
API.spendVang        = spendVang
API.addGo            = addGo
API.getGo            = getGo
API.spendGo          = spendGo
API.grantSkillPoints = grantSkillPoints
API.lockHero      = lockHero
API.sweepHeroes   = sweepHeroes
API.startHeroLock = startHeroLock
API.initPlayers = initPlayers
API.activeCount = activeCount
end
--#endregion 2_nguoi_choi/1_player.lua

--#region 2_nguoi_choi/2_heropick.lua
do
-- ============================================================
--  2_heropick.lua  --  Chon hero bang popup
--
--  Thay cho Tavern. Ly do: CreateUnit bo qua toan bo techtree --
--  khong requirement Altar, khong gia vang/go, khong luong thuc,
--  khong quay hang, khong dong ho hoi hang. Ban Tavern phai chong do
--  ca nam thu do bang nam cho va tam; popup thi khong can cai nao.
--
--  Nho: goi ham cua file khac phai qua API.
-- ============================================================

-- Nhung hero chua ai lay.
local function available()
  local out = {}
  for i = 1, #CFG.HEROES do
    local h = CFG.HEROES[i]
    if not (CFG.HERO_UNIQUE and S.heroTaken[h.id]) then
      out[#out + 1] = h
    end
  end
  return out
end

local function heroDef(uid)
  for i = 1, #CFG.HEROES do
    if CFG.HEROES[i].id == uid then return CFG.HEROES[i] end
  end
  return nil
end

-- So thu tu trong CFG.HEROES. Kenh dong bo chi cho gui so duoi 100000,
-- ma id kieu FourCC thi hon mot ti -- nen gui so thu tu roi tra nguoc
-- ra id o dau ben kia. Xem src/1_nen/3_sync.lua.
local function heroIndex(uid)
  for i = 1, #CFG.HEROES do
    if CFG.HEROES[i].id == uid then return i end
  end
  return nil
end

-- Gan ky nang luc tao. Ghi lai id nao gan that bai -- UnitAddAbility
-- tra ve false khi id khong ton tai, va that bai im lang kieu do la
-- thu kho phat hien nhat.
local function giveAbilities(u, uid)
  local def = heroDef(uid)
  local list = {}

  for i = 1, #CFG.HERO_COMMON_ABILITIES do
    list[#list + 1] = CFG.HERO_COMMON_ABILITIES[i]
  end
  if def ~= nil and def.abilities ~= nil then
    for i = 1, #def.abilities do list[#list + 1] = def.abilities[i] end
  end

  -- Ky nang hero: CHI nhung cai da mo khoa. Khong hoc bang diem, mua
  -- bang Linh Khi trong bang phim E. Xem
  -- docs/03-du-lieu/nang-cap-ky-nang.md
  local sk = CFG.SKILLS[uid]
  if sk ~= nil then
    local n = CFG.SKILL_START_COUNT
    if n > #sk then n = #sk end
    for i = 1, n do list[#list + 1] = sk[i].id end
  end

  local bad = {}
  for i = 1, #list do
    if UnitAddAbility(u, list[i]) then
      -- Ability nhan ban tu HERO ability ra o cap 0: nut hien nhung bam
      -- khong duoc. Ability thuong von da cap 1, goi them la vo hai.
      SetUnitAbilityLevel(u, list[i], 1)
    else
      bad[#bad + 1] = API.idToStr(list[i])
    end
  end

  if #bad > 0 then
    API.msg(nil, CFG.C_RED .. "Khong gan duoc ability: " ..
      table.concat(bad, " ") .. CFG.C_END)
  end
  API.trace("abil gan cho " .. GetUnitName(u) .. ": " .. (#list - #bad) ..
            "/" .. #list)
end

local function heroNameOf(uid)
  for i = 1, #CFG.HEROES do
    if CFG.HEROES[i].id == uid then return CFG.HEROES[i].name end
  end
  return "?"
end

local function slotIndex(pid)
  for i = 1, #S.pids do
    if S.pids[i] == pid then return i end
  end
  return 1
end

-- Hero sinh quanh nha chinh, moi nguoi mot huong de khong chong len nhau.
local function spawnHero(pid, uid)
  local cx, cy = S.houseX, S.houseY
  if cx == nil then cx, cy = API.blockCenter(3, 3) end

  local n = #S.pids
  if n < 1 then n = 1 end
  local ang = (360.0 / n) * (slotIndex(pid) - 1)
  local x = API.polarX(cx, CFG.HERO_SPAWN_OFFSET, ang)
  local y = API.polarY(cy, CFG.HERO_SPAWN_OFFSET, ang)
  x, y = API.clampToMap(x, y)

  local u = CreateUnit(Player(pid), uid, x, y, ang + 180.0)
  if u ~= nil then
    API.lockHero(u)
    giveAbilities(u, uid)
    -- THU TU QUAN TRONG. Doc chi so NEN cua hero moi TRUOC khi bat cu
    -- he nao cong vao -- doc sau la doc phai con so da cong roi, va moi
    -- lan doi hero se nhan chong them mot lan.
    API.heroBaseCapture(pid)
    API.skillApply(pid)          -- dat lai bac cho dung bang da mua
    API.heroRecomputeAll()       -- Linh Can + Trang Bi + bi dong + aura
    API.waveReadyCheck()       -- du nguoi thi vao dot 1 ngay, khoi cho
    if CFG.SKILL_MODE == "learn" then
      API.grantSkillPoints(u, CFG.SKILL_POINTS_START)
    end
    SelectUnitAddForPlayer(u, Player(pid))
    PanCameraToTimedForPlayer(Player(pid), x, y, 0.0)
  end
  return u
end

local function hidePicker(pid)
  local slot = S.pick[pid]
  if slot ~= nil and slot.dlg ~= nil then
    DialogDisplay(Player(pid), slot.dlg, false)
  end
end

-- Dung lai popup cho mot nguoi. Goi lai moi khi danh sach doi -- nguoi
-- khac vua lay mat mot con thi con do phai bien khoi popup cua ta.
local function showPicker(pid)
  local d = S.p[pid]
  if d == nil or not d.active then return end
  if CFG.HERO_MAX_PER_PLAYER > 0 and d.heroCount >= CFG.HERO_MAX_PER_PLAYER then
    hidePicker(pid)
    return
  end

  local list = available()
  if #list == 0 then
    hidePicker(pid)
    API.msg(pid, CFG.C_RED .. "Khong con hero nao de chon." .. CFG.C_END)
    return
  end

  local slot = S.pick[pid]
  if slot == nil then
    slot = { dlg = DialogCreate(), map = {} }
    S.pick[pid] = slot
    TriggerRegisterDialogEvent(S.pickTrigger, slot.dlg)
  end

  -- DialogClear huy cac nut cu, nen bang anh xa phai dung lai tu dau.
  DialogClear(slot.dlg)
  slot.map = {}
  DialogSetMessage(slot.dlg, API.t("pick_title"))
  for i = 1, #list do
    local btn = DialogAddButton(slot.dlg, list[i].name, 0)
    slot.map[btn] = list[i].id
  end

  DialogDisplay(Player(pid), slot.dlg, true)
end

-- ---------- Dieu huong: popup chu hay giao dien card ----------
-- Hai duong cung dung mot logic chon hero ben duoi; chi khac cach ve.

local function pickerShow(pid)
  if CFG.HERO_PICK_MODE == "frame" and API.showHeroFrame ~= nil then
    return API.showHeroFrame(pid)
  end
  return showPicker(pid)
end

local function pickerHide(pid)
  if API.hideHeroFrame ~= nil then API.hideHeroFrame(pid) end
  hidePicker(pid)
end

-- Hien lai cho nhung nguoi chua chon, sau khi danh sach thay doi -- ai
-- do vua lay mat mot con thi con do phai bien khoi man hinh nguoi khac.
local function refreshOthers(exceptPid)
  for i = 1, #S.pids do
    local pid = S.pids[i]
    local d = S.p[pid]
    if pid ~= exceptPid and d ~= nil and d.hero == nil then
      pickerShow(pid)
    end
  end
end

-- Ap dung mot lua chon hero.
--
-- Day la NOI DUY NHAT doi trang thai khi chon hero. Ca popup dialog lan
-- giao dien card deu goi vao day, nen luat "moi nguoi mot con, khong ai
-- lay trung" chi ton tai o mot cho.
--
-- Voi giao dien card, ham nay duoc goi tu su kien DONG BO nen no chay
-- tren moi may. Voi dialog thi su kien von da dong bo san.
local function applyHeroPick(pid, uid)
  local d = S.p[pid]
  if d == nil then return false end

  if CFG.HERO_MAX_PER_PLAYER > 0 and d.heroCount >= CFG.HERO_MAX_PER_PLAYER then
    pickerHide(pid)
    return false
  end

  -- Hai nguoi bam cung mot con: nguoi den sau roi vao day.
  if CFG.HERO_UNIQUE and S.heroTaken[uid] then
    API.msg(pid, CFG.C_RED .. heroNameOf(uid) .. " vua co nguoi lay mat." .. CFG.C_END)
    pickerShow(pid)
    return false
  end

  local u = spawnHero(pid, uid)
  if u == nil then
    API.msg(pid, CFG.C_RED .. "Khong tao duoc hero -- kiem tra id trong CFG.HEROES."
      .. CFG.C_END)
    pickerShow(pid)
    return false
  end

  d.hero = u
  d.heroCount = d.heroCount + 1
  if CFG.HERO_UNIQUE then S.heroTaken[uid] = true end
  pickerHide(pid)

  -- Qua khoi dau, phat SAU KHI CO HERO chu khong luc vao map.
  --
  -- Truoc day Go phat trong initPlayers, tuc truoc khi ai kip chon hero.
  -- Do la sai thu tu: qua la cua HERO, ma luc do hero chua ton tai --
  -- lo do voi vat pham thi khong co tui nao de bo vao.
  --
  -- Chi phat cho lan pick DAU TIEN. Doi hero (heroCount > 1) ma phat
  -- lai la mot duong de nhan qua vo han.
  if d.heroCount == 1 then
    if CFG.GO_START ~= nil and CFG.GO_START > 0 then
      API.addGo(pid, CFG.GO_START)
    end
    if CFG.START_ITEMS ~= nil and API.shopGive ~= nil then
      for k = 1, #CFG.START_ITEMS do
        local q = CFG.START_ITEMS[k]
        API.shopGive(pid, q.ma, q.so)
      end
    end
  end

  API.msg(nil, API.t("pick_done",
    CFG.C_GOLD .. GetPlayerName(Player(pid)) .. CFG.C_END,
    CFG.C_JADE .. heroNameOf(uid) .. CFG.C_END))

  refreshOthers(pid)
  return true
end

local function onPick()
  local pid  = GetPlayerId(GetTriggerPlayer())
  local slot = S.pick[pid]
  if slot == nil then return end

  local uid = slot.map[GetClickedButton()]
  if uid == nil then return end

  applyHeroPick(pid, uid)
end

local function startPicking()
  S.pickTrigger = CreateTrigger()
  TriggerAddAction(S.pickTrigger, onPick)

  API.after(CFG.PICK_DELAY, function()
    for i = 1, #S.pids do pickerShow(S.pids[i]) end
    API.trace("heropick: da hien bang chon cho " .. #S.pids .. " nguoi (che do " ..
              tostring(CFG.HERO_PICK_MODE) .. ")")
  end)
end


-- ============================================================
--  Chon ky nang theo slot
--
--  Moi slot la mot o trong command card. Nguoi choi chon mot ability
--  trong so ung vien cua slot do, va no duoc gan thang bang
--  UnitAddAbility -- khong ton diem ky nang, khong can Techtree.
--
--  Han che phai biet: nut popup cua Warcraft III chi hien CHU, khong
--  hien icon. Muon co icon thi phai dung nut + goc (Techtree - Hero
--  Abilities), va luc do slot do vi tri nut cua ability quyet dinh chu
--  khong phai nguoi choi chon.
-- ============================================================

-- Cay skill cua hero nguoi choi dang cam, lui ve cay chung neu hero do
-- khong khai bao rieng.
local function slotsFor(pid)
  local d = S.p[pid]
  if d ~= nil and d.hero ~= nil then
    local def = heroDef(GetUnitTypeId(d.hero))
    if def ~= nil and def.skills ~= nil and #def.skills > 0 then
      return def.skills
    end
  end
  return CFG.SKILL_SLOTS
end

local function slotDone(d, i)
  return d.slots ~= nil and d.slots[i] ~= nil
end

local function nextEmptySlot(d, slots)
  for i = 1, #slots do
    if not slotDone(d, i) then return i end
  end
  return nil
end

local function hideSkillPicker(pid)
  local sp = S.skillPick[pid]
  if sp ~= nil and sp.dlg ~= nil then
    DialogDisplay(Player(pid), sp.dlg, false)
  end
end

local function showSkillPicker(pid)
  local d = S.p[pid]
  if d == nil or not d.active then return false end

  if d.hero == nil then
    API.msg(pid, CFG.C_RED .. "Chua co hero de gan ky nang." .. CFG.C_END)
    return false
  end
  local slots = slotsFor(pid)
  if #slots == 0 then
    API.msg(pid, CFG.C_RED .. "Hero nay chua khai bao cay skill nao." .. CFG.C_END)
    return false
  end

  local si = nextEmptySlot(d, slots)
  if si == nil then
    hideSkillPicker(pid)
    API.msg(pid, CFG.C_GOLD .. "Da chon du " .. #slots .. " slot ky nang."
      .. CFG.C_END)
    return false
  end

  local slot = slots[si]
  local sp = S.skillPick[pid]
  if sp == nil then
    sp = { dlg = DialogCreate(), map = {}, slot = si }
    S.skillPick[pid] = sp
    TriggerRegisterDialogEvent(S.skillTrigger, sp.dlg)
  end
  sp.slot = si

  DialogClear(sp.dlg)
  sp.map = {}
  DialogSetMessage(sp.dlg, slot.name or ("Slot " .. si))
  for i = 1, #slot.choices do
    local c = slot.choices[i]
    local btn = DialogAddButton(sp.dlg, c.name, 0)
    sp.map[btn] = c.id
  end

  DialogDisplay(Player(pid), sp.dlg, true)
  return true
end

local function onSkillPick()
  local p   = GetTriggerPlayer()
  local pid = GetPlayerId(p)
  local sp  = S.skillPick[pid]
  if sp == nil then return end

  local aid = sp.map[GetClickedButton()]
  if aid == nil then return end

  local d = S.p[pid]
  if d == nil or d.hero == nil then return end

  if not UnitAddAbility(d.hero, aid) then
    API.msg(pid, CFG.C_RED .. "Khong gan duoc ability " .. API.idToStr(aid) ..
      " -- id sai, hoac unit khong nhan duoc ability nay." .. CFG.C_END)
    showSkillPicker(pid)
    return
  end

  -- HERO ability gan thang bang UnitAddAbility ra o CAP 0: nut hien
  -- nhung bam khong duoc. Phai nang len cap 1 moi dung duoc.
  -- Ability thuong von da o cap 1, goi them la vo hai.
  SetUnitAbilityLevel(d.hero, aid, 1)

  d.slots[sp.slot] = aid
  hideSkillPicker(pid)
  API.msg(pid, CFG.C_GOLD .. "Da hoc " .. CFG.C_JADE ..
    (slotsFor(pid)[sp.slot].name or "?") .. CFG.C_END .. ".")

  if CFG.SKILL_PICK_CHAIN then showSkillPicker(pid) end
end

local function startSkillPicking()
  S.skillTrigger = CreateTrigger()
  TriggerAddAction(S.skillTrigger, onSkillPick)
end

-- ---------- Nap truoc model hero ----------
--
-- Warcraft nap model cua nhung LOAI unit co mat tren map luc vao game.
-- Loai nao khong xuat hien o dau thi model nap theo yeu cau -- va model
-- tu import nap kieu do thi hong: unit hien ra den si, khong loi nao bao.
--
-- Do duoc: cung mot H001, con dat san trong World Editor thi co mau, con
-- tao bang CreateUnit luc chay thi den.
--
-- Cach chua: tao mot con moi loai luc khoi dong roi xoa ngay. Engine da
-- nap model roi thi lan tao sau khong con phai nap theo yeu cau nua.
local function preloadHeroes()
  local x, y = API.blockCenter(3, 3)
  local n = 0
  for i = 1, #CFG.HEROES do
    local u = CreateUnit(Player(bj_PLAYER_NEUTRAL_EXTRA), CFG.HEROES[i].id,
                         x, y, 270.0)
    if u ~= nil then
      ShowUnit(u, false)
      RemoveUnit(u)
      n = n + 1
    end
  end
  API.trace("heropick: nap truoc model cho " .. n .. "/" .. #CFG.HEROES .. " hero")
end

API.preloadHeroes     = preloadHeroes
API.heroesAvailable   = available
API.heroNameOf        = heroNameOf
API.heroDef           = heroDef
API.heroIndex         = heroIndex
API.applyHeroPick     = applyHeroPick
API.pickerShow        = pickerShow
API.slotsFor          = slotsFor
API.showSkillPicker   = showSkillPicker
API.startSkillPicking = startSkillPicking

local function report()
  API.msg(nil, CFG.C_GOLD .. "=== Chon hero ===" .. CFG.C_END)
  API.msg(nil, #CFG.HEROES .. " hero  |  moi nguoi toi da " ..
    CFG.HERO_MAX_PER_PLAYER .. "  |  " ..
    (CFG.HERO_UNIQUE and "khong trung nhau" or "duoc trung nhau"))
  API.msg(nil, "Popup hien sau " .. CFG.PICK_DELAY .. "s, hero sinh cach nha chinh " ..
    API.num(CFG.HERO_SPAWN_OFFSET))
end

API.showPicker    = showPicker
API.startPicking  = startPicking
API.heroPickReport = report
end
--#endregion 2_nguoi_choi/2_heropick.lua

--#region 2_nguoi_choi/3_linhcan.lua
do
-- ============================================================
--  3_linhcan.lua  --  Linh Can (tu vi cua nguoi choi)
--
--  Nguon suc manh LON NHAT: x20 trong hop dong x967
--  (docs/03-du-lieu/duong-cong-suc-manh.md). 20 bac, dung chung thang
--  ten voi 20 canh gioi cua phe dich.
--
--  File nay KHONG ve bang. No dang ky mot the vao bang nhan vat
--  (1_panel.lua) va chi lo phan noi dung. Nho vay bon he dung chung
--  mot khung, khong the lech nhau ve giao dien.
--
--  Nho: goi ham cua file khac phai qua API.
-- ============================================================

-- The nay dung kieu "focus" cua bang: MOT the lon, MOT hanh dong.
--
-- Truoc day no la mot cai thang 7 dong. Nhung trong 7 dong do chi co
-- DUNG MOT dong bam duoc -- bac ke tiep. Sau dong con lai la thong tin
-- tham khao chen cho dung mot viec lam duoc, va nguoi choi phai do mat
-- tim xem dong nao moi la dong cua minh.
--
-- Bang 20 bac van con, nhung no thuoc ve tai lieu
-- (docs/03-du-lieu/canh-gioi.md) chu khong phai giao dien.

-- ---------- Toan ----------

local function maxRank() return #CFG.REALMS end

local function rankName(r)
  return API.pick(CFG.REALMS[r])
end

local function powerAt(r) return CFG.LINHCAN_STEP ^ (r - 1) end

-- GIAI NGUOC, khong nhan thang. Sat thuong hero = sat thuong nen + chi
-- so, nen nhan thang chi so len x1.17 moi bac chi cho x10.4 sat thuong
-- sau 20 bac -- thieu mot nua. Cong thuc nay bu lai phan nen.
local function statAt(r)
  local b = CFG.LINHCAN_DMG_BASE
  return (b + CFG.LINHCAN_STAT_BASE) * powerAt(r) - b
end

local function costOf(r)
  return math.floor(CFG.LINHCAN_COST_BASE * CFG.LINHCAN_COST_STEP ^ (r - 1) + 0.5)
end

-- Linh Can KHONG tu ghi chi so nua. No chi tra loi mot cau: "tu vi cong
-- them bao nhieu diem so voi bac 1?"
--
-- API.heroRecompute trong 7_hieuung.lua la cho DUY NHAT ghi chi so hero
-- -- no cong nen + so nay, roi nhan % cua bi dong, roi ghi mot lan. Truoc
-- day moi he tu cong vao, va hai he cung ghi mot thuoc tinh thi lech.
--
-- CFG.LINHCAN_STAT_MODE quyet dinh cong vao chi so nao; phan do do
-- recompute lo.
local function statBonus(pid)
  local d = S.p[pid]
  if d == nil then return 0 end
  return math.floor(statAt(d.linhCan) - statAt(1) + 0.5)
end

-- ---------- Noi dung the ----------
--
-- Cai nguoi choi can biet la TRUOC -> SAU va GIA. Khong phai ca bang.
local function tabInfo(pid)
  local d = S.p[pid]
  if d == nil then return {} end

  local cur = d.linhCan
  local top = maxRank()
  local out = {
    tieuDe = API.t("lc_rank", cur, top),
    phu    = rankName(cur),
    tienDo = cur / top,
  }

  if cur >= top then
    out.dong = {
      { API.t("lc_power"), string.format("x%.2f", powerAt(cur)), "" },
      { API.t("lc_stat"),
        "+" .. API.num(statAt(cur) - CFG.LINHCAN_STAT_BASE), "" },
    }
    out.ghiChu = API.t("lc_peak")
    return out
  end

  local gia = costOf(cur)
  out.dong = {
    { API.t("lc_power"),
      string.format("x%.2f", powerAt(cur)),
      string.format("x%.2f", powerAt(cur + 1)) },
    { API.t("lc_stat"),
      "+" .. API.num(statAt(cur)     - CFG.LINHCAN_STAT_BASE),
      "+" .. API.num(statAt(cur + 1) - CFG.LINHCAN_STAT_BASE) },
    { API.t("col_realm"), rankName(cur), rankName(cur + 1) },
  }
  out.nut    = API.t("lc_next", rankName(cur + 1)) .. "     " ..
               API.num(gia) .. " " .. API.t("cur_lk")
  out.batNut = (API.getLinhKhi(pid) >= gia)
  out.ghiChu = API.t("lc_have", API.num(API.getLinhKhi(pid)))
  return out
end

-- ---------- Dot pha ----------
-- setRank/breakthrough chay tren MOI may, tu su kien dong bo.

local function setRank(pid, newR, dev)
  local d = S.p[pid]
  if d == nil then return end
  if newR < 1 then newR = 1 end
  if newR > maxRank() then newR = maxRank() end

  local old = d.linhCan
  if newR == old then return end

  d.linhCan = newR
  API.heroRecompute(pid)
  API.panelRefresh(pid)

  if dev then
    API.msg(pid, CFG.C_GREY .. "[dev] Linh Can -> " .. rankName(newR) ..
      " (bac " .. newR .. ", x" .. string.format("%.2f", powerAt(newR)) .. ")" .. CFG.C_END)
  end
end

local function breakthrough(pid)
  local d = S.p[pid]
  if d == nil then return end

  local r = d.linhCan
  if r >= maxRank() then
    API.msg(pid, CFG.C_GREY .. API.t("lc_peak") .. CFG.C_END)
    return
  end

  local c = costOf(r)
  if not API.spendLinhKhi(pid, c) then
    API.msg(pid, CFG.C_RED .. API.t("no_qi") .. CFG.C_END ..
      API.t("need_have", API.num(c), API.num(API.getLinhKhi(pid))))
    API.panelRefresh(pid)
    return
  end

  setRank(pid, r + 1, false)
  API.msg(nil, API.t("lc_broke",
    CFG.C_GOLD .. GetPlayerName(Player(pid)) .. CFG.C_END,
    CFG.C_JADE .. rankName(r + 1) .. CFG.C_END) ..
    " (x" .. string.format("%.2f", powerAt(r + 1)) .. ")")

  if d.hero ~= nil then
    API.fx([[Abilities\Spells\Human\Resurrect\ResurrectTarget.mdl]],
           GetUnitX(d.hero), GetUnitY(d.hero))
  end
end

-- Nut "Dot pha" tren bang: KHONG doi trang thai o day. Su kien bam frame
-- chi no tren may nguoi bam, nen chi gui mot tin -- 02b_sync lo phan con
-- lai. breakthrough() ben duoi chay tren MOI may, cung mot nhip.
local function tabAction(pid)
  API.syncSend(pid, CFG.OP_LC_UP, 0)
end

-- "-lc" mo the Linh Can · "-lc up" dot pha · "-lc <so>" nhay bac (dev)
--
-- Lenh chat KHONG can di qua 02b_sync: su kien chat von da no tren moi
-- may cung luc. Goi thang la dung, va do la ly do lenh chat luon chay
-- duoc ke ca khi khong con duong dong bo nao.
local function onChat(pid, raw)
  if raw ~= nil and raw:match("^%s*%-lc%s+up") then
    breakthrough(pid)
    return
  end

  if raw ~= nil then
    local n = tonumber(raw:match("^%s*%-lc%s+(%d+)"))
    if n ~= nil then
      if not CFG.DEV_COMMANDS then
        API.msg(pid, CFG.C_RED .. "Lenh dev dang tat (CFG.DEV_COMMANDS)." .. CFG.C_END)
        return
      end
      setRank(pid, n, true)
      return
    end
  end

  API.panelOpenTab(pid, S.lcTabIndex or 1)
end

local function startLinhCan()
  S.lcTabIndex = API.panelAddTab({
    ten    = API.t("panel_root"),
    kind   = "focus",
    info   = tabInfo,
    action = tabAction,
  })

  API.syncOn(CFG.OP_LC_UP,  function(pid) breakthrough(pid) end)
  API.syncOn(CFG.OP_LC_SET, function(pid, arg) setRank(pid, arg, true) end)

  API.trace("linhcan: the so " .. S.lcTabIndex .. ", dong bo=" .. API.syncMode())
end

-- Goi khi hero vua duoc tao. Khong con lam gi rieng: recompute doc
-- statBonus roi tu ap. Giu ten de cho goi cu khong gay.
local function applyToHero(pid, hero)
  API.heroRecompute(pid)
end

API.linhCanRank   = function(pid) return S.p[pid] and S.p[pid].linhCan or 1 end
API.linhCanPower  = function(pid) return powerAt(API.linhCanRank(pid)) end
API.linhCanCost   = costOf
API.linhCanStatAt = statAt
API.linhCanStatBonus = statBonus
API.linhCanChat   = onChat
API.linhCanApply  = applyToHero
API.startLinhCan  = startLinhCan
end
--#endregion 2_nguoi_choi/3_linhcan.lua

--#region 2_nguoi_choi/4_skill.lua
do
-- ============================================================
--  4_skill.lua  --  Bay ky nang: bac, gia nang, suc manh moi bac
--
--  MOI so lieu ky nang o day, khong o Object Editor. war3map.w3a chi
--  giu VO: ten, icon, o nut, so bac. Nho vay chinh can bang khong phai
--  build lai file nhi phan nao -- va so lieu voi tooltip ra tu cung mot
--  bang nen khong the lech nhau.
--
--  HAI QUY TAC, ca hai deu tu do ma ra:
--
--  1. Sat thuong an theo CHI SO CAO NHAT cua hero, khong phai so co dinh.
--     Linh Can cong +1075 moi chi so o bac 20; skill gay so co dinh thi
--     cuoi game thanh vo nghia.
--
--  2. Ky nang bi dong tinh theo PHAN TRAM. Cung ly do: cong thang +20
--     chi so nghe to luc dau (+100%) nhung chi con +5% o Linh Can bac 20.
--
--  Nho: goi ham cua file khac phai qua API.
-- ============================================================

local function listOf(pid)
  local d = S.p[pid]
  if d == nil or d.hero == nil then return {} end
  return CFG.SKILLS[GetUnitTypeId(d.hero)] or {}
end

-- ---------- So bac THAT cua ability ----------
--
-- Object Editor moi la nguoi quyet dinh mot ability co bao nhieu bac.
-- Ability hero mac dinh 3 bac, ability unit thuong 1 bac. Goi
-- SetUnitAbilityLevel(u, aid, 10) len mot ability 3 bac thi no KEP
-- xuong 3 va KHONG bao loi gi.
--
-- Da can mot lan: nang skill len bac 10, tra du tien, bang bao 10/10,
-- ma trong game chi len bac 3. Nen gio do that roi moi cho nang.
local function probeMax(u, aid)
  local cur = GetUnitAbilityLevel(u, aid)
  if cur == 0 then return 0 end
  SetUnitAbilityLevel(u, aid, CFG.SKILL_MAX_LEVEL)
  local hi = GetUnitAbilityLevel(u, aid)
  SetUnitAbilityLevel(u, aid, cur)
  return hi
end

-- Tran that: nho hon giua "thiet ke muon" va "Object Editor cho".
local function maxOf(aid)
  local m = S.skillMax[aid]
  if m == nil or m <= 0 then return CFG.SKILL_MAX_LEVEL end
  if m < CFG.SKILL_MAX_LEVEL then return m end
  return CFG.SKILL_MAX_LEVEL
end

-- Bac 0 = CHUA MO KHOA. Bac 1..10 = da co.
local function levelOf(pid, aid, index)
  local d = S.p[pid]
  if d ~= nil and d.skill ~= nil and d.skill[aid] ~= nil then
    return d.skill[aid]
  end
  -- Chua mua gi: nhung cai dau tien co san, con lai khoa.
  if index ~= nil and index <= CFG.SKILL_START_COUNT then return 1 end
  return 0
end

-- Gia mo khoa theo SO CAI DA MO, khong theo cai nao. Thich mo cai nao
-- truoc thi mo -- ep thu tu la lay mat mot lua chon ma chang duoc gi.
-- Gia tinh bang NGO TINH, va la MOT diem cho moi lan.
--
-- Ky nang bi chan boi "da giet du tinh anh chua", khong phai "da gom du
-- tien chua" -- ma tien thi Linh Can va Trang Bi da tranh nhau roi.
-- Xem docs/02-he-thong/kinh-te.md
--
-- Gia phang nen khong con ham unlockCost: mo khoa cai thu nhat hay cai
-- thu bay deu 1 diem. Nguoi choi khong phai tinh toan gi, chi phai chon
-- THU TU -- mo cai nao truoc, don bac cai nao.
local function costOf(pid, level, aid)
  if level <= 0 then return CFG.SKILL_GO_UNLOCK end
  if level >= (aid and maxOf(aid) or CFG.SKILL_MAX_LEVEL) then return nil end
  return CFG.SKILL_GO_UP
end

-- ---------- Suc manh theo bac ----------
-- Ngan sach ca he nang cap la x2, va x2 do la TICH cua moi nut chinh.
-- Chu dong: he so x1.33 va hoi chieu x0.667 (tan suat x1.5) = x2.
-- Bi dong khong co hoi chieu nen an tron x2.

local function heSoAt(sk, level)
  return (sk.heSo or 0) * CFG.SKILL_DMG_STEP ^ (level - 1)
end

local function cdAt(sk, level)
  return (sk.cd or 0) * CFG.SKILL_CD_STEP ^ (level - 1)
end

local function pctAt(sk, level)
  return (sk.pct or 0) * CFG.SKILL_PASSIVE_STEP ^ (level - 1)
end

-- Giap PHANG cua aura. Dung buoc bi dong nhu pct: 3.0 -> 6.0 sau 9 lan.
--
-- Rieng mot ham chu khong dung pctAt vi day la GIAP, khong phai phan
-- tram. Warcraft dung giap phang; "+15% giap" tren hero co 3 giap la
-- +0.45 -- gan nhu bang khong.
local function giapAt(sk, level)
  return (sk.giap or 0) * CFG.SKILL_PASSIVE_STEP ^ (level - 1)
end

local function manaAt(sk, level)
  if sk.mana == nil or sk.mana <= 0 then return 0 end
  return math.floor(sk.mana * CFG.SKILL_MANA_STEP ^ (level - 1) + 0.5)
end

-- Chi so cao nhat cua hero. Dung CHUNG cho moi skill, nen doi hero hay
-- doi trang bi deu khong lam skill nao bi bo lai.
local function topStat(u)
  if u == nil then return 0 end
  local s, a, i = GetHeroStr(u, true), GetHeroAgi(u, true), GetHeroInt(u, true)
  if s >= a and s >= i then return s, "str" end
  if a >= i then return a, "agi" end
  return i, "int"
end

-- Sat thuong/hoi mau cua mot skill. Day la ham ma cac skill se goi khi
-- co hieu ung that.
local function skillDamage(u, heSo)
  return heSo * (CFG.LINHCAN_DMG_BASE + topStat(u))
end

-- ---------- Nang bac ----------
-- Chay tren MOI may, tu kenh dong bo.

local function applyLevel(pid, sk, level)
  local d = S.p[pid]
  if d == nil or d.hero == nil then return end
  if GetUnitAbilityLevel(d.hero, sk.id) <= 0 then return end

  SetUnitAbilityLevel(d.hero, sk.id, level)

  -- Mana va hoi chieu dat TU LUA, de o Object Editor thi chinh can bang
  -- phai mo World Editor. Ca hai native nay deu co tren 1.31.1 (-nat).
  -- Dat cho MOI bac, khong chi bac hien tai: unit nho bac nao thi doc
  -- bac do, va ta khong biet no se nhay len bac nao truoc khi ta kip
  -- goi lai.
  local tran = maxOf(sk.id)

  -- TAT hieu ung GOC. Xem CFG.SKILL_TAT_GOC.
  --
  -- Dat cho MOI bac, cung ly do voi mana/hoi chieu ben duoi. Hang so nao
  -- khong co trong ban nay thi GHI VET chu khong lang le bo qua -- mot
  -- cai ten go sai tra ve nil va khong lam gi ca (ADR 0012).
  local ab = (BlzGetUnitAbility ~= nil) and BlzGetUnitAbility(d.hero, sk.id) or nil

  local function tat(bang, dat)
    local zero = bang and bang[sk.id] or nil
    if zero == nil or ab == nil or dat == nil then return end
    for k = 1, #zero do
      local F = _G[zero[k]]
      if F == nil then
        API.trace("skill: KHONG co hang so " .. zero[k] ..
                  " -- hieu ung goc VAN CHAY")
      else
        for lv = 1, tran do dat(ab, F, lv - 1, 0) end
      end
    end
  end

  tat(CFG.SKILL_TAT_GOC,     BlzSetAbilityRealLevelField)
  tat(CFG.SKILL_TAT_GOC_INT, BlzSetAbilityIntegerLevelField)

  -- GHI so can bang vao truong goc, de Warcraft tu cong. Xem
  -- CFG.SKILL_CHO_GOC -- day la duong thay cho BlzSetUnitArmor, thu da
  -- dong bang phan chi so vao giap.
  local cho = CFG.SKILL_CHO_GOC and CFG.SKILL_CHO_GOC[sk.id] or nil
  if cho ~= nil and ab ~= nil and BlzSetAbilityRealLevelField ~= nil then
    local F = _G[cho.truong]
    if F == nil then
      API.trace("skill: KHONG co hang so " .. cho.truong ..
                " -- " .. API.idToStr(sk.id) .. " khong cong duoc giap")
    else
      for lv = 1, tran do
        local v = 0.0
        if cho.nguon == "giap" then
          v = giapAt(sk, lv)
        elseif cho.nguon == "buffgiap" then
          v = CFG.FX_BUFF_ARMOR * (1 + 0.1 * (lv - 1))
        end
        BlzSetAbilityRealLevelField(ab, F, lv - 1, v)
      end
    end
  end

  for lv = 1, tran do
    if BlzSetUnitAbilityManaCost ~= nil and sk.mana ~= nil then
      BlzSetUnitAbilityManaCost(d.hero, sk.id, lv - 1, manaAt(sk, lv))
    end
    if BlzSetUnitAbilityCooldown ~= nil and sk.cd ~= nil and sk.cd > 0 then
      BlzSetUnitAbilityCooldown(d.hero, sk.id, lv - 1, cdAt(sk, lv))
    end
  end
end

local function upgrade(pid, index)
  local list = listOf(pid)
  local sk = list[index]
  if sk == nil then return end

  local d = S.p[pid]
  if d.skill == nil then d.skill = {} end

  local cur = levelOf(pid, sk.id, index)
  local tran = maxOf(sk.id)
  local gia = costOf(pid, cur, sk.id)
  if gia == nil then
    if tran < CFG.SKILL_MAX_LEVEL then
      -- Khong tru tien. Bao dung cho phai sua, dung de nguoi choi doan.
      API.msg(pid, CFG.C_RED ..
        API.t("skill_oemissing", API.pick(sk), tran) .. CFG.C_END ..
        API.t("skill_oefix", CFG.SKILL_MAX_LEVEL, CFG.SKILL_MAX_LEVEL,
              API.idToStr(sk.id)))
    else
      API.msg(pid, CFG.C_GREY .. API.t("skill_atmax", API.pick(sk)) .. CFG.C_END)
    end
    return
  end
  if not API.spendGo(pid, gia) then
    API.msg(pid, CFG.C_RED .. API.t("no_go") .. CFG.C_END ..
      API.t("need_have", API.num(gia), API.num(API.getGo(pid))) ..
      CFG.C_GREY .. " " .. API.t("ngo_note") .. CFG.C_END)
    API.panelRefresh(pid)
    return
  end

  d.skill[sk.id] = cur + 1

  -- Tu bac 0 len 1 la MO KHOA: phai gan ability vao unit truoc da.
  if cur == 0 then
    if UnitAddAbility(d.hero, sk.id) then
      SetUnitAbilityLevel(d.hero, sk.id, 1)
      S.skillMax[sk.id] = probeMax(d.hero, sk.id)
      SetUnitAbilityLevel(d.hero, sk.id, 1)
      -- PHAI goi applyLevel o day nua. Truoc day nhanh mo khoa return
      -- thang, nen mana va hoi chieu cua ability giu nguyen so cua
      -- Object Editor -- Chuong la ban sao cua Shockwave nen no doi 100
      -- mana trong khi bang ghi 25, va hero chi co 75 mana. Bang noi mot
      -- dang, game lam mot neo.
      applyLevel(pid, sk, 1)
      API.skillFxRecompute(pid)   -- vua mo khoa mot bi dong
    else
      API.msg(pid, CFG.C_RED .. "Khong gan duoc " .. API.idToStr(sk.id) ..
        CFG.C_END)
    end
    API.msg(nil, API.t("skill_unlocked",
      CFG.C_GOLD .. GetPlayerName(Player(pid)) .. CFG.C_END,
      CFG.C_JADE .. API.pick(sk) .. CFG.C_END))
    API.panelRefresh(pid)
    return
  end

  applyLevel(pid, sk, cur + 1)
  API.skillFxRecompute(pid)   -- bi dong "stat"/"aura" tinh lai theo bac moi

  -- Doc lai bac THAT tren unit. Neu no khong bang bac vua mua thi bang
  -- dang noi doi, va tha nguoi choi biet ngay con hon phat hien sau
  -- muoi lan nang nua.
  local that = (d.hero ~= nil) and GetUnitAbilityLevel(d.hero, sk.id) or (cur + 1)
  if that ~= cur + 1 then
    API.msg(pid, CFG.C_RED ..
      API.t("skill_warn", API.pick(sk), that, cur + 1) .. CFG.C_END)
  end
  API.msg(pid, API.t("skill_up", CFG.C_JADE .. API.pick(sk) .. CFG.C_END,
                     cur + 1, tran))
  API.panelRefresh(pid)
end

-- ---------- The "Ky Nang" trong bang phim E ----------

local function fmt(sk, level)
  if sk.giap ~= nil then
    return "+" .. string.format("%.0f", giapAt(sk, level))
  end
  if sk.loai == "aura" or sk.loai == "bidong" then
    return string.format("%.0f%%", pctAt(sk, level) * 100)
  end
  return "x" .. string.format("%.2f", heSoAt(sk, level))
end

-- Icon lay THANG tu ability, khong go duong dan trong bang. Go tay thi
-- sai mot chu la hien o xanh la, ma khong ai biet sai o dau.
local function iconOf(sk)
  if sk.icon ~= nil then return sk.icon end
  if BlzGetAbilityIcon == nil then return nil end
  local p = BlzGetAbilityIcon(sk.id)
  if p == nil or p == "" then return nil end
  return p
end

-- Mot dong mo ta: hieu luc, roi hoi chieu / mana neu co.
local function subOf(pid, sk, lv)
  local s = fmt(sk, lv)
  if sk.heSo ~= nil and sk.heSo > 0 then
    -- Ghi ro dang an theo chi so nao. Cong thuc lay chi so CAO NHAT, ma
    -- nguoi choi khong co cach nao biet do la cai nao neu khong noi.
    local _, ten = topStat(S.p[pid] and S.p[pid].hero)
    s = s .. " (" .. API.t("stat_" .. ten) .. ")"
  end
  if sk.cd ~= nil and sk.cd > 0 then
    s = s .. "   " .. string.format("%.1fs", cdAt(sk, lv))
    if manaAt(sk, lv) > 0 then s = s .. " / " .. manaAt(sk, lv) .. " mana" end
  end
  return s
end

local function tabItems(pid)
  local list = listOf(pid)
  if #list == 0 then return {} end

  local ngo = API.getGo(pid)
  local out = {}
  for i = 1, #list do
    local sk   = list[i]
    local lv   = levelOf(pid, sk.id, i)
    local tran = maxOf(sk.id)
    local gia  = costOf(pid, lv, sk.id)

    local it = { icon = iconOf(sk), ten = API.pick(sk) }

    if lv <= 0 then
      -- Ky nang chua mo: KHONG hien so lieu cua no. Lo het thi chang
      -- con gi de mong khi bo tien ra mo.
      it.ten       = CFG.C_GREY .. API.pick(sk) .. CFG.C_END
      it.trangThai = CFG.C_GREY .. API.t("skill_locked") .. CFG.C_END
      it.mota      = ""
      if gia ~= nil then
        it.nut    = API.t("btn_unlock") .. "  " .. gia .. " " .. API.t("cur_go")
        it.batNut = (ngo >= gia)
      end
    else
      -- Hien TRAN THAT, khong hien tran thiet ke. Bang bao 10/10 trong
      -- khi unit chi len duoc bac 3 la bang noi doi.
      local bac = lv .. "/" .. tran
      if tran < CFG.SKILL_MAX_LEVEL then
        bac = CFG.C_RED .. bac .. " !" .. CFG.C_END
      else
        bac = CFG.C_JADE .. bac .. CFG.C_END
      end
      it.trangThai = bac
      it.mota      = subOf(pid, sk, lv)
      if gia ~= nil then
        it.nut    = API.t("btn_up") .. "  " .. gia .. " " .. API.t("cur_go")
        it.batNut = (ngo >= gia)
      else
        it.trangThai = CFG.C_GREY .. API.t("st_max") .. CFG.C_END
      end
    end
    out[i] = it
  end

  -- Mot dong su that o cuoi: con so mau ngoc o tren la THIET KE, chua
  -- phai thu dang chay. Chung chi thanh that khi bo sinh ghi so vao
  -- war3map.w3a va cac skill bi dong duoc viet bang Lua.
  --
  -- Giu lai sau khi doi bo cuc: bang ma hien so dep nhung sai thi te
  -- hon la khong hien gi.
  if not CFG.SKILL_DATA_LIVE then
    out[#out + 1] = {
      ten  = CFG.C_RED .. API.t("skill_notlive") .. CFG.C_END,
      mota = API.t("skill_notlive2"),
    }
  end
  return out
end

local function tabItemAction(pid, i)
  if listOf(pid)[i] == nil then return end
  API.syncSend(pid, CFG.OP_SKILL_UP, i)
end

local function startSkills()
  API.panelAddTab({
    ten        = API.t("panel_skill"),
    kind       = "list",
    -- Dong canh bao SKILL_DATA_LIVE chi hien khi co la false, nen chi
    -- dat cho no khi do. Mot hang thua = 0.048 chieu cao khung, ma
    -- chieu cao dang tranh nhau voi thanh giao dien duoi.
    soMuc      = 7 + (CFG.SKILL_DATA_LIVE and 0 or 1),
    items      = tabItems,
    itemAction = tabItemAction,
    trong      = API.t("skill_none"),
  })
  API.syncOn(CFG.OP_SKILL_UP, upgrade)
  API.trace("skill: the Ky Nang san sang (Ngo Tinh)")
end

-- Goi khi hero vua duoc tao: dat lai bac cho dung voi bang da mua.
local function applyToHero(pid)
  local d = S.p[pid]
  local list = listOf(pid)
  local thieu = {}

  local co = 0
  for i = 1, #list do
    local sk = list[i]
    local lv = levelOf(pid, sk.id, i)

    -- Chi do va dat bac cho ky nang DA MO KHOA. Ky nang con khoa chua
    -- nam tren unit, do no chi tra ve 0 va lam ban bao cao.
    if lv > 0 and d ~= nil and d.hero ~= nil then
      co = co + 1
      local m = probeMax(d.hero, sk.id)
      S.skillMax[sk.id] = m
      if m > 0 and m < CFG.SKILL_MAX_LEVEL then
        thieu[#thieu + 1] = API.idToStr(sk.id) .. "=" .. m
      end
      applyLevel(pid, sk, lv)
    end
  end

  if #thieu > 0 then
    API.trace("skill: OE thieu bac -- " .. table.concat(thieu, " "))
    API.msg(pid, CFG.C_RED .. #thieu .. "/" .. co ..
      " ky nang chua du " .. CFG.SKILL_MAX_LEVEL .. " bac trong Object Editor" ..
      CFG.C_END .. CFG.C_GREY .. " (" .. table.concat(thieu, " ") ..
      "). Dat Stats - Levels = " .. CFG.SKILL_MAX_LEVEL .. "." .. CFG.C_END)
  end
end

API.skillList    = listOf
API.skillLevel   = levelOf
API.skillCost    = costOf
API.skillDamage  = skillDamage
API.skillHeSo    = heSoAt
API.skillCd      = cdAt
API.skillPct     = pctAt
API.skillGiap    = giapAt
API.skillMana    = manaAt
API.skillTopStat = topStat
API.skillApply   = applyToHero
API.startSkills  = startSkills
end
--#endregion 2_nguoi_choi/4_skill.lua

--#region 2_nguoi_choi/5_trangbi.lua
do
-- ============================================================
--  5_trangbi.lua  --  Sau o trang bi, moi o 10 cap
--
--  Mua bang LINH KHI -- cung vi voi Linh Can, va do la co y. Hai he
--  nay tranh nhau mot cai vi nen moi wave nguoi choi phai tra loi mot
--  cau that: dot pha, hay nang do?
--
--  Hai he con lai khong tranh vi do. Ky Nang an Ngo Tinh (tinh anh),
--  Phap Khi an Tinh Thach (boss) -- chung bi chan boi NOI DUNG chu
--  khong boi tien. Xem docs/02-he-thong/kinh-te.md
--
--  O bat dau o CAP 1, nang 9 lan len cap 10. Sau o day cap:
--    (1.04^9)^6 = x8.3 sat thuong -- dung phan x8 cua ngan sach x967.
--
--  Nho: goi ham cua file khac phai qua API.
-- ============================================================

local function slotCount() return #CFG.TRANGBI end

-- Cap cua mot o. Mac dinh 1, khong phai 0 -- sau o deu co san tu dau,
-- thu mua duoc la CAP chu khong phai mon do.
local function levelOf(pid, i)
  local d = S.p[pid]
  if d == nil or d.tb == nil then return 1 end
  return d.tb[i] or 1
end

-- Tong so lan da nang cua CA SAU o. Gia tra theo con so nay chu khong
-- theo cap cua rieng mot o -- don het vao mot o khong re hon rai deu,
-- nen nguoi choi chon theo loi choi chu khong theo phep tinh.
local function upsOf(pid)
  local d = S.p[pid]
  return (d ~= nil) and (d.tbUps or 0) or 0
end

local function costOf(pid, i)
  if levelOf(pid, i) >= CFG.TRANGBI_MAX_LEVEL then return nil end
  return math.floor(CFG.TRANGBI_COST_BASE
                    * CFG.TRANGBI_COST_STEP ^ upsOf(pid) + 0.5)
end

-- Nhan sat thuong tu ca sau o gop lai.
local function multOf(pid)
  local n = 0
  for i = 1, slotCount() do n = n + (levelOf(pid, i) - 1) end
  return (1 + CFG.TRANGBI_PCT) ^ n
end

-- ---------- Ap vao hero ----------
--
-- Trang Bi nhan vao SAT THUONG NEN, khong cong vao chi so.
--
-- Linh Can da cong chi so roi. Neu Trang Bi cung cong chi so thi hai he
-- chong len nhau va khong con tach duoc phan nao do he nao -- ma ngan
-- sach x967 thi doi tung phan phai do duoc rieng.
--
-- File nay KHONG tu ghi len unit. API.heroRecompute trong
-- 7_hieuung.lua la cho duy nhat ghi, va no doc multOf() qua
-- API.trangBiMult.

-- ---------- Nang cap ----------
-- Chay tren MOI may, tu kenh dong bo.

local function upgrade(pid, i)
  local slot = CFG.TRANGBI[i]
  if slot == nil then return end

  local d = S.p[pid]
  if d == nil then return end
  if d.tb == nil then d.tb = {} end

  local cur = levelOf(pid, i)
  if cur >= CFG.TRANGBI_MAX_LEVEL then
    API.msg(pid, CFG.C_GREY .. API.t("skill_atmax", API.pick(slot)) .. CFG.C_END)
    return
  end

  local gia = costOf(pid, i)
  if not API.spendLinhKhi(pid, gia) then
    API.msg(pid, CFG.C_RED .. API.t("no_qi") .. CFG.C_END ..
      API.t("need_have", API.num(gia), API.num(API.getLinhKhi(pid))))
    API.panelRefresh(pid)
    return
  end

  d.tb[i]  = cur + 1
  d.tbUps  = upsOf(pid) + 1
  API.heroRecompute(pid)

  API.msg(nil, API.t("tb_bought",
    CFG.C_GOLD .. GetPlayerName(Player(pid)) .. CFG.C_END,
    CFG.C_JADE .. API.pick(slot) .. CFG.C_END, cur + 1))
  API.panelRefresh(pid)
end

-- ---------- The trong bang phim E ----------

local function tabItems(pid)
  local lk  = API.getLinhKhi(pid)
  local out = {}
  for i = 1, slotCount() do
    local slot = CFG.TRANGBI[i]
    local lv   = levelOf(pid, i)
    local gia  = costOf(pid, i)

    local pct = string.format("%.0f%%",
      ((1 + CFG.TRANGBI_PCT) ^ (lv - 1) - 1) * 100)

    local it = {
      icon      = slot.icon,
      ten       = API.pick(slot),
      mota      = API.t("tb_effect", pct),
      trangThai = CFG.C_JADE .. lv .. "/" .. CFG.TRANGBI_MAX_LEVEL .. CFG.C_END,
    }

    -- KHOA TAM THOI: van hien du sau o, nhung ghi 0/0 va khong co nut.
    -- Hien the day du roi khoa thi nguoi choi biet he nay ton tai va
    -- dang dong; de the trong thi ho tuong giao dien hong.
    if CFG.TRANGBI_LOCKED then
      it.ten       = CFG.C_GREY .. API.pick(slot) .. CFG.C_END
      it.mota      = CFG.C_GREY .. API.t("tb_locked") .. CFG.C_END
      it.trangThai = CFG.C_GREY .. "0/0" .. CFG.C_END
      out[i] = it
    elseif gia ~= nil then
      it.nut    = API.t("btn_up") .. "  " .. API.num(gia) .. " " .. API.t("cur_lk")
      it.batNut = (lk >= gia)
    else
      it.trangThai = CFG.C_GREY .. API.t("st_max") .. CFG.C_END
    end
    if not CFG.TRANGBI_LOCKED then out[i] = it end   -- nhanh khoa da gan o tren
  end
  return out
end

-- Bam nut KHONG doi trang thai -- no gui mot tin, va upgrade() ben duoi
-- chay tren moi may cung mot nhip. Xem ADR 0012.
local function tabItemAction(pid, i)
  if CFG.TRANGBI_LOCKED then return end
  if CFG.TRANGBI[i] == nil then return end
  API.syncSend(pid, CFG.OP_TB_UP, i)
end

local function startTrangBi()
  API.panelAddTab({
    ten        = API.t("panel_gear"),
    kind       = "list",
    soMuc      = slotCount(),
    items      = tabItems,
    itemAction = tabItemAction,
  })
  API.syncOn(CFG.OP_TB_UP, upgrade)
  API.trace("trangbi: " .. slotCount() .. " o, the san sang")
end

-- Goi khi hero vua duoc tao. Khong con lam gi rieng -- giu ten de cho
-- goi cu khong gay.
local function applyToHero(pid)
  API.heroRecompute(pid)
end

API.trangBiLevel = levelOf
API.trangBiMult  = multOf
API.trangBiApply = applyToHero
API.startTrangBi = startTrangBi
end
--#endregion 2_nguoi_choi/5_trangbi.lua

--#region 2_nguoi_choi/6_phapkhi.lua
do
-- ============================================================
--  6_phapkhi.lua  --  Mua MOT lan, khong co cap
--
--  BANG DANG RONG (CFG.PHAPKHI = {}) -- 2026-09-16. Nam mon cu da xoa:
--  chung mua bang Tinh Thach, con he nay gio tra bang NGO TINH.
--
--  NGAN SACH DANH SAN: ca van kiem 300 Ngo Tinh, ky nang tieu 70, nen
--  con 230 diem cho day. Do la rang buoc khi thiet ke lai.
--
--  Code chay duoc voi bang rong: the hien mot dong "chua co gi", khong
--  mua duoc gi, va moi hieu ung tra ve false -- nen 2_wave.lua goi
--  API.phapKhiCo / phapKhiAiCo / phapKhiOnClear van an toan.
--
--  KHI THEM MON MOI. Moi mon phai DOC-LUC-DUNG: khong dang ky trigger
--  rieng, ma cho can biet thi hoi API.phapKhiCo. Mot mon can bo bat su
--  kien rieng la mot mon co the hong am tham, ma ca van chi mua duoc
--  vai lan. Them mon la them dong vao CFG.PHAPKHI VA viet cho doc 'ma'
--  cua no -- khong co bang dieu phoi tu dong nao ca.
--
--  Nho: goi ham cua file khac phai qua API.
-- ============================================================

-- Nguoi nay co mon do khong.
local function co(pid, ma)
  local d = S.p[pid]
  return (d ~= nil) and (d.pk ~= nil) and (d.pk[ma] == true)
end

-- CO AI trong doi co mon do khong.
--
-- Dung cho hai mon cong vao NHA CHINH: nha la cua chung, nen mot nguoi
-- mua la ca doi duoc huong. Do cung la ly do hai mon do dat hon hai mon
-- ca nhan.
local function aiCo(ma)
  for i = 1, #S.pids do
    if co(S.pids[i], ma) then return true end
  end
  return false
end

local function defOf(ma)
  for i = 1, #CFG.PHAPKHI do
    if CFG.PHAPKHI[i].ma == ma then return CFG.PHAPKHI[i] end
  end
  return nil
end

-- ---------- Mua ----------
-- Chay tren MOI may, tu kenh dong bo.

local function buy(pid, i)
  local mon = CFG.PHAPKHI[i]
  if mon == nil then return end

  local d = S.p[pid]
  if d == nil then return end
  if d.pk == nil then d.pk = {} end
  if d.pk[mon.ma] then return end

  if CFG.PHAPKHI_LOCKED then return end
  if not API.spendGo(pid, mon.gia) then
    API.msg(pid, CFG.C_RED .. API.t("no_go") .. CFG.C_END ..
      API.t("need_have", API.num(mon.gia), API.num(API.getGo(pid))) ..
      CFG.C_GREY .. " " .. API.t("ngo_note") .. CFG.C_END)
    API.panelRefresh(pid)
    return
  end

  d.pk[mon.ma] = true
  API.msg(nil, API.t("pk_bought",
    CFG.C_GOLD .. GetPlayerName(Player(pid)) .. CFG.C_END,
    CFG.C_JADE .. API.pick(mon) .. CFG.C_END))

  if d.hero ~= nil then
    API.fx([[Abilities\Spells\Items\AIem\AIemTarget.mdl]],
           GetUnitX(d.hero), GetUnitY(d.hero))
  end
  API.panelRefresh(pid)
end

-- ---------- Hieu ung "mana": don sach mot dot thi ca doi hoi day ----------
--
-- Goi tu onMobDeath luc con cuoi cung chet. Mot nguoi mua thi ca doi
-- duoc -- cung nguyen tac voi hai mon cong vao nha.
local function onClear()
  if not aiCo("mana") then return end
  for i = 1, #S.pids do
    local d = S.p[S.pids[i]]
    if d ~= nil and d.hero ~= nil and API.alive(d.hero) then
      SetUnitState(d.hero, UNIT_STATE_MANA,
                   GetUnitState(d.hero, UNIT_STATE_MAX_MANA))
    end
  end
end

-- ---------- The trong bang phim E ----------

local function motaOf(mon)
  if API.lang() == "en" then return mon.mota_en or mon.mota end
  return mon.mota or mon.mota_en
end

local function tabItems(pid)
  -- KHOA TAM THOI: khong ban gi ca. Tra ve rong de bang hien dong
  -- "chua co gi" + ly do, thay vi hien mon mua khong duoc.
  if CFG.PHAPKHI_LOCKED then return {} end
  local ngo = API.getGo(pid)
  local out = {}
  for i = 1, #CFG.PHAPKHI do
    local mon = CFG.PHAPKHI[i]
    local it  = { icon = mon.icon, ten = API.pick(mon), mota = motaOf(mon) }

    if co(pid, mon.ma) then
      it.trangThai = CFG.C_JADE .. API.t("st_owned") .. CFG.C_END
    else
      it.trangThai = CFG.C_GREY .. API.num(mon.gia) .. CFG.C_END
      -- GO: buy() goi API.spendGo. Nhan sai tien tren nut la noi doi voi
      -- nguoi choi ve thu ho dang de danh.
      it.nut       = API.t("btn_buy") .. "  " .. API.num(mon.gia) .. " " .. API.t("cur_go")
      it.batNut    = (ngo >= mon.gia)
    end
    out[i] = it
  end
  return out
end

local function tabItemAction(pid, i)
  if CFG.PHAPKHI[i] == nil then return end
  API.syncSend(pid, CFG.OP_PK_BUY, i)
end

local function startPhapKhi()
  API.panelAddTab({
    ten        = API.t("panel_treasure"),
    kind       = "list",
    soMuc      = #CFG.PHAPKHI,
    items      = tabItems,
    itemAction = tabItemAction,
    trong      = CFG.PHAPKHI_LOCKED and API.t("pk_locked") or API.t("pk_empty"),
  })
  API.syncOn(CFG.OP_PK_BUY, buy)
  API.trace("phapkhi: " .. #CFG.PHAPKHI .. " mon, the san sang")
end

API.phapKhiCo      = co
API.phapKhiAiCo    = aiCo
API.phapKhiDef     = defOf
API.phapKhiOnClear = onClear
API.startPhapKhi   = startPhapKhi
end
--#endregion 2_nguoi_choi/6_phapkhi.lua

--#region 2_nguoi_choi/7_hieuung.lua
do
-- ============================================================
--  7_hieuung.lua  --  Ky nang co hieu luc that
--
--  Truoc file nay, bay ky nang cua Hart la bay ability GOC cua Warcraft
--  duoc nhan ban: Shockwave, Holy Light, Devotion Aura, Avatar... Chung
--  gay dung so sat thuong ma Blizzard dat, va KHONG an theo bat cu thu
--  gi nguoi choi mua. Linh Can bac 20 cong +1075 moi chi so; Chuong van
--  gay dung ngan ay sat thuong nhu wave 1.
--
--  Do la ly do CFG.SKILL_DATA_LIVE ton tai, va vi sao no tung la false.
--
--  VI SAO KHONG SUA TRUONG TRONG war3map.w3a
--
--  Cach "chinh thong" la ghi so vao truong Data cua Shockwave. Khong lam
--  duoc: ma truong cua AOsh / AHhb / AHad CHUA AI DO
--  (docs/06-object-editor/sua-va-clone-ability.md), ma du an nay co luat
--  khong doan -- doan sai mot ma truong bon ky tu la file hong am tham,
--  kieu te nhat.
--
--  Nen file nay bat su kien va TU gay sat thuong. Khong can biet ma
--  truong nao ca. Sat thuong goc cua Warcraft van con, nhung o bac 10
--  voi Linh Can bac 20 thi no la sai so lam tron.
--
--  BAY LOAI HIEU UNG, khai bao bang truong 'fx' trong CFG.SKILLS:
--    line heal buff        chu dong, bat qua su kien cast
--    cleave reduce         bi dong, bat qua su kien sat thuong
--    stat aura             bi dong, tinh lai khi bac ky nang doi
--
--  Bay loai nay dung lai duoc cho Hvwd va Hkal -- them hero moi la khai
--  bao them dong trong CFG.SKILLS, khong phai viet them code o day.
--
--  Nho: goi ham cua file khac phai qua API.
-- ============================================================

-- Chan de quy: sat thuong do CHINH file nay gay ra cung ban su kien
-- EVENT_PLAYER_UNIT_DAMAGED. Khong chan thi Chem Lan van lan nhau vo han
-- va game treo ngay wave dau.
local busy = false

-- ---------- Tra cuu ----------

-- Tra ve (sk, bac) cua mot ability tren hero cua nguoi nay. Bac 0 hoac
-- khong tim thay thi tra nil -- goi ben ngoai chi can kiem mot lan.
local function skillOf(pid, abilId)
  local list = API.skillList(pid)
  for i = 1, #list do
    if list[i].id == abilId then
      local lv = API.skillLevel(pid, abilId, i)
      if lv > 0 then return list[i], lv end
      return nil
    end
  end
  return nil
end

-- Tim ky nang theo LOAI hieu ung. Dung cho bi dong: luc bi danh thi ta
-- khong biet ability nao, chi biet "nguoi nay co Da Sat khong".
local function skillByFx(pid, fx)
  local list = API.skillList(pid)
  for i = 1, #list do
    if list[i].fx == fx then
      local lv = API.skillLevel(pid, list[i].id, i)
      if lv > 0 then return list[i], lv end
      return nil
    end
  end
  return nil
end

local function heroPid(u)
  if u == nil then return nil end
  local pid = GetPlayerId(GetOwningPlayer(u))
  local d = S.p[pid]
  if d == nil or d.hero ~= u then return nil end
  return pid
end

-- ---------- Nhat muc tieu ----------

local function enemiesNear(x, y, radius, f)
  local g = CreateGroup()
  GroupEnumUnitsInRange(g, x, y, radius, nil)
  local u = FirstOfGroup(g)
  while u ~= nil do
    GroupRemoveUnit(g, u)
    -- Chi quai cua phe dich. Khong dung IsUnitEnemy: no hoi "dich voi
    -- AI", ma o day ta luon muon dung mot phe duy nhat.
    if API.alive(u) and GetOwningPlayer(u) == S.enemy then f(u) end
    u = FirstOfGroup(g)
  end
  DestroyGroup(g)
end

-- Gay sat thuong, co co chan de quy.
local function hit(src, tgt, amount, model)
  if amount <= 0 or not API.alive(tgt) then return end
  busy = true
  UnitDamageTarget(src, tgt, amount, true, false,
                   ATTACK_TYPE_NORMAL, DAMAGE_TYPE_MAGIC, WEAPON_TYPE_WHOKNOWS)
  busy = false
  if model ~= nil then API.fx(model, GetUnitX(tgt), GetUnitY(tgt)) end
end

-- ---------- Ky nang chu dong ----------

-- "line": danh tren mot duong thang truoc mat.
--
-- Khoang cach tu mot diem toi DUONG THANG, khong phai toi diem cuoi --
-- neu khong thi con dung sat ben canh hero se khong an don du no nam
-- ngay tren duong danh.
local function fxLine(pid, u, sk, lv)
  local x, y = GetUnitX(u), GetUnitY(u)
  local tx, ty = x, y
  if GetSpellTargetX ~= nil then tx, ty = GetSpellTargetX(), GetSpellTargetY() end
  if tx == x and ty == y then
    -- Khong co diem nham thi danh theo huong dang quay.
    tx = API.polarX(x, CFG.FX_LINE_LEN, GetUnitFacing(u))
    ty = API.polarY(y, CFG.FX_LINE_LEN, GetUnitFacing(u))
  end

  local ang = API.angleXY(x, y, tx, ty)
  local L   = CFG.FX_LINE_LEN
  local cx  = API.polarX(x, L * 0.5, ang)
  local cy  = API.polarY(y, L * 0.5, ang)
  local dmg = API.skillDamage(u, API.skillHeSo(sk, lv))

  local ux, uy = Cos(ang * bj_DEGTORAD), Sin(ang * bj_DEGTORAD)
  enemiesNear(cx, cy, L * 0.5 + CFG.FX_LINE_WIDTH, function(e)
    local dx, dy = GetUnitX(e) - x, GetUnitY(e) - y
    local doc = dx * ux + dy * uy                 -- chieu len duong danh
    if doc < 0.0 or doc > L then return end
    local ngang = dx * (-uy) + dy * ux            -- khoang cach toi duong
    if ngang < 0 then ngang = -ngang end
    if ngang > CFG.FX_LINE_WIDTH then return end
    hit(u, e, dmg, CFG.FX_HIT_LINE)
  end)
end

-- "heal": hoi mau mot muc tieu. Khong co muc tieu thi hoi chinh minh.
local function fxHeal(pid, u, sk, lv)
  local t = (GetSpellTargetUnit ~= nil) and GetSpellTargetUnit() or nil
  if t == nil then t = u end
  local amount = API.skillDamage(u, API.skillHeSo(sk, lv))
  local hp = GetUnitState(t, UNIT_STATE_LIFE) + amount
  local mx = GetUnitState(t, UNIT_STATE_MAX_LIFE)
  SetUnitState(t, UNIT_STATE_LIFE, (hp > mx) and mx or hp)
  API.fx(CFG.FX_HIT_HEAL, GetUnitX(t), GetUnitY(t))
end

-- "buff" KHONG con ham Lua nao.
--
-- Bat Hoai la ban sao cua Avatar, va Avatar tu co buff co thoi luong.
-- Giap cua no lay tu ABILITY_RLF_DEFENSE_BONUS_HAV1 -- truong ma
-- applyLevel() ghi so can bang cua ta vao (CFG.SKILL_CHO_GOC). Nen
-- khong con gi de lam bang Lua: bam la Warcraft lo het.
--
-- Thoi luong gio la thoi luong goc cua Avatar, khong phai
-- CFG.FX_BUFF_TIME. Muon doi thi dat truong 'adur'/'ahdu' trong
-- war3map.w3a.
--
-- HAV2 (mau toi da) van chay: ban 1.31.1 khong phoi ra hang so nao cho
-- no nen khong tat duoc -- xem chu thich o CFG.SKILL_TAT_GOC.

local FX_CAST = { line = fxLine, heal = fxHeal }

local function onSpell()
  local u = GetTriggerUnit()
  if u == nil then return end
  local pid = heroPid(u)
  if pid == nil then return end

  local sk, lv = skillOf(pid, GetSpellAbilityId())
  if sk == nil or sk.fx == nil then return end

  local f = FX_CAST[sk.fx]
  if f ~= nil then f(pid, u, sk, lv) end
end

-- ---------- Ky nang bi dong bat qua su kien sat thuong ----------

local function onDamaged()
  if busy then return end                -- sat thuong cua chinh ta

  local amount = GetEventDamage()
  if amount <= 0.0 then return end

  local tgt = (BlzGetEventDamageTarget ~= nil) and BlzGetEventDamageTarget()
              or GetTriggerUnit()
  local src = GetEventDamageSource()

  -- "reduce": hero NHAN don. Giam % sat thuong, co tran cung.
  local tp = heroPid(tgt)
  if tp ~= nil and BlzSetEventDamage ~= nil then
    local sk, lv = skillByFx(tp, "reduce")
    if sk ~= nil then
      local pct = API.skillPct(sk, lv)
      if pct > CFG.FX_REDUCE_CAP then pct = CFG.FX_REDUCE_CAP end
      BlzSetEventDamage(amount * (1.0 - pct))
    end
  end

  -- "cleave": hero GAY don. Van % sat thuong sang muc tieu ben canh.
  local sp = heroPid(src)
  if sp ~= nil and tgt ~= nil then
    local sk, lv = skillByFx(sp, "cleave")
    if sk ~= nil then
      local van = amount * API.skillPct(sk, lv)
      if van >= 1.0 then
        enemiesNear(GetUnitX(tgt), GetUnitY(tgt), CFG.FX_CLEAVE_AOE,
          function(e)
            if e ~= tgt then hit(src, e, van, CFG.FX_HIT_CLEAVE) end
          end)
      end
    end
  end
end

-- ============================================================
--  MOT cho duy nhat ghi chi so hero
--
--  LUAT. Moi nguon chi KHAI BAO no dong gop bao nhieu; ham recompute
--  cong het lai roi ghi MOT lan. Khong cho nao duoc doc-cong-ghi-lai.
--
--  Vi sao phai co luat nay -- day la loi that da xay ra:
--
--    Bat Hoai va Hieu Lenh truoc day deu ghi giap kieu doc-cong-ghi.
--    Nang Hieu Lenh trong luc Bat Hoai dang bat thi "giap nen" bi doc
--    nham la giap DA CONG buff, nen luc buff het tru ra khong khop.
--    Lan vet voi giap nen 5: sau mot chu ky hero con 9.05 thay vi 5.81,
--    va no cong don moi lan lap.
--
--  Bon nguon hien co, va se con them khi Hvwd/Hkal co ky nang:
--    chi so       nen + Linh Can, roi nhan % cua bi dong "stat"
--    sat thuong   nen x Trang Bi
--    giap         nen + aura "Hieu Lenh" + buff "Bat Hoai"
--
--  Nho: goi ham cua file khac phai qua API.
-- ============================================================

-- Doc chi so NEN cua hero. Goi DUNG MOT LAN, ngay sau khi tao hero va
-- truoc khi bat cu he nao cong vao.
--
-- Doc lai lan hai la nhan chong: lan do se doc ra con so da cong roi.
local function baseCapture(pid)
  local d = S.p[pid]
  if d == nil or d.hero == nil then return end
  local h = d.hero
  d.nen = {
    str   = GetHeroStr(h, false),
    agi   = GetHeroAgi(h, false),
    int   = GetHeroInt(h, false),
    dmg   = (BlzGetUnitBaseDamage ~= nil) and BlzGetUnitBaseDamage(h, 0) or 0,
    giap  = (BlzGetUnitArmor ~= nil) and BlzGetUnitArmor(h) or 0.0,
  }
end

-- Giap cua Hieu Lenh va Bat Hoai khong con tinh o file nay.
--
-- Hai ham cu -- auraGiap() va buffGiap() -- da xoa. Chung ton tai de
-- cong giap vao BlzSetUnitArmor, ma dong do chinh la thu dong bang phan
-- chi so. Gio giap nam trong truong cua chinh hai ability do
-- (CFG.SKILL_CHO_GOC) va Warcraft cong.
--
-- DOI HANH VI: aura cua Warcraft co BAN KINH, ban Lua cu thi khong --
-- no cong cho ca doi du dung dau tren map. Map nay ba nguoi gan nhu
-- luon dung chung mot cho nen khac biet nho, nhung day la thu can nhin
-- lai neu doi hinh tach xa nhau.

local function recompute(pid)
  local d = S.p[pid]
  if d == nil or d.hero == nil then return end
  local h = d.hero
  if d.nen == nil then baseCapture(pid) end
  local n = d.nen

  -- ---------- Chi so ----------
  -- nen + Linh Can, roi nhan % cua bi dong "stat" (Luyen The).
  local lc = API.linhCanStatBonus(pid)
  local sk, lv = skillByFx(pid, "stat")
  local pct = (sk ~= nil) and API.skillPct(sk, lv) or 0.0

  if CFG.LINHCAN_STAT_MODE == "primary" then
    -- Cong vao chi so cao nhat cua NEN, khong phai cua hien tai -- chi
    -- so hien tai doi theo chinh phep cong nay thi no se nhay qua nhay
    -- lai giua hai chi so.
    local s, a, i = n.str, n.agi, n.int
    if s >= a and s >= i then s = s + lc
    elseif a >= i then a = a + lc
    else i = i + lc end
    SetHeroStr(h, math.floor(s * (1 + pct) + 0.5), true)
    SetHeroAgi(h, math.floor(a * (1 + pct) + 0.5), true)
    SetHeroInt(h, math.floor(i * (1 + pct) + 0.5), true)
  else
    SetHeroStr(h, math.floor((n.str + lc) * (1 + pct) + 0.5), true)
    SetHeroAgi(h, math.floor((n.agi + lc) * (1 + pct) + 0.5), true)
    SetHeroInt(h, math.floor((n.int + lc) * (1 + pct) + 0.5), true)
  end

  -- ---------- Sat thuong va giap: DE WARCRAFT TU TINH ----------
  --
  -- Ham nay KHONG con ghi BlzSetUnitBaseDamage hay BlzSetUnitArmor.
  --
  -- Ban truoc ghi ca hai, va do la ly do chi so len ma don thuong voi
  -- giap dung yen: n.giap la BlzGetUnitArmor() chup luc TAO HERO (giap
  -- tong hoi Agi con bang 5), nen moi lan tinh lai deu dong bang phan
  -- Agi vao con so do. Agi 511 ma giap van bang 2.
  --
  -- Phan cong them cua Hieu Lenh va Bat Hoai gio nam trong CHINH TRUONG
  -- cua hai ability do (CFG.SKILL_CHO_GOC), nen Warcraft cong -- khong
  -- con ai phai so huu cong thuc giap nua.
  --
  -- Sat thuong thi khong can vat mang: Trang Bi dang khoa nen
  -- trangBiMult luon 1.0, tuc dong cu ghi lai dung con so no vua doc.
  -- Mo Trang Bi lai thi phai chon vat mang cho no, dung ghi de o day.
end

-- Aura cham toi NGUOI KHAC, nen doi bac cua mot nguoi la ca doi phai
-- tinh lai.
local function recomputeAll()
  for i = 1, #S.pids do recompute(S.pids[i]) end
end

-- ---------- Khoi dong ----------

local function startSkillFx()
  local tSpell = CreateTrigger()
  TriggerRegisterAnyUnitEventBJ(tSpell, EVENT_PLAYER_UNIT_SPELL_EFFECT)
  TriggerAddAction(tSpell, onSpell)

  if EVENT_PLAYER_UNIT_DAMAGED ~= nil then
    local tDmg = CreateTrigger()
    TriggerRegisterAnyUnitEventBJ(tDmg, EVENT_PLAYER_UNIT_DAMAGED)
    TriggerAddAction(tDmg, onDamaged)
  else
    API.msg(nil, CFG.C_RED .. "Khong co EVENT_PLAYER_UNIT_DAMAGED -- " ..
      "Chem Lan va Da Sat se khong chay." .. CFG.C_END)
  end

  API.trace("hieuung: san sang (cast + damage)")
end

API.heroBaseCapture  = baseCapture
API.heroRecompute    = recompute
API.heroRecomputeAll = recomputeAll
API.skillFxRecompute = recomputeAll   -- ten cu, giu cho cho goi san co
API.startSkillFx     = startSkillFx
end
--#endregion 2_nguoi_choi/7_hieuung.lua

--#region 2_nguoi_choi/8_shop.lua
do
-- ============================================================
--  8_shop.lua  --  The V: Shop
--
--  He DUY NHAT tieu VANG, va he duy nhat ban do TIEU HAO. Ba the kia
--  ban thu vinh vien; the nay ban mot lan dung.
--
--  Mua la HANH DONG -> phai qua kenh dong bo, khong duoc lam cuc bo.
--  Chi viec mo bang va doi the moi la UI thuan.
--
--  Nho: goi ham cua file khac phai qua API.
-- ============================================================

-- Cung khuon voi 6_phapkhi.lua: API.pick lo phan TEN, mo ta thi tung he
-- tu lay vi ten truong khac nhau.
local function motaOf(mon)
  if API.lang() == "en" then return mon.mota_en or mon.mota end
  return mon.mota or mon.mota_en
end

-- Con o trong tui khong? Warcraft cho 6 o; mua khi day tui thi item roi
-- xuong dat ngay duoi chan hero, va nguoi choi mat vang vi mot cai o ma
-- khong hieu tai sao.
-- Tim o dang giu item CUNG LOAI va con cho gop. Tra ve chinh item do.
local function oGop(u, maItem)
  if u == nil or UnitInventorySize == nil or UnitItemInSlot == nil then return nil end
  if GetItemTypeId == nil or GetItemCharges == nil then return nil end
  local tran = CFG.SHOP_STACK_MAX or 1
  if tran <= 1 then return nil end
  local n = UnitInventorySize(u)
  for i = 0, (n or 0) - 1 do
    local it = UnitItemInSlot(u, i)
    if it ~= nil and GetItemTypeId(it) == maItem then
      local c = GetItemCharges(it)
      -- 0 luot = item khong dung he luot. Gop vao la dem duoc nhung con
      -- so hien ra co the khong dung voi so lan dung duoc -- nen bo qua,
      -- de no chiem o rieng cho that.
      if c ~= nil and c >= 1 and c < tran then return it end
    end
  end
  return nil
end

-- Con cho de NHAN them mot lo khong: hoac con o trong, hoac co mot o
-- cung loai chua day luot.
local function conCho(u, maItem)
  if not CFG.SHOP_CHECK_BAG then return true end
  if u == nil then return false end
  if oGop(u, maItem) ~= nil then return true end
  if UnitInventorySize == nil or UnitItemInSlot == nil then return true end

  -- KHONG CO TUI = KHONG CO CHO, chu khong phai "khong biet nen cho qua".
  --
  -- Ban truoc tra ve true o day, va do la mot loi im lang dat dung cho
  -- te nhat: UnitAddItemById tren mot unit khong co tui van tra ve
  -- HANDLE ITEM -- no tao item roi tha xuong DAT duoi chan. Nen
  -- give() dem "phat 10/10 thanh cong" trong khi ca 20 lo nam duoi
  -- san, va UnitItemInSlot() thi bao o trong.
  --
  -- Unit muon cam do phai co ability "Inventory (Hero)" (AInv) trong
  -- Object Editor. Xem CFG.HERO_COMMON_ABILITIES.
  local n = UnitInventorySize(u)
  if n == nil or n <= 0 then return false end

  for i = 0, n - 1 do
    if UnitItemInSlot(u, i) == nil then return true end
  end
  return false
end

-- Chay tren MOI may, tu kenh dong bo.
local function buy(pid, i)
  local mon = CFG.SHOP[i]
  if mon == nil then return end

  local d = S.p[pid]
  if d == nil or d.hero == nil then return end

  if not conCho(d.hero, mon.item) then
    API.msg(pid, CFG.C_RED .. API.t("shop_full") .. CFG.C_END)
    return
  end

  if not API.spendVang(pid, mon.gia) then
    API.msg(pid, CFG.C_RED .. API.t("no_vang") .. CFG.C_END ..
      API.t("need_have", API.num(mon.gia), API.num(API.getVang(pid))))
    API.panelRefresh(pid)
    return
  end

  -- Da co mot o cung loai chua day: cong them mot luot, khong chiem o
  -- moi. Lam truoc khi tao item moi, neu khong thi lan nao cung ra o moi
  -- va gop thanh vo nghia.
  local cu = oGop(d.hero, mon.item)
  if cu ~= nil then
    local c = GetItemCharges(cu) + 1
    SetItemCharges(cu, c)
    API.msg(pid, API.t("shop_stack",
      CFG.C_JADE .. API.pick(mon) .. CFG.C_END, c, API.num(mon.gia)))
    API.panelRefresh(pid)
    return
  end

  -- UnitAddItemById tra ve nil khi ma item khong ton tai. Hoan tien va
  -- BAO RO -- mot ma sai ma nuot im la nguoi choi mat vang khong hieu vi
  -- sao, va ta khong biet minh go sai ma nao (ADR 0012).
  local it = UnitAddItemById(d.hero, mon.item)
  if it == nil then
    API.addVang(pid, mon.gia)
    API.msg(pid, CFG.C_RED .. "Khong tao duoc item " ..
      API.idToStr(mon.item) .. " -- da hoan " .. API.num(mon.gia) ..
      " vang. Kiem CFG.SHOP." .. CFG.C_END)
    API.panelRefresh(pid)
    return
  end

  API.msg(pid, API.t("shop_bought",
    CFG.C_JADE .. API.pick(mon) .. CFG.C_END, API.num(mon.gia)))
  API.panelRefresh(pid)
end

-- Phat item khong tinh tien. Dung cho qua khoi dau (CFG.START_ITEMS).
--
-- Di qua CUNG duong voi buy(): gop vao o cu neu co, khong thi tao o
-- moi. Nho vay qua khoi dau va do mua deu nam chung mot o, va luat gop
-- chi viet mot lan.
local function give(pid, ma, so)
  local d = S.p[pid]
  if d == nil or d.hero == nil or so == nil or so <= 0 then return 0 end

  local mon
  for i = 1, #CFG.SHOP do
    if CFG.SHOP[i].ma == ma then mon = CFG.SHOP[i] end
  end
  if mon == nil then
    API.msg(pid, CFG.C_RED .. "shopGive: khong co mon '" .. tostring(ma) ..
      "' trong CFG.SHOP." .. CFG.C_END)
    return 0
  end

  -- Bao RO khi unit khong co tui, thay vi tha do xuong dat roi bao
  -- thanh cong.
  if UnitInventorySize ~= nil then
    local n = UnitInventorySize(d.hero)
    if n == nil or n <= 0 then
      API.msg(nil, CFG.C_RED .. "Hero khong co tui do (thieu ability " ..
        "Inventory/AInv) -- khong phat duoc " .. tostring(ma) .. CFG.C_END)
      API.trace("shop: hero KHONG CO TUI, bo qua " .. tostring(ma))
      return 0
    end
  end

  local xong = 0
  for _ = 1, so do
    local cu = oGop(d.hero, mon.item)
    if cu ~= nil then
      SetItemCharges(cu, GetItemCharges(cu) + 1)
      xong = xong + 1
    elseif conCho(d.hero, mon.item) then
      local it = UnitAddItemById(d.hero, mon.item)
      if it == nil then break end
      xong = xong + 1
    else
      break   -- het cho, dung han chu khong lam roi item xuong dat
    end
  end

  API.trace("shop: phat " .. xong .. "/" .. so .. " " .. ma .. " cho pid " .. pid)
  return xong
end

-- ---------- The trong bang ----------

local function tabItems(pid)
  local vang = API.getVang(pid)
  local hero = (S.p[pid] or {}).hero
  local out  = {}
  for i = 1, #CFG.SHOP do
    local mon = CFG.SHOP[i]
    local con = conCho(hero, mon.item)
    out[i] = {
      icon      = mon.icon,
      ten       = API.pick(mon),
      mota      = motaOf(mon),
      -- Trang thai la CHO TRONG TUI, khong phai gia: gia da nam tren
      -- nut roi, in hai lan la thua.
      trangThai = con and "" or (CFG.C_RED .. API.t("shop_full") .. CFG.C_END),
      nut       = API.t("btn_buy") .. "  " .. API.num(mon.gia) .. " " ..
                  API.t("cur_vang"),
      batNut    = (vang >= mon.gia) and con,
    }
  end
  return out
end

local function tabItemAction(pid, i)
  if CFG.SHOP[i] == nil then return end
  API.syncSend(pid, CFG.OP_SHOP, i)
end

-- Do ma item va icon NGAY LUC VAO MAP, khong doi toi luc ai do bam mua.
--
-- Hai thu trong CFG.SHOP deu la phong doan: ma item ('phea', 'pman') va
-- duong dan icon. Doan sai ma thi nguoi choi bam mua moi biet; doan sai
-- icon thi o icon ra XANH LA -- dung loi ma BTNRingViolet da dinh.
--
-- CreateItem tra ve nil khi ma khong ton tai, nen tao thu mot cai roi
-- xoa ngay la do duoc ca hai: ma co that khong, va icon THAT cua no la
-- gi. Icon doc duoc thi ghi de len duong dan trong CFG -- lay so do
-- duoc thay cho so go tay.
local function probeItems()
  if CreateItem == nil then return end
  local bad = {}
  for i = 1, #CFG.SHOP do
    local mon = CFG.SHOP[i]
    local it = CreateItem(mon.item, 0.0, 0.0)
    if it == nil then
      bad[#bad + 1] = API.idToStr(mon.item)
    else
      if BlzGetItemIconPath ~= nil then
        local p = BlzGetItemIconPath(it)
        if p ~= nil and p ~= "" then mon.icon = p end
      end
      -- So luot GOC. Bang 0 nghia la item nay khong dung he luot, va
      -- luc do gop lo khong chay -- phai biet truoc chu khong doi toi
      -- luc nguoi choi mua cai thu hai moi phat hien.
      local c = (GetItemCharges ~= nil) and GetItemCharges(it) or -1
      API.trace("shop: " .. mon.ma .. " = " .. API.idToStr(mon.item) ..
                ", luot goc " .. c .. ", icon " .. tostring(mon.icon))
      if c == 0 then
        API.msg(nil, CFG.C_GREY .. "[shop] " .. API.pick(mon) ..
          " co 0 luot -- khong gop o duoc, moi lo se chiem mot o." .. CFG.C_END)
      end
      RemoveItem(it)
    end
  end
  if #bad > 0 then
    API.msg(nil, CFG.C_RED .. "Shop: khong co item " ..
      table.concat(bad, " ") .. " -- sua CFG.SHOP." .. CFG.C_END)
  end
end

local function startShop()
  probeItems()
  API.panelAddTab({
    ten        = API.t("panel_shop"),
    kind       = "list",
    soMuc      = #CFG.SHOP,
    items      = tabItems,
    itemAction = tabItemAction,
    trong      = API.t("shop_empty"),
  })
  API.syncOn(CFG.OP_SHOP, buy)
  API.trace("shop: " .. #CFG.SHOP .. " mon, the san sang")
end

API.shopBuy   = buy
API.shopGive  = give
API.startShop = startShop
end
--#endregion 2_nguoi_choi/8_shop.lua

--#region 2_nguoi_choi/9_dungdo.lua
do
-- ============================================================
--  9_dungdo.lua  --  Dung do trong tui bang HANG SO TREN (canh Esc)
--
--  Warcraft chi gan san san tui do vao numpad (7/8/4/5/1/2). May
--  khong co numpad, va tay phai roi chuot de voi sang numpad, nen
--  gan them hang so 1..6 o tren.
--
--  Day la THEM, khong phai thay: numpad van chay nhu cu.
--
--  VI SAO PHAI QUA KENH DONG BO.
--
--  Su kien phim la DAU VAO CUC BO -- no chi no tren may cua nguoi bam.
--  Bang phim R goi UnitUseItem thang o day thi may do dung mot lo thuoc
--  ma hai may kia khong biet -> lech ban game. Bang chi bat/tat khung
--  hinh nen lam cuc bo duoc; dung do thi doi TRANG THAI, nen phai di
--  qua API.syncSend nhu moi hanh dong khac (ADR 0012).
--
--  Nho: goi ham cua file khac phai qua API.
-- ============================================================

-- Chay tren MOI may, tu kenh dong bo. o = 0..5.
local function dung(pid, o)
  local d = S.p[pid]
  if d == nil or d.hero == nil then return end
  if UnitItemInSlot == nil or UnitUseItem == nil then return end

  local it = UnitItemInSlot(d.hero, o)
  if it == nil then return end
  UnitUseItem(d.hero, it)
end

local function startDungDo()
  if CFG.ITEM_KEYS == nil or #CFG.ITEM_KEYS == 0 then return end
  if BlzTriggerRegisterPlayerKeyEvent == nil then
    API.trace("dungdo: KHONG co BlzTriggerRegisterPlayerKeyEvent")
    return
  end

  API.syncOn(CFG.OP_ITEM, dung)

  local thieu, xong = {}, 0
  for k = 1, #CFG.ITEM_KEYS do
    local ten = CFG.ITEM_KEYS[k]
    local key = _G["OSKEY_" .. ten]
    if key == nil then
      -- Go sai ten hang la tra ve nil roi im lang khong lam gi ca --
      -- ghi ra chu khong nuot (ADR 0012). "-nat oskey" liet ke ten that.
      thieu[#thieu + 1] = "OSKEY_" .. ten
    else
      local t = CreateTrigger()
      for i = 1, #S.pids do
        BlzTriggerRegisterPlayerKeyEvent(t, Player(S.pids[i]), key, 0, true)
      end
      -- Bien k cua vong for so hoc la RIENG cho tung vong trong Lua,
      -- nen moi closure bat dung o cua no.
      TriggerAddAction(t, function()
        API.syncSend(GetPlayerId(GetTriggerPlayer()), CFG.OP_ITEM, k - 1)
      end)
      xong = xong + 1
    end
  end

  if #thieu > 0 then
    API.trace("dungdo: THIEU hang so " .. table.concat(thieu, " ") ..
              " -- go '-nat oskey' de tim ten dung")
  end
  API.trace("dungdo: gan " .. xong .. "/" .. #CFG.ITEM_KEYS .. " phim")
end

API.dungDo      = dung
API.startDungDo = startDungDo
end
--#endregion 2_nguoi_choi/9_dungdo.lua

--#region 3_tran_dau/1_house.lua
do
-- ============================================================
--  1_house.lua  --  Nha chinh & phan giai vung
--
--  Dung nha chinh giua CFG.RGN_HOUSE, va phan giai san vung
--  CFG.RGN_ENEMY de sau nay cho quai ra. Chua sinh quai nao ca.
--
--  Nha chinh la HERO (Mountain King), khong phai cong trinh. Khac biet
--  phai xu ly: mau tinh theo suc manh nen phai khoa kinh nghiem, va
--  hero mac dinh co don danh nen phai tat di.
--
--  Nho: goi ham cua file khac phai qua API.
-- ============================================================

-- Nha chinh dung mot slot rieng, khong thuoc ve rieng nguoi choi nao.
-- Quan he dong minh dat o 04_player.
local function houseOwner()
  return Player(CFG.HOUSE_SLOT)
end

-- Voi hero, mau toi da duoc suy ra tu suc manh. Dat thang bang
-- BlzSetUnitMaxHP van duoc, nhung se bi tinh lai neu hero len cap hoac
-- doi chi so -- vi vay CFG.HOUSE_SUSPEND_XP mac dinh bat.
local function setHouseHP(value)
  if S.house == nil or BlzSetUnitMaxHP == nil then return false end
  BlzSetUnitMaxHP(S.house, math.floor(value))
  SetUnitState(S.house, UNIT_STATE_LIFE, GetUnitState(S.house, UNIT_STATE_MAX_LIFE))
  return true
end

-- Tam nhin bang fog modifier, KHONG sua truong cua unit.
--
-- Truoc day dung BlzSetUnitRealField(UNIT_RF_SIGHT_RADIUS). Da bo:
-- kiem tra hang so ~= nil khong chan duoc truong hop hang so ton tai
-- nhung SAI KIEU -- goi setter real len mot truong integer la ghi sai
-- bo nho, ACCESS_VIOLATION. Nha chinh dung yen nen mot vung sang co
-- dinh la tuong duong hoan toan, va chi dung native cu chac chan.
local function setHouseSight(radius)
  for i = 1, #S.pids do
    local fm = CreateFogModifierRadius(Player(S.pids[i]), FOG_OF_WAR_VISIBLE,
                                       S.houseX, S.houseY, radius, true, false)
    FogModifierStart(fm)
  end
  return "fog modifier"
end

-- Khong cho nha chinh tu tim muc tieu.
--
-- Truoc day dung BlzSetUnitIntegerField(UNIT_IF_ATTACKS_ENABLED, 0) --
-- da bo vi cung ly do o tren. SetUnitAcquireRange la native cu, co tu
-- doi dau: ban kinh 0 thi unit khong bao gio tu nham ai. No van danh
-- neu bi RA LENH danh, nhung slot so huu nha khong co nguoi dieu khien
-- nen khong bao gio co lenh do.
local function disableAttacks()
  SetUnitAcquireRange(S.house, 0.0)
  return true
end

local function createHouse()
  local r, realName = API.findRegion(CFG.RGN_HOUSE)
  if r == nil then
    API.regionMissing("CFG.RGN_HOUSE", API.regionLabel(CFG.RGN_HOUSE))
    return nil
  end
  S.houseRgnName = realName

  local x, y = API.regionCenter(r)
  API.trace("house: CreateUnit slot " .. CFG.HOUSE_SLOT)
  S.house = CreateUnit(houseOwner(), CFG.HOUSE_UNIT, x, y, CFG.HOUSE_FACE)
  if S.house == nil then
    API.msg(nil, CFG.C_RED .. "CreateUnit that bai -- kiem tra CFG.HOUSE_UNIT." .. CFG.C_END)
    return nil
  end
  S.houseX, S.houseY = x, y

  if CFG.HOUSE_SCALE ~= 1.0 then
    SetUnitScale(S.house, CFG.HOUSE_SCALE, CFG.HOUSE_SCALE, CFG.HOUSE_SCALE)
  end
  if BlzSetUnitName ~= nil then BlzSetUnitName(S.house, CFG.HOUSE_NAME) end

  -- Khoa kinh nghiem TRUOC khi dat mau, neu khong len cap se pha moc.
  API.trace("house: SuspendHeroXP")
  if CFG.HOUSE_SUSPEND_XP then SuspendHeroXP(S.house, true) end

  API.trace("house: setHP (BlzSetUnitMaxHP)")
  S.houseHpSet    = setHouseHP(CFG.HOUSE_HP)

  API.trace("house: setSight (fog modifier)")
  S.houseSightVia = setHouseSight(CFG.HOUSE_SIGHT)

  API.trace("house: disableAttacks (SetUnitAcquireRange)")
  if not CFG.HOUSE_CAN_ATTACK then
    S.houseNoAttack = disableAttacks()
  end

  API.trace("house: SetUnitInvulnerable")
  SetUnitInvulnerable(S.house, CFG.HOUSE_INVULNERABLE)

  -- Chot nha chinh tai cho. BA lop, vi khong lop nao mot minh du chac:
  --   SetUnitMoveSpeed(0)  Warcraft ep ve toc do toi thieu chu khong ve
  --                        0 han, nen day chi la lop giam thiet hai.
  --   "stop"               huy lenh di chuyen dang co san trong hang doi.
  --   PauseUnit(true)      chot han: unit khong nhan lenh nao nua.
  --
  -- PauseUnit KHONG lam no bat tu: unit bi chot van an sat thuong, van
  -- chet, van ban su kien chet -- nen duong thua van chay.
  if CFG.HOUSE_FROZEN then
    API.trace("house: FROZEN (move 0 + stop + PauseUnit)")
    if SetUnitMoveSpeed ~= nil then SetUnitMoveSpeed(S.house, 0.0) end
    if IssueImmediateOrder ~= nil then IssueImmediateOrder(S.house, "stop") end
    if PauseUnit ~= nil then PauseUnit(S.house, true) end
  end

  API.trace("house: XONG")
  return S.house
end

-- Goi tu 08_events khi nha chinh chet. Day la dieu kien thua DUY NHAT.
local function onHouseDeath()
  if not S.running then return end
  if not CFG.HOUSE_DEATH_ENDS_GAME then return end
  API.endGame(false, CFG.HOUSE_NAME .. " da bi pha huy.")
end

-- Chua cho quai ra. Buoc nay chi xac nhan vung ton tai va nho lai.
local function resolveEnemyRegion()
  local r, realName = API.findRegion(CFG.RGN_ENEMY)
  if r == nil then
    API.regionMissing("CFG.RGN_ENEMY", API.regionLabel(CFG.RGN_ENEMY))
    return nil
  end
  S.enemyRgnName = realName

  S.enemyRect = r
  S.enemyX, S.enemyY = API.regionCenter(r)
  return r
end

-- Diem nay roi vao block nao cua luoi 5x5 -- de doi chieu vung ve tay
-- trong World Editor voi luoi logic.
local function blockLabel(x, y)
  if x == nil then return "-" end
  local col, row = API.blockAt(x, y)
  if col == nil then
    if API.inRiver(x, y) then return "duoi song" end
    return "ngoai luoi"
  end
  return "block #" .. API.blockIndex(col, row) .. " (" .. col .. "," .. row .. ")"
end

local function report()
  local rgns = API.listRegions()
  API.msg(nil, CFG.C_GOLD .. "=== Vung & nha chinh ===" .. CFG.C_END)
  API.msg(nil, "Vung WE thay duoc (" .. #rgns .. "): " .. table.concat(rgns, ", "))

  if S.house ~= nil then
    API.msg(nil, "Nha chinh : " .. API.num(S.houseX) .. ", " .. API.num(S.houseY) ..
      "  -- " .. blockLabel(S.houseX, S.houseY) ..
      CFG.C_GREY .. "  [vung " .. tostring(S.houseRgnName) .. "]" .. CFG.C_END)
    API.msg(nil, "  chu     : slot " .. CFG.HOUSE_SLOT ..
      ", dong minh voi " .. #S.pids .. " nguoi choi")
    API.msg(nil, "  mau     : " .. API.num(GetUnitState(S.house, UNIT_STATE_MAX_LIFE)) ..
      (S.houseHpSet and "" or CFG.C_RED .. " (dat that bai: can 1.31+)" .. CFG.C_END))
    API.msg(nil, "  tam nhin: " .. API.num(CFG.HOUSE_SIGHT) ..
      " qua " .. tostring(S.houseSightVia))
    API.msg(nil, "  don danh: " ..
      (CFG.HOUSE_CAN_ATTACK and "con" or "khong tu nham (acquire range 0)"))
    API.msg(nil, "  chet     : " ..
      (CFG.HOUSE_INVULNERABLE and (CFG.C_GOLD .. "bat tu, khong chet duoc" .. CFG.C_END)
       or (CFG.HOUSE_DEATH_ENDS_GAME and "thua ngay" or "khong sao")))
  end

  if S.enemyRect ~= nil then
    API.msg(nil, "Vung dich : " .. API.num(S.enemyX) .. ", " .. API.num(S.enemyY) ..
      "  -- " .. blockLabel(S.enemyX, S.enemyY) ..
      CFG.C_GREY .. "  [vung " .. tostring(S.enemyRgnName) ..
      "]  (chua cho quai ra)" .. CFG.C_END)
  end
end

API.blockLabel         = blockLabel
API.createHouse        = createHouse
API.onHouseDeath       = onHouseDeath
API.resolveEnemyRegion = resolveEnemyRegion
API.setHouseHP         = setHouseHP
API.report             = report
end
--#endregion 3_tran_dau/1_house.lua

--#region 3_tran_dau/2_wave.lua
do
-- ============================================================
--  2_wave.lua  --  220 stage
--
--  Luat: docs/02-he-thong/dot-quai.md
--  Duong cong: docs/03-du-lieu/duong-cong-suc-manh.md
--
--  MOT bien stage duy nhat, 1..220. Canh gioi va tang deu SUY RA tu no
--  -- giu hai bien song song la chung se lech nhau.
--
--  Nho: goi ham cua file khac phai qua API.
-- ============================================================

-- ---------- Chi so hoa stage ----------
-- Mot canh gioi = TIERS_PER_REALM tang + 1 boss. So 11 khong hard-code.
local function stagesPerRealm()
  return CFG.TIERS_PER_REALM + 1
end

local function totalStages()
  return #CFG.REALMS * stagesPerRealm()
end

-- Tra ve: canh gioi 1..20, tang 1..10, co phai boss khong
local function decode(stage)
  local per   = stagesPerRealm()
  local realm = math.floor((stage - 1) / per) + 1
  local k     = ((stage - 1) % per) + 1
  local isBoss = (k == per)
  local tier   = isBoss and CFG.TIERS_PER_REALM or k
  return realm, tier, isBoss
end

local function realmName(realm)
  return API.pick(CFG.REALMS[realm])
end

-- Tang cua mot stage, thanh chu: "So Ki", "Vien Man", hoac "BOSS".
--
-- Bon tang co TEN rieng (CFG.TIER_NAMES) chu khong danh so: "Truc Co So
-- Ki" doc ra nghia ngay, con "Truc Co Tang 3" thi phai nho tang 3 tren
-- tong bao nhieu.
--
-- Lui ve danh so neu bang ten thieu phan tu -- doi TIERS_PER_REALM ma
-- quen them ten thi van chay, chi la ten xau, chu khong no loi.
--
-- Chu o day di qua API.t/API.pick chu khong go thang: truoc day
-- stageLabel noi " tang " bang tieng Viet ngay ca khi CFG.LANG = "en",
-- nen ban tieng Anh hien ra "Mortal tang 4".
local function tierLabel(stage)
  local _, tier, isBoss = decode(stage)
  if isBoss then return API.t("stage_boss") end
  local ten = CFG.TIER_NAMES and CFG.TIER_NAMES[tier] or nil
  if ten ~= nil then return API.pick(ten) end
  if tier >= CFG.TIERS_PER_REALM then return API.t("tier_full") end
  return API.t("tier_word") .. " " .. tier
end

-- Ten quai = canh gioi + TANG + hau to theo loai.
--
-- Co TANG trong ten vi khong co no thi ca 5 stage cua mot canh gioi ra
-- cung mot cai ten. Ma quai don lai qua nhieu wave (do duoc: stage 6
-- con 174 con song), nen tren map luc nao cung co vai the he cung luc
-- -- nhin vao mot con khong biet no thuoc dot nao, cung khong biet no
-- dang o dung gia tri thuong cua stage nao.
--
-- Boss khong can tang: no la lan do kiep DUY NHAT cua canh gioi do.
--
-- 20 canh gioi x 4 tang x 2 loai + 20 boss = 180 ten, sinh ra tu 20 ten
-- canh gioi + 4 ten tang + 3 hau to -- khong phai 180 unit type.
--
-- BlzSetUnitName doi ten TUNG con luc chay, nen doi tieng khong phai
-- dung toi Object Editor. Thieu native thi quai giu ten goc cua mau
-- lam no ("Footman", "Ghoul"...) -- 5_natives.lua do va bao truoc.
local function mobName(stage, kind)
  local realm = decode(stage)
  if kind == "boss" then
    return realmName(realm) .. " - " .. API.t("boss_suffix")
  end
  local hau = (kind == "elite") and "elite_suffix" or "mob_suffix"
  return realmName(realm) .. " " .. tierLabel(stage) .. " - " .. API.t(hau)
end

local function realmCoi(realm)
  local r = CFG.REALMS[realm]
  if r == nil then return 1 end
  return r.coi
end

-- Chu hien cho nguoi choi: "Truc Co Tang 4" hoac "Truc Co Vien Man".
-- Cung mot nguon voi ten quai, nen dong bao wave va con quai tren map
-- khong the goi khac nhau.
local function stageLabel(stage)
  local realm = decode(stage)
  return realmName(realm) .. " " .. tierLabel(stage)
end

-- ---------- Duong cong ----------

local function ehpOf(stage, realm)
  return CFG.MOB_EHP_BASE
       * CFG.MOB_EHP_GROWTH ^ (stage - 1)
       * CFG.MOB_EHP_REALM_STEP ^ (realm - 1)
end

local function dmgOf(stage, realm)
  return CFG.MOB_DMG_BASE
       * CFG.MOB_DMG_GROWTH ^ (stage - 1)
       * CFG.MOB_DMG_REALM_STEP ^ (realm - 1)
end

local function armorOf(realm)
  return CFG.MOB_ARMOR_BASE + CFG.MOB_ARMOR_PER_REALM * (realm - 1)
end

-- Duong cong sinh ra EHP; MAU THAT suy nguoc ra tu giap. Cong giap o
-- dau thi chia mau o do. (ADR 0010)
local function hpFromEhp(ehp, armor)
  return ehp / (1 + CFG.ARMOR_DR_PER_POINT * armor)
end

-- So nguoi choi dang song, dem lai moi wave (ADR 0009).
local function playerCount()
  if not CFG.SCALE_RECOUNT_EACH_WAVE then return #S.pids end
  local n = API.activeCount()
  if n < 1 then n = 1 end
  return n
end

-- ---------- Sinh quai ----------

local function applyStats(u, ehp, dmg, armor)
  local hp = math.floor(hpFromEhp(ehp, armor) + 0.5)
  if hp < 1 then hp = 1 end

  if BlzSetUnitMaxHP ~= nil then
    BlzSetUnitMaxHP(u, hp)
    SetUnitState(u, UNIT_STATE_LIFE, GetUnitState(u, UNIT_STATE_MAX_LIFE))
  end
  if BlzSetUnitArmor ~= nil then
    BlzSetUnitArmor(u, armor)
  end
  if BlzSetUnitBaseDamage ~= nil then
    BlzSetUnitBaseDamage(u, math.floor(dmg + 0.5), 0)
  end
end

local function spawnPoint()
  if S.enemyX ~= nil then
    local jx = GetRandomReal(-CFG.SPAWN_JITTER, CFG.SPAWN_JITTER)
    local jy = GetRandomReal(-CFG.SPAWN_JITTER, CFG.SPAWN_JITTER)
    return API.clampToMap(S.enemyX + jx, S.enemyY + jy)
  end
  return API.blockCenter(3, 3)
end

local function sendToHouse(u)
  if S.houseX == nil then return end
  IssuePointOrder(u, "attack", S.houseX, S.houseY)
end

-- kind: "mob" | "elite" | "boss"
local function spawnOne(stage, realm, kind)
  local uid = CFG.MOB_UNIT[realmCoi(realm)]
  if uid == nil then return nil end

  local x, y = spawnPoint()
  local face = API.angleXY(x, y, S.houseX or x, S.houseY or y)
  local u = CreateUnit(S.enemy, uid, x, y, face)
  if u == nil then
    S.wave.spawnFail = (S.wave.spawnFail or 0) + 1
    return nil
  end

  local P     = S.wave.players
  local ehp   = ehpOf(stage, realm) * (1 + CFG.SCALE_EHP_PER_PLAYER * (P - 1))
  local dmg   = dmgOf(stage, realm) * (1 + CFG.SCALE_DMG_PER_PLAYER * (P - 1))
  local armor = armorOf(realm)

  if kind == "elite" then
    ehp = ehp * CFG.ELITE_EHP
    dmg = dmg * CFG.ELITE_DMG
    SetUnitScale(u, CFG.ELITE_SCALE, CFG.ELITE_SCALE, CFG.ELITE_SCALE)
    SetUnitVertexColor(u, 255, 210, 120, 255)
  elseif kind == "boss" then
    -- Boss dung he so rieng: mot than, dong nguoi don ha hieu qua hon.
    ehp = ehpOf(stage, realm) * CFG.BOSS_EHP
        * (1 + CFG.SCALE_BOSS_EHP_PER_PLAYER * (P - 1))
    dmg = dmgOf(stage, realm) * CFG.BOSS_DMG
        * (1 + CFG.SCALE_DMG_PER_PLAYER * (P - 1))
    SetUnitScale(u, CFG.BOSS_SCALE, CFG.BOSS_SCALE, CFG.BOSS_SCALE)
    SetUnitVertexColor(u, 255, 120, 120, 255)
  end

  applyStats(u, ehp, dmg, armor)
  if BlzSetUnitName ~= nil then BlzSetUnitName(u, mobName(stage, kind)) end
  S.mobs[u] = kind
  -- Ghi lai stage luc SINH, khong dung stage hien tai luc chet.
  -- Quai don lai qua nhieu wave (do duoc: stage 6 con 174 con song),
  -- nen tra theo stage hien tai la tu thuong them cho viec giet cham.
  S.mobStage[u] = stage
  S.alive = S.alive + 1
  sendToHouse(u)
  return u
end

-- ---------- Kinh te ----------
--
-- Ba ham cu -- waveIncome(), bountyOf(), payBounty() -- da xoa het.
--
-- Chung ton tai de giai MOT bai toan: thu nhap la duong cong mu
-- 60 x 1.0319^(stage-1), chia cho 50 con, nen o stage 1 mot con dang
-- gia 0.72 Linh Khi. Lam tron xuong la ca wave dau duoc 0 dong; lam
-- tron len la thu nhap dau game vot 23%. Nen phai giu so thuc va cong
-- don phan le.
--
-- Thu nhap gio PHANG: mot con dung mot dong. Khong con phan le nao de
-- cong don, nen ca ba ham thanh thua. rewardAll() goi thang
-- API.addLinhKhi / addVang / addGo.
--
-- He so x1.25 cua Phap Khi "Tu Linh Tran" mat theo, va do la dung: he
-- Phap Khi dang khoa (CFG.PHAPKHI_LOCKED).

-- ---------- Mot wave ----------

-- Mau nha tinh lai moi wave theo sat thuong mot con linh o stage do.
-- Khong tinh lai thi den canh gioi 5 nha da thanh giay.
--
-- Giu nguyen TI LE mau dang co, roi hoi them REGEN_PER_WAVE -- neu dat
-- lai day mau moi wave thi lot bao nhieu cung khong sao.
local function rescaleHouse(stage, realm)
  if S.house == nil or BlzSetUnitMaxHP == nil then return end

  local oldMax = GetUnitState(S.house, UNIT_STATE_MAX_LIFE)
  local ratio  = 1.0
  if oldMax > 0 then
    ratio = GetUnitState(S.house, UNIT_STATE_LIFE) / oldMax
  end

  local P = S.wave.players
  local newMax = CFG.HOUSE_HP_HITS * dmgOf(stage, realm)
               * (1 + CFG.SCALE_DMG_PER_PLAYER * (P - 1))

  -- Hai Phap Khi cong vao nha chinh. Nha la cua CHUNG, nen chi can MOT
  -- nguoi mua la ca doi duoc -- do la ly do chung dat gia cao hon hai
  -- mon ca nhan o tren.
  local bonusMax, bonusRegen = 0.0, 0.0
  if API.phapKhiAiCo ~= nil then
    if API.phapKhiAiCo("nhahp")    then bonusMax   = 0.30 end
    if API.phapKhiAiCo("nharegen") then bonusRegen = 0.15 end
  end
  newMax = math.floor(newMax * (1 + bonusMax) + 0.5)
  if newMax < 1 then newMax = 1 end

  BlzSetUnitMaxHP(S.house, newMax)
  local heal = ratio + CFG.HOUSE_REGEN_PER_WAVE + bonusRegen
  if heal > 1.0 then heal = 1.0 end
  SetUnitState(S.house, UNIT_STATE_LIFE, newMax * heal)
end

local function spawnStage(stage)
  local realm, tier, isBoss = decode(stage)

  S.stage = stage
  S.wave.players = playerCount()
  S.wave.spawnFail = 0
  rescaleHouse(stage, realm)

  if isBoss then
    spawnOne(stage, realm, "boss")
    API.msg(nil, CFG.C_RED .. API.t("boss_coming", realmName(realm)) .. CFG.C_END)
    API.msg(nil, "   " .. CFG.C_JADE .. mobName(stage, "boss") .. CFG.C_END)
  else
    for _ = 1, CFG.WAVE_MOB_COUNT do spawnOne(stage, realm, "mob") end
    for _ = 1, CFG.WAVE_ELITE_COUNT do spawnOne(stage, realm, "elite") end
    API.msg(nil, CFG.C_GOLD .. "[" .. stage .. "/" .. totalStages() .. "] " ..
      stageLabel(stage) .. CFG.C_END)

    -- Ghi ro wave nay gom NHUNG GI, bang dung cai ten dang nam tren con
    -- quai. Mot wave co hai loai ma dong bao chi noi mot cau chung thi
    -- nguoi choi khong doi chieu duoc cai minh nhin thay voi cai vua doc.
    API.msg(nil, "   " .. CFG.C_GREY .. API.t("wave_comp",
      CFG.WAVE_MOB_COUNT,   mobName(stage, "mob"),
      CFG.WAVE_ELITE_COUNT, mobName(stage, "elite")) .. CFG.C_END)
  end

  if S.wave.spawnFail > 0 then
    API.msg(nil, CFG.C_RED .. "Khong sinh duoc " .. S.wave.spawnFail ..
      " con -- kiem tra CFG.MOB_UNIT." .. CFG.C_END)
  end
  API.trace("stage " .. stage .. " (" .. stageLabel(stage) .. ") P=" ..
            S.wave.players .. " song=" .. S.alive)
end

local function waveSeconds(stage)
  local realm = decode(stage)
  return CFG.WAVE_TIME[realmCoi(realm)] or 30.0
end

-- Dong ho KHONG duoc phep chong dot len nhau: xem CFG.WAVE_ONLY_WHEN_CLEAR.
local function onWaveTimer()
  if not S.running then return end

  local nextStage = S.stage + 1
  if nextStage > totalStages() then
    API.endGame(true, API.t("win_final", realmName(#CFG.REALMS)))
    return
  end

  -- CHAN CHINH: con mot con song thi khong dot nao moi duoc ra.
  --
  -- Bao MOT lan roi im, va tat dong ho dem di. Bao moi nhip WAVE_TICK
  -- la lap chu day man hinh; con de dong ho dung yen o 0:00 thi nguoi
  -- choi tuong game treo -- dung loi ma pauseWaves() da phai xu ly.
  if CFG.WAVE_ONLY_WHEN_CLEAR and S.alive > 0 then
    if not S.waveHold then
      S.waveHold = true
      if S.waveDlg ~= nil then TimerDialogDisplay(S.waveDlg, false) end
      API.msg(nil, CFG.C_GREY .. API.t("wave_hold", S.alive) .. CFG.C_END)
      API.trace("wave: HOAN dot " .. nextStage .. ", con song " .. S.alive)
    end
    TimerStart(S.waveTimer, CFG.WAVE_TICK, false, onWaveTimer)
    return
  end
  S.waveHold = false

  -- Boss chiem TRON stage, mot minh (L4 trong dot-quai.md). Neu dong ho
  -- het gio ma tang 10 chua don xong thi HOAN, dung sinh boss de len
  -- dam linh con song -- lam vay la pha dung cai luat khien tran boss
  -- co cam giac khac han mot wave.
  local _, _, nextIsBoss = decode(nextStage)
  if nextIsBoss and S.alive > 0 then
    TimerStart(S.waveTimer, CFG.WAVE_TICK, false, onWaveTimer)
    return
  end

  -- Chi con y nghia khi WAVE_ONLY_WHEN_CLEAR tat.
  if S.alive >= CFG.WAVE_MAX_ALIVE then
    API.msg(nil, CFG.C_GREY .. API.t("wave_hold", S.alive) .. CFG.C_END)
    TimerStart(S.waveTimer, CFG.WAVE_TICK, false, onWaveTimer)
    return
  end

  spawnStage(nextStage)
  TimerStart(S.waveTimer, waveSeconds(nextStage), false, onWaveTimer)
end

-- ---------- Nhip 2 giay: ra lenh lai ----------
-- Quai bi danh lac huong khong tu quay ve nha.

local function tick()
  if not S.running or S.houseX == nil then return end
  for u, _ in pairs(S.mobs) do
    if u ~= nil and API.alive(u) then sendToHouse(u) end
  end
end

-- Dua dong quai ke tiep ve NGAY. Goi tu lenh -next, tu luc moi nguoi
-- chon xong hero, va tu luc don sach wave.
--
-- Khong goi thang onWaveTimer(): lam vay thi bo dem cu van chay va mot
-- luc nua lai no them mot dot nua. Phai dung no truoc.
local function waveNow()
  if not S.running or S.waveTimer == nil then
    API.trace("waveNow: TU CHOI -- running=" .. tostring(S.running) ..
              " timer=" .. tostring(S.waveTimer ~= nil))
    return false
  end
  API.trace("waveNow: keo dot ke tiep (stage hien tai " .. S.stage ..
            ", cho=" .. tostring(S.waitNext) .. ")")
  S.waitNext = nil
  S.waveHold = false
  if S.waveDlg ~= nil then TimerDialogDisplay(S.waveDlg, true) end
  PauseTimer(S.waveTimer)
  TimerStart(S.waveTimer, 0.02, false, onWaveTimer)
  return true
end

-- ---------- Phat thuong ----------
--
-- MOI phan thuong di qua day. Quai thuong, tinh anh, boss -- ca hai loai
-- tien -- deu chia deu cho MOI nguoi choi, khong phu thuoc ai ket lieu.
-- Xem ADR 0013.
--
-- Mot cho duy nhat, vi truoc day Linh Khi va Tinh Thach moi cai mot vong
-- lap rieng: thu them mot loai thuong nua la quen mot cho.
local function rewardAll(stage, kind)
  -- Ba loai quai, ba dong tien. So PHANG, khong theo stage:
  --
  --   linh thuong -> 1 Linh Khi + 1 Vang   (nhip giay)
  --   tinh anh    -> 1 Go                  (nhip wave)
  --   boss        -> 5 Go                  (nhip canh gioi)
  --
  -- Moi loai quai mo khoa dung mot he, nen ba he bi chan boi ba loai
  -- NOI DUNG khac nhau chu khong chi boi mot cai vi:
  --   Linh Khi -> Linh Can   Vang -> Shop   Go -> Ky Nang
  --
  -- Xem docs/02-he-thong/kinh-te.md
  local lk, vang, go = 0, 0, 0
  if kind == "boss" then
    go = CFG.THUONG_BOSS_GO
  elseif kind == "elite" then
    go = CFG.THUONG_ELITE_GO
  else
    lk   = CFG.THUONG_MOB_LINHKHI
    vang = CFG.THUONG_MOB_VANG
  end

  for i = 1, #S.pids do
    local pid = S.pids[i]
    if S.p[pid] ~= nil and S.p[pid].active then
      if lk > 0 then API.addLinhKhi(pid, lk) end
      if vang > 0 then API.addVang(pid, vang) end
      if go > 0 then
        local n = go
        if kind == "elite" and API.phapKhiCo ~= nil
           and API.phapKhiCo(pid, "go") then n = n + 1 end
        API.addGo(pid, n)
      end
    end
  end
  -- Ve lai bang khi mot dong tien DOI BAC: Go nhay tung diem mot nen
  -- moi diem deu dang ke. Linh Khi va Vang nhay 1 moi con, ve lai moi
  -- con la ve lai 50 lan mot wave -- de nhip refresh cua bang lo.
  if go > 0 then API.panelRefreshAll() end

  if kind == "boss" then
    API.msg(nil, CFG.C_JADE .. API.t("boss_down", realmName(realm), tt) .. CFG.C_END)
  end
end

-- ---------- Nghi giua hai canh gioi ----------
--
-- Dung HAN dong ho va an dong ho dem. An la co y: mot cai dong ho dung
-- yen o 0:00 chi lam nguoi choi tuong game treo, dung loi ma
-- WAVE_WAIT_FIRST da phai xu ly mot lan.
local function pauseWaves(what)
  S.waitNext = what
  if S.waveTimer ~= nil then PauseTimer(S.waveTimer) end
  if S.waveDlg ~= nil then TimerDialogDisplay(S.waveDlg, false) end
  API.trace("wave: DUNG dong ho o stage " .. S.stage .. ", cho '" .. what .. "'")
end

-- ---------- Goi tu 08_events khi mot con chet ----------

local function onMobDeath(u, killer)
  local kind = S.mobs[u]
  if kind == nil then return end

  S.mobs[u] = nil
  S.alive = S.alive - 1
  if S.alive < 0 then S.alive = 0 end

  local stage = S.mobStage[u] or S.stage
  S.mobStage[u] = nil

  rewardAll(stage, kind)

  -- Con cuoi cung cua stage vua chet.
  -- Chi xet o day chu khong dat trong timer -- toi duoc day nghia la
  -- chac chan da tung co quai, nen S.alive = 0 la "don sach" that,
  -- khong phai "wave sinh hong khong con nao".
  if S.alive ~= 0 or S.stage <= 0 or not S.running then return end

  if API.phapKhiOnClear ~= nil then API.phapKhiOnClear() end

  local r, tier, wasBoss = decode(S.stage)

  -- MOC 1: vua ha boss -> dung han, cho -next sang canh gioi sau.
  if CFG.WAVE_REST and wasBoss and S.stage < totalStages() then
    pauseWaves("realm")
    API.msg(nil, CFG.C_GOLD ..
      API.t("wave_realmdone", realmName(r + 1)) .. CFG.C_END)
    return
  end

  -- MOC 2: vua don sach tang cuoi -> dung han, cho -next goi boss.
  if CFG.WAVE_REST and (not wasBoss) and tier >= CFG.TIERS_PER_REALM then
    pauseWaves("boss")
    API.msg(nil, CFG.C_GOLD ..
      API.t("wave_vienman", realmName(r)) .. CFG.C_END)
    return
  end

  -- Binh thuong: bao da don sach roi keo dot sau vao som.
  if CFG.WAVE_AUTO_NEXT then
    API.msg(nil, CFG.C_JADE .. API.t("wave_cleared") .. CFG.C_END)
    API.after(CFG.WAVE_CLEAR_DELAY, function()
      if S.alive == 0 and S.waitNext == nil then waveNow() end
    end)
  end
end

-- ---------- Khoi dong ----------

-- Goi khi mot nguoi vua chon hero xong. Dot dau khong cho het 15 giay
-- neu moi nguoi da san sang -- 15 giay do la de CHO CHON HERO, khong
-- phai mot phan cua nhip choi.
local function readyCheck()
  if CFG.WAVE_WAIT_FIRST then return end   -- dot 1 doi goi tay
  if not S.running or S.stage > 0 then return end
  local n = 0
  for i = 1, #S.pids do
    local d = S.p[S.pids[i]]
    if d ~= nil and d.active then
      if d.hero == nil then return end   -- con nguoi chua chon
      n = n + 1
    end
  end
  if n == 0 then return end
  API.trace("wave: ca " .. n .. " nguoi da co hero -- vao dot 1 ngay")
  waveNow()
end

local function startWaves()
  S.stage = 0
  S.mobs  = {}
  S.mobStage = {}
  S.alive = 0
  S.wave  = { players = 1, spawnFail = 0 }

  S.waveTimer = CreateTimer()
  S.waveDlg = CreateTimerDialog(S.waveTimer)
  TimerDialogSetTitle(S.waveDlg, API.t("wave_next"))

  if CFG.WAVE_WAIT_FIRST then
    -- Khong khoi dong bo dem. Dong ho an luon: hien mot cai dem 0:00
    -- dung yen chi lam nguoi choi tuong game treo.
    TimerDialogDisplay(S.waveDlg, false)
    API.msg(nil, CFG.C_GOLD .. API.t("wave_waiting") .. CFG.C_END)
  else
    TimerDialogDisplay(S.waveDlg, true)
    TimerStart(S.waveTimer, CFG.WAVE_FIRST_DELAY, false, onWaveTimer)
  end

  S.tickTimer = CreateTimer()
  TimerStart(S.tickTimer, CFG.WAVE_TICK, true, tick)

  API.trace("wave: khoi dong, " .. totalStages() .. " stage")
end

local function stopWaves()
  if S.waveTimer ~= nil then PauseTimer(S.waveTimer) end
  if S.tickTimer ~= nil then PauseTimer(S.tickTimer) end
  if S.waveDlg ~= nil then TimerDialogDisplay(S.waveDlg, false) end
end

-- Lenh dev "-wave N": nhay thang toi stage N. Khong co no thi khong ai
-- kiem duoc stage 180.
local function jumpTo(stage)
  if stage < 1 then stage = 1 end
  if stage > totalStages() then stage = totalStages() end
  S.stage = stage - 1
  TimerStart(S.waveTimer, 0.5, false, onWaveTimer)
end

API.stagesPerRealm = stagesPerRealm
API.totalStages    = totalStages
API.decodeStage    = decode
API.realmName      = realmName
API.stageLabel     = stageLabel
API.tierLabel      = tierLabel
API.ehpOf          = ehpOf
API.dmgOf          = dmgOf
API.armorOf        = armorOf
API.mobName        = mobName
API.waveNow        = waveNow
API.waveWaiting    = function() return S.waitNext end
API.waveReadyCheck = readyCheck
API.onMobDeath     = onMobDeath
API.startWaves     = startWaves
API.stopWaves      = stopWaves
API.jumpToStage    = jumpTo
end
--#endregion 3_tran_dau/2_wave.lua

--#region 4_giao_dien/1_panel.lua
do
-- ============================================================
--  1_panel.lua  --  Bang nhan vat (phim R -- xem CFG.PANEL_KEY)
--
--  MOT khung, bon the. Moi he tu dang ky noi dung cua minh qua
--  API.panelAddTab -- khung khong biet gi ve Linh Can hay Ky Nang.
--
--  HAI KIEU THAN BANG, khong phai mot.
--
--  Ban truoc chi co mot kieu: bang tinh hang x o, moi the tu khai bao
--  cot cua no, va mot nut "+" rong 0.028 o mep phai. Bon he thi khong
--  cung hinh dang, nen ep ca bon vao bang tinh lam cai nao cung do:
--
--    Linh Can  la mot cai thang co DUNG MOT hanh dong (dot pha len bac
--              ke). Bang tinh hien 7 dong, ma 6 dong khong bam duoc --
--              thong tin tham khao chen cho dung mot viec lam duoc.
--    Ky Nang   la 7 mon nang cap doc lap. Nam cot chia 680px thi cot
--              "Bac" con 81px, va chu dai tran sang cot ben.
--    Trang Bi  6 mon, Phap Khi 5 mon -- cung hinh dang voi Ky Nang.
--
--  Nen: "list" (3/4 the) va "focus" (1/4 the). The khai bao DU LIEU,
--  bang lo BO CUC -- nguoc han ban truoc, noi the phai khai bao cot.
--
--  Nho vay them mot he moi khong phai dung them bang, cung khong phai
--  do be ngang cot: tra ve mot danh sach muc la xong.
--
--  Mo/dong va doi the la UI THUAN -> lam cuc bo duoc, khong can dong
--  bo. Chi HANH DONG (dot pha, nang cap, mua) moi phai qua
--  BlzSendSyncData, va do la viec cua tung he.
--
--  Nho: goi ham cua file khac phai qua API.
-- ============================================================

local TAB_H  = 0.026
local HEAD_H = 0.022    -- dong tien
-- KHONG CON NUT CLOSE. Dong bang ESC, hoac bam lai phim mo bang.
--
-- Nut cu nam o chan khung va bam khong an: thanh giao dien duoi cua
-- Warcraft phu khoang 0.12 duoi man hinh va an TREN frame cua ta, nen
-- no nuot cu bam truoc khi toi duoc nut. Frame bi che mot phan van
-- "nhin thay duoc" nen nhin thi khong ra loi.
--
-- Doi len dinh khung thi het loi, nhung mot phim ESC van gon hon mot
-- cai nut phai ram chuot toi -- va ESC la thu nguoi choi bam theo phan
-- xa de dong bat cu thu gi. Nen bo han nut, giu mot dong chu nho chi
-- cho biet bam gi.
local GAP    = 0.006
local LINE   = 0.016    -- khoang cach hai dong chu trong mot muc

-- Cao than bang o kieu "focus". Bang phai CAO BANG NHAU o moi the,
-- neu khong doi the mot cai la khung nhay -- nen lay max voi kieu list.
local FOCUS_H = 0.200

-- Le trong THAT = le + vien trang tri cua backdrop. Moi thu ben trong
-- dung con so nay, nen doi backdrop chi phai sua mot cho.
local function PAD()   return CFG.PANEL_PAD + (CFG.PANEL_BORDER or 0.0) end
local function ROW()   return CFG.PANEL_ROW end
local function ICON()  return CFG.PANEL_ICON end
local function BTN_W() return CFG.PANEL_BTN_W end
local function BTN_H() return CFG.PANEL_BTN_H end

-- Bao nhieu dong phai dung san. Tinh tu the dai nhat da dang ky, chu
-- khong go tay: them mot he 9 muc thi bang tu no rong ra.
local MAX_ITEMS = 1

local function bodyH()
  local list = MAX_ITEMS * ROW()
  return (list > FOCUS_H) and list or FOCUS_H
end

local function panelH()
  return PAD() + TAB_H + GAP + HEAD_H + GAP + bodyH() + PAD()
end

local function tabTop()
  return PAD()
end

local function bodyTop()
  return tabTop() + TAB_H + GAP + HEAD_H + GAP
end

-- Be ngang phan chu cua mot muc: tru icon ben trai va nut ben phai.
local function textW()
  return CFG.PANEL_W - 2 * PAD() - ICON() - 0.008 - BTN_W() - 0.008
end

-- So La Ma cho nhan the: I. Linh Can, II. Ky Nang, ...
local ROMAN = { "I", "II", "III", "IV", "V", "VI", "VII", "VIII" }

local FRAME_OK = nil

local function framesAvailable()
  if FRAME_OK ~= nil then return FRAME_OK end
  FRAME_OK = (BlzGetOriginFrame ~= nil and BlzCreateFrameByType ~= nil
          and BlzFrameSetAbsPoint ~= nil and BlzFrameSetPoint ~= nil
          and BlzFrameSetSize ~= nil and BlzFrameSetTexture ~= nil
          and BlzFrameSetVisible ~= nil and BlzFrameSetText ~= nil
          and BlzTriggerRegisterFrameEvent ~= nil and BlzGetTriggerFrame ~= nil
          and ORIGIN_FRAME_GAME_UI ~= nil and FRAMEEVENT_CONTROL_CLICK ~= nil
          and FRAMEPOINT_CENTER ~= nil and FRAMEPOINT_TOPLEFT ~= nil)
  if not FRAME_OK then API.trace("panel: THIEU native frame") end
  return FRAME_OK
end

-- ---------- Dang ky the ----------
--
-- kind = "list":
--   items(pid) -> { { icon, ten, mota, trangThai, nut, batNut }, ... }
--   itemAction(pid, i)
--   trong  -- chu hien khi items rong
--
-- kind = "focus":
--   info(pid) -> { tieuDe, phu, dong = { {nhan, truoc, sau}, ... },
--                  tienDo (0..1), ghiChu, nut, batNut }
--   action(pid)

local function addTab(tab)
  if tab.kind == nil then tab.kind = "list" end
  S.panel.tabs[#S.panel.tabs + 1] = tab
  return #S.panel.tabs
end

-- The chua lam: hien ro la chua lam thay vi de trong. Mot the trong
-- khien nguoi choi tuong giao dien hong.
local function placeholderTab(ten, mota)
  return {
    ten   = ten,
    kind  = "list",
    items = function() return {} end,
    trong = CFG.C_GREY .. API.t("panel_empty") .. CFG.C_END .. "  " .. mota,
  }
end

-- ---------- Trang thai ----------

local function stateOf(pid)
  if S.panel.byPid[pid] == nil then
    S.panel.byPid[pid] = { panel = nil, money = nil, tabBtn = {},
                           item = {}, focus = nil,
                           tab = 1, shown = false }
  end
  return S.panel.byPid[pid]
end

-- ---------- Ve lai ----------

local function setEnabled(f, on)
  if f ~= nil and BlzFrameSetEnable ~= nil then BlzFrameSetEnable(f, on) end
end

local function show(f, on)
  if f ~= nil then BlzFrameSetVisible(f, on) end
end

local function refreshList(st, pid, tab)
  local items = (tab.items and tab.items(pid)) or {}

  for i = 1, MAX_ITEMS do
    local it = items[i]
    local w  = st.item[i]
    if w ~= nil then
      local co = (it ~= nil)
      show(w.bg, co and (i % 2 == 0))
      show(w.name, co)
      show(w.state, co)
      show(w.sub, co)
      show(w.icon, co and it.icon ~= nil)
      show(w.btn, co and it.nut ~= nil)

      if co then
        if it.icon ~= nil then BlzFrameSetTexture(w.icon, it.icon, 0, true) end
        BlzFrameSetText(w.name,  CFG.C_GOLD .. (it.ten or "?") .. CFG.C_END)
        BlzFrameSetText(w.state, it.trangThai or "")
        BlzFrameSetText(w.sub,   CFG.C_GREY .. (it.mota or "") .. CFG.C_END)
        if it.nut ~= nil then
          -- Chu XAM khi khong du tien. Vien va ruot la o mau tu ve nen
          -- BlzFrameSetEnable khong doi mau chung -- khong lam gi thi
          -- nut bam duoc va nut mo trong y het nhau.
          BlzFrameSetText(w.btnTxt, (it.batNut ~= false) and it.nut
                                    or (CFG.C_GREY .. it.nut .. CFG.C_END))
          -- Nut mo di khi khong du tien: van THAY duoc gia, chi khong
          -- bam duoc. An han nut thi nguoi choi khong biet mon do ton
          -- bao nhieu de ma de danh.
          setEnabled(w.btn, it.batNut ~= false)
        end
      end
    end
  end

  -- Dong "chua co gi" cho the giu cho.
  show(st.empty, #items == 0)
  if #items == 0 and st.empty ~= nil then
    BlzFrameSetText(st.empty, tab.trong or "")
  end
end

local function refreshFocus(st, pid, tab)
  local f = st.focus
  if f == nil then return end
  local d = (tab.info and tab.info(pid)) or {}

  BlzFrameSetText(f.tieuDe, CFG.C_GOLD .. (d.tieuDe or "") .. CFG.C_END)
  BlzFrameSetText(f.phu,    CFG.C_JADE .. (d.phu or "") .. CFG.C_END)

  local dong = d.dong or {}
  for i = 1, #f.dong do
    local r = f.dong[i]
    local v = dong[i]
    show(r.ke, v ~= nil)
    show(r.nhan, v ~= nil)
    show(r.truoc, v ~= nil)
    show(r.sau, v ~= nil)
    if v ~= nil then
      BlzFrameSetText(r.nhan,  CFG.C_GREY .. (v[1] or "") .. CFG.C_END)
      BlzFrameSetText(r.truoc, v[2] or "")
      -- Mui ten nam trong cung frame voi gia tri sau, de khong phai do
      -- be ngang cua gia tri truoc moi biet dat mui ten o dau.
      BlzFrameSetText(r.sau,   CFG.C_GREY .. "->  " .. CFG.C_END ..
                               CFG.C_JADE .. (v[3] or "") .. CFG.C_END)
    end
  end

  local p = d.tienDo or 0.0
  if p < 0.0 then p = 0.0 elseif p > 1.0 then p = 1.0 end
  local full = CFG.PANEL_W - 2 * PAD()
  -- NEN phai hien -- backdropFrame() tao ra o trang thai an, va truoc
  -- day khong ai bat no len. Ket qua: chi thay o vang cua phan da day,
  -- lo lung khong ro no la thanh gi. Mot thanh tien do khong co nen thi
  -- khong phai thanh tien do.
  show(f.barBg, true)
  -- Be ngang 0 lam frame hong; an han di thay vi dat kich thuoc 0.
  show(f.barFill, p > 0.01)
  if p > 0.01 then BlzFrameSetSize(f.barFill, full * p, 0.010) end

  BlzFrameSetText(f.ghiChu, CFG.C_GREY .. (d.ghiChu or "") .. CFG.C_END)

  show(f.btn, d.nut ~= nil)
  if d.nut ~= nil then
    BlzFrameSetText(f.btnTxt, (d.batNut ~= false) and d.nut
                              or (CFG.C_GREY .. d.nut .. CFG.C_END))
    setEnabled(f.btn, d.batNut ~= false)
  end
end

local function refresh(pid)
  local st = stateOf(pid)
  if st.panel == nil then return end

  local tab = S.panel.tabs[st.tab]
  if tab == nil then return end

  -- Nhan the: the dang mo to vang, cac the khac xam.
  for i = 1, #S.panel.tabs do
    local t = st.tabBtn[i]
    if t ~= nil and t.txt ~= nil then
      local nm = (ROMAN[i] or i) .. ". " .. S.panel.tabs[i].ten
      BlzFrameSetText(t.txt,
        (i == st.tab and CFG.C_GOLD or CFG.C_GREY) .. nm .. CFG.C_END)
    end
  end

  if st.money ~= nil then
    local tien = {
      { API.t("panel_linhkhi"), API.getLinhKhi(pid), CFG.C_JADE },
      { API.t("panel_vang"),    API.getVang(pid),    CFG.C_GOLD },
      { API.t("panel_go"),      API.getGo(pid),      CFG.C_GOLD },
    }
    for i = 1, #tien do
      local m = st.money[i]
      if m ~= nil then
        BlzFrameSetText(m.nhan, CFG.C_GREY .. tien[i][1] .. CFG.C_END)
        BlzFrameSetText(m.so,   tien[i][3] .. API.num(tien[i][2]) .. CFG.C_END)
      end
    end
  end

  local isList = (tab.kind ~= "focus")
  for i = 1, MAX_ITEMS do
    local w = st.item[i]
    if w ~= nil and not isList then
      show(w.bg, false); show(w.icon, false); show(w.name, false)
      show(w.state, false); show(w.sub, false); show(w.btn, false)
    end
  end
  if st.focus ~= nil then show(st.focus.root, not isList) end
  if not isList then show(st.empty, false) end

  if isList then refreshList(st, pid, tab) else refreshFocus(st, pid, tab) end
end

local function hide(pid)
  local st = stateOf(pid)
  if st.panel ~= nil then BlzFrameSetVisible(st.panel, false) end
  st.shown = false
end

-- ---------- Dung bang ----------

local function build(pid)
  local st = stateOf(pid)
  if st.panel ~= nil then return true end

  local parent = BlzGetOriginFrame(ORIGIN_FRAME_GAME_UI, 0)
  if parent == nil then return false end

  local P, W = PAD(), CFG.PANEL_W
  local bg, how = API.backdrop(CFG.PANEL_BACKDROP, parent, pid, CFG.FRAME_BG)
  st.panel = bg
  if st.panel == nil then return false end
  BlzFrameSetAbsPoint(st.panel, FRAMEPOINT_CENTER, CFG.PANEL_X, CFG.PANEL_Y)
  BlzFrameSetSize(st.panel, W, panelH())

  -- Mot dong chu neo TRAI (hoac PHAI) vao mot o co be ngang THAT.
  -- Khong dat kich thuoc thi Warcraft can giua chu quanh diem neo va
  -- chu dai tran deu hai ben -- do la loi "chu de len cot ben canh"
  -- cua ban truoc.
  local function text(name, parentF, dx, dy, w, scale, phai, h)
    local t = BlzCreateFrameByType("TEXT", name, parentF, "", pid)
    if t == nil then return nil end
    local s = scale or 1.0
    -- CHIA cho ti le phong -- CA TOA DO lan kich thuoc.
    --
    -- Do duoc tu anh chup: BlzFrameSetScale(f, s) khong chi phong hinh
    -- cua f, no phong luon KHOANG CACH tu f toi diem neo cua cha. Mot
    -- frame dat cach cha (dx, dy) voi ti le s se duoc ve o (dx*s, dy*s).
    --
    -- Ban truoc chi bu kich thuoc, nen moi dong chu co ti le khac 1.0
    -- deu bi keo ve goc tren-trai cua cha, va keo cang nhieu khi cang xa
    -- goc. Do la ly do DUY NHAT khien ca bon the vo bo cuc cung mot lan:
    --   dong tien (0.85) -> nhan cot 2 de len so cot 1: "0Insight"
    --   mo ta muc (0.85) -> keo len ngang hang TEN va trat vao icon
    --   ten muc   (1.05) -> day sang phai, roi khoi cot cua no
    --
    -- Kiem lai bang phep cong: cot 3 dang le o 0.3653, do duoc 0.3653 x
    -- 0.85 = 0.3105 -- dung bang chenh lech nhin thay tren man hinh.
    BlzFrameSetPoint(t, FRAMEPOINT_TOPLEFT, parentF, FRAMEPOINT_TOPLEFT,
                     dx / s, -(dy / s))
    -- Truyen h = can GIUA trong mot o cao h, thay vi bam mep tren cua
    -- mot o cao LINE. Can theo mep tren thi phai doan chieu cao chu de
    -- biet tam no o dau -- va doan sai la lech vai pixel, dung cai lam
    -- dong "1/10" khong thang voi nut ben canh.
    BlzFrameSetSize(t, w / s, (h or LINE) / s)
    local doc = (h ~= nil and TEXT_JUSTIFY_MIDDLE ~= nil)
                and TEXT_JUSTIFY_MIDDLE or TEXT_JUSTIFY_TOP
    if BlzFrameSetTextAlignment ~= nil and TEXT_JUSTIFY_TOP ~= nil then
      BlzFrameSetTextAlignment(t, doc,
        phai and TEXT_JUSTIFY_RIGHT or TEXT_JUSTIFY_LEFT)
    end
    API.frameScale(t, scale)
    API.frameDead(t)   -- chu nam de len nut se NUOT cu bam
    return t
  end

  -- CHA la tham so, khong co dinh st.panel.
  --
  -- Truoc day ham nay va backdropFrame() luon gan vao st.panel, ke ca
  -- khi goi tu cum "focus". Ket qua: nut va thanh tien do la ANH EM cua
  -- f.root chu khong phai CON, nen tat f.root khong tat duoc chung --
  -- "BREAK THROUGH -> Qi Refining" hien tren CA BON the.
  local function button(name, label, dx, dy, w, h, parentF)
    parentF = parentF or st.panel
    local b = BlzCreateFrameByType("GLUEBUTTON", name, parentF,
                                   CFG.FRAME_BUTTON_TEMPLATE, pid)
    if b == nil then return nil end
    BlzFrameSetSize(b, w, h)
    BlzFrameSetPoint(b, FRAMEPOINT_TOPLEFT, parentF, FRAMEPOINT_TOPLEFT, dx, -dy)
    -- VIEN cua nut: HAI O MAU DAC LONG NHAU, khong mượn template.
    --
    -- O ngoai phu kin nut = duong vien. O trong thut vao moi be d = ruot.
    -- Ca hai la CON cua nut nen tu an/hien va tu di theo nut, va
    -- frameDead nen khong nuot cu bam. Tao TRUOC chu de chu nam tren.
    --
    -- Vi sao khong dung backdrop co san: xem CFG.PANEL_BTN_EDGE.
    local d = CFG.PANEL_BTN_BORDER or 0.0016
    local function o(ten, dx2, dy2, w2, h2, tex)
      local f = BlzCreateFrameByType("BACKDROP", ten, b, "", pid)
      if f == nil then return end
      BlzFrameSetSize(f, w2, h2)
      BlzFrameSetPoint(f, FRAMEPOINT_TOPLEFT, b, FRAMEPOINT_TOPLEFT, dx2, -dy2)
      BlzFrameSetTexture(f, tex, 0, true)
      API.frameDead(f)
    end
    o(name .. "Edge", 0.0, 0.0, w, h, CFG.PANEL_BTN_EDGE)
    o(name .. "Fill", d, d, w - 2 * d, h - 2 * d, CFG.PANEL_BTN_FILL)

    local t = BlzCreateFrameByType("TEXT", name .. "Txt", b, "", pid)
    if t ~= nil then
      BlzFrameSetPoint(t, FRAMEPOINT_CENTER, b, FRAMEPOINT_CENTER, 0, 0)
      BlzFrameSetText(t, label)
      API.frameDead(t)
    end
    BlzTriggerRegisterFrameEvent(S.panel.trig, b, FRAMEEVENT_CONTROL_CLICK)
    return { btn = b, txt = t }
  end

  local function backdropFrame(name, dx, dy, w, h, tex, parentF)
    parentF = parentF or st.panel
    local f = BlzCreateFrameByType("BACKDROP", name, parentF, "", pid)
    if f == nil then return nil end
    BlzFrameSetSize(f, w, h)
    BlzFrameSetPoint(f, FRAMEPOINT_TOPLEFT, parentF, FRAMEPOINT_TOPLEFT, dx, -dy)
    if tex ~= nil then BlzFrameSetTexture(f, tex, 0, true) end
    BlzFrameSetVisible(f, false)
    API.frameDead(f)
    return f
  end

  -- Hang the
  local n  = #S.panel.tabs
  local tw = (W - 2 * P - (n - 1) * GAP) / n
  for i = 1, n do
    st.tabBtn[i] = button("CharTab" .. i, S.panel.tabs[i].ten,
                          P + (i - 1) * (tw + GAP), tabTop(), tw, TAB_H)
  end

  -- Dong tien: BA COT rong bang nhau, nhan can TRAI, so can PHAI.
  --
  -- Ban truoc nhet ca ba cap vao MOT frame chu, ngan nhau bang bon dau
  -- cach. Chu Warcraft khong deu nen bon dau cach khong ra mot be ngang
  -- co dinh: ba cap khong bao gio thang hang, va moi lan so doi do dai
  -- thi hai cap sau truot sang ngang. Nhin la thay lech, va lech khac
  -- nhau moi lan mo bang.
  --
  -- Cot co diem dau CO DINH thi khong con gi truot duoc.
  local moneyY = tabTop() + TAB_H + GAP
                 + (HEAD_H - LINE * CFG.PANEL_SCALE_SUB) * 0.5
  -- Ba cot tien chi chiem 78% be ngang; 22% con lai de chu thich ESC.
  --
  -- Chu thich KHONG dat duoc o hang the: nam nut da chia kin be ngang
  -- roi, dat o goc phai la de thang len "V. Shop".
  local hintW  = (W - 2 * P) * 0.22
  local colW   = (W - 2 * P - hintW) / 3
  st.money = {}
  for i = 1, 3 do
    local x = P + (i - 1) * colW
    st.money[i] = {
      nhan = text("CharMoneyL" .. i, st.panel, x, moneyY, colW * 0.58,
                  CFG.PANEL_SCALE_SUB, false),
      so   = text("CharMoneyV" .. i, st.panel, x + colW * 0.58, moneyY,
                  colW * 0.42 - 0.008, CFG.PANEL_SCALE_SUB, true),
    }
  end

  -- Chu nho cuoi dong tien, KHONG phai nut: chi cho biet bam gi de dong.
  -- text() da goi API.frameDead nen no khong nuot cu bam nao.
  st.hint = text("CharHint", st.panel, W - P - hintW, moneyY, hintW,
                 CFG.PANEL_SCALE_SUB, true)
  if st.hint ~= nil then
    BlzFrameSetText(st.hint, CFG.C_GREY ..
      ((CFG.PANEL_KEY == nil) and API.t("panel_close_esc")
                               or API.t("panel_close", CFG.PANEL_KEY)) ..
      CFG.C_END)
  end

  local top = bodyTop()

  -- ----- Than kieu "list": MAX_ITEMS muc dung san -----
  for i = 1, MAX_ITEMS do
    local y  = top + (i - 1) * ROW()
    local xt = P + ICON() + 0.008
    local w  = textW()

    local it = {}
    it.bg    = backdropFrame("CharBg" .. i, P, y, W - 2 * P, ROW() - 0.004,
                             CFG.PANEL_GRID_TEX)
    it.icon  = backdropFrame("CharIcon" .. i, P, y + 0.006, ICON(), ICON(), nil)
    it.name  = text("CharName" .. i,  st.panel, xt, y + 0.006, w * 0.62,
                    CFG.PANEL_SCALE_NAME, false)
    -- Dong bac ("1/10"): o cao TRON DONG, can giua theo chieu doc. Nut
    -- ben phai cung can giua dong, nen hai cai chung mot tam -- khong
    -- con phu thuoc chieu cao chu.
    it.state = text("CharState" .. i, st.panel, xt + w * 0.62, y,
                    w * 0.38, CFG.PANEL_SCALE_NAME, true, ROW())
    it.sub   = text("CharSub" .. i,   st.panel, xt, y + 0.006 + LINE + 0.004, w,
                    CFG.PANEL_SCALE_SUB, false)

    local b = button("CharBtn" .. i, "", W - P - BTN_W(),
                     y + (ROW() - BTN_H()) * 0.5, BTN_W(), BTN_H())
    if b ~= nil then it.btn, it.btnTxt = b.btn, b.txt end

    show(it.name, false); show(it.state, false); show(it.sub, false)
    show(it.btn, false)
    st.item[i] = it
  end

  st.empty = text("CharEmpty", st.panel, P, top + 0.010, W - 2 * P,
                  CFG.PANEL_SCALE_NAME, false)
  show(st.empty, false)

  -- ----- Than kieu "focus" -----
  do
    local f = { dong = {} }
    local fh = bodyH()

    -- Frame goc CHI de bat/tat ca cum bang MOT loi goi -- no khong ve gi.
    --
    -- Ban truoc no la BACKDROP phu PANEL_GRID_TEX. PANEL_GRID_TEX la mot
    -- o mau DAC (TeamColor27, den): dung cho mot dong cao 0.044 thi ra
    -- vach ke, dung cho ca than bang thi ra MOT TAM DEN to bang nua
    -- khung. Ke vach la viec cua tung dong, khong phai cua ca khoi.
    --
    -- "FRAME" la kieu frame rong: co toa do, co con, khong co hinh. No
    -- khong phai control nen khong goi frameDead -- khong co hinh thi
    -- cung khong nuot duoc cu bam.
    f.root = BlzCreateFrameByType("FRAME", "CharFocus", st.panel, "", pid)
    if f.root == nil then
      -- Lui ve kieu cu: xau nhung con hien duoc. Mot the TRONG te hon
      -- mot the co tam den.
      API.trace("panel: khong tao duoc FRAME rong -- lui ve BACKDROP")
      f.root = BlzCreateFrameByType("BACKDROP", "CharFocus", st.panel, "", pid)
      if f.root ~= nil then
        BlzFrameSetTexture(f.root, CFG.PANEL_GRID_TEX, 0, true)
        API.frameDead(f.root)
      end
    end
    if f.root ~= nil then
      BlzFrameSetSize(f.root, W - 2 * P, fh)
      BlzFrameSetPoint(f.root, FRAMEPOINT_TOPLEFT, st.panel,
                       FRAMEPOINT_TOPLEFT, P, -top)
      show(f.root, false)

      local fw = W - 2 * P
      f.tieuDe = text("CharFTitle", f.root, 0.004, 0.006, fw * 0.55,
                      CFG.PANEL_SCALE_HEAD, false)
      f.phu    = text("CharFSub",   f.root, fw * 0.45, 0.008, fw * 0.55 - 0.004,
                      CFG.PANEL_SCALE_NAME, true)

      -- Ba dong so lieu, moi dong mot vach ke rieng -- cung cach the
      -- kieu "list" ke dong chan, de hai kieu than trong nhu mot bang.
      for i = 1, 3 do
        local y = 0.044 + (i - 1) * 0.024
        f.dong[i] = {
          ke    = (CFG.PANEL_GRID and i % 2 == 0)
                  and backdropFrame("CharFRow" .. i, 0.0, y - 0.004, fw, 0.022,
                                    CFG.PANEL_GRID_TEX, f.root) or nil,
          nhan  = text("CharFL" .. i, f.root, 0.010, y, fw * 0.34,
                       CFG.PANEL_SCALE_NAME, false),
          truoc = text("CharFA" .. i, f.root, fw * 0.36, y, fw * 0.22,
                       CFG.PANEL_SCALE_NAME, true),
          sau   = text("CharFB" .. i, f.root, fw * 0.60, y, fw * 0.38 - 0.010,
                       CFG.PANEL_SCALE_NAME, false),
        }
      end

      -- Thanh tien do + nut + ghi chu dat theo DAY cua than bang, khong
      -- theo dinh. Than bang cao bang the dai nhat (7 ky nang = 0.336),
      -- nen neo theo dinh thi ca cum dinh o nua tren va nua duoi bo
      -- trong -- do la cai "vo bo cuc" cua the I.
      --
      -- Toa do theo F.ROOT, khong theo st.panel. f.root nam o (P, -top)
      -- nen diem panel (P + x, top + y) chinh la diem root (x, y).
      local noteY = fh - 0.022
      local btnH  = BTN_H() + 0.006
      local btnY  = noteY - btnH - 0.010
      local barY  = btnY - 0.020

      f.barBg = backdropFrame("CharFBarBg", 0.0, barY, fw, 0.010,
                              CFG.PANEL_BAR_BG, f.root)
      f.barFill = backdropFrame("CharFBarFill", 0.0, barY, fw * 0.5, 0.010,
                                CFG.PANEL_BAR_FILL, f.root)

      local b = button("CharFBtn", "", fw * 0.10, btnY,
                       fw * 0.80, btnH, f.root)
      if b ~= nil then f.btn, f.btnTxt = b.btn, b.txt end

      f.ghiChu = text("CharFNote", f.root, 0.010, noteY, fw - 0.020,
                      CFG.PANEL_SCALE_SUB, false)
    end
    st.focus = f
  end

  BlzFrameSetVisible(st.panel, false)
  API.trace("panel: dung bang pid " .. pid .. " (" .. n .. " the, " ..
            MAX_ITEMS .. " dong, nen = " .. tostring(how) .. ")")
  return true
end

local function setShown(pid, want)
  if not framesAvailable() then
    API.msg(pid, CFG.C_RED .. "Khong ve duoc bang -- dung lenh chat." .. CFG.C_END)
    return
  end
  if not build(pid) then return end

  local st = stateOf(pid)
  st.shown = want
  refresh(pid)

  BlzFrameSetVisible(st.panel, false)
  if GetLocalPlayer() == Player(pid) then
    BlzFrameSetVisible(st.panel, st.shown)
  end
end

local function toggle(pid)
  setShown(pid, not stateOf(pid).shown)
end

local function openTab(pid, index)
  local st = stateOf(pid)
  if S.panel.tabs[index] == nil then return end
  st.tab = index
  setShown(pid, true)
end

-- ---------- Su kien ----------

-- Tra ban phim ve cho game sau moi cu bam.
--
-- LOI THAT: bam vao mot the roi bam ESC thi bang khong dong. Bam ra
-- ngoai mot cai roi ESC thi lai duoc.
--
-- Nguyen nhan: GLUEBUTTON GIU TIEU DIEM ban phim sau khi duoc bam. Frame
-- dang giu tieu diem nuot het phim, nen ca
-- BlzTriggerRegisterPlayerKeyEvent lan EVENT_PLAYER_END_CINEMATIC deu
-- khong no. Bam ra cho khac la mat tieu diem, nen ESC lai chay -- dung
-- kieu "luc duoc luc khong" ma anh chup khong the hien.
--
-- Tat roi bat lai la cach tra tieu diem o ban 1.31. Nut nao gui duoc cu
-- bam thi von da dang bat, nen bat lai luon dung trang thai; va cac
-- duong ben duoi deu goi refresh() ngay sau do, refresh dat lai trang
-- thai bat/tat theo du tien hay khong.
local function nhaFocus(f)
  if f == nil or BlzFrameSetEnable == nil then return end
  BlzFrameSetEnable(f, false)
  BlzFrameSetEnable(f, true)
end

local function onClick()
  local f = BlzGetTriggerFrame()
  if f == nil then return end
  nhaFocus(f)

  for pid, st in pairs(S.panel.byPid) do
    if GetLocalPlayer() == Player(pid) then
      local tab = S.panel.tabs[st.tab]

      if st.focus ~= nil and f == st.focus.btn then
        if tab ~= nil and tab.action ~= nil then tab.action(pid) end
        return
      end

      for i = 1, #st.tabBtn do
        if st.tabBtn[i] ~= nil and f == st.tabBtn[i].btn then
          st.tab = i
          refresh(pid)
          return
        end
      end

      for i = 1, MAX_ITEMS do
        local w = st.item[i]
        if w ~= nil and f == w.btn then
          if tab ~= nil and tab.itemAction ~= nil then tab.itemAction(pid, i) end
          return
        end
      end
    end
  end
end

-- Phim E. Su kien phim la cuc bo, nhung mo/dong bang cung la UI thuan
-- nen khong can dong bo.
-- Phim mo bang. Doi E -> R: E da thanh phim tat cua Bat Hoai (ky nang
-- chu dong thu ba), va mot phim khong the vua bam skill vua mo bang.
-- ESC dong bang. HAI duong dang ky, khong mot:
--
--   OSKEY_ESCAPE                  co tu 1.31, nhung la duong moi
--   EVENT_PLAYER_END_CINEMATIC    duong co dien: Warcraft ban su kien
--                                 nay moi lan ai do bam ESC
--
-- Dang ky ca hai roi de hide() tu chan lan thu hai -- re hon nhieu so
-- voi viec doan xem ban nay nhan duong nao, va do chinh la kieu doan da
-- lam hong he dong bo mot lan (ADR 0012).
local function bindEsc()
  local n = 0
  local t = CreateTrigger()

  local esc = _G["OSKEY_ESCAPE"]
  if BlzTriggerRegisterPlayerKeyEvent ~= nil and esc ~= nil then
    for i = 1, #S.pids do
      BlzTriggerRegisterPlayerKeyEvent(t, Player(S.pids[i]), esc, 0, true)
    end
    n = n + 1
  end

  if TriggerRegisterPlayerEvent ~= nil and EVENT_PLAYER_END_CINEMATIC ~= nil then
    for i = 1, #S.pids do
      TriggerRegisterPlayerEvent(t, Player(S.pids[i]), EVENT_PLAYER_END_CINEMATIC)
    end
    n = n + 1
  end

  -- Khong con phim chu thi ESC phai BAT/TAT, neu khong thi khong con
  -- duong nao MO bang ngoai lenh chat "-c".
  --
  -- Con phim chu thi ESC chi TAT: luc do bam ESC de huy chon quan ma
  -- bang bat len la mot cai bay nho dat dung cho ai cung bam theo phan
  -- xa.
  local batTat = (CFG.PANEL_KEY == nil)

  -- CHAN LAN NO THU HAI.
  --
  -- Hai duong dang ky o tren nam tren CUNG MOT trigger, nen mot lan bam
  -- ESC no HAI lan. Hoi ESC con la chi-tat thi vo hai: lan hai goi
  -- hide() tren mot bang da dong. Tu luc no thanh bat/tat thi lan hai
  -- HUY lan mot -- bang mo ra roi dong ngay trong cung mot khung hinh,
  -- nhin y het nhu ESC khong lam gi ca.
  --
  -- Do do duoc: file vet ghi "ESC dang ky qua 2 duong".
  --
  -- Van giu ca hai duong dang ky chu khong bo bot mot: khong ai biet
  -- ban sau con du ca hai khong, va chan trung o day re hon la doan.
  local khoa = {}
  TriggerAddAction(t, function()
    local pid = GetPlayerId(GetTriggerPlayer())
    if khoa[pid] then return end
    khoa[pid] = true
    API.after(CFG.PANEL_ESC_KHOA or 0.25, function() khoa[pid] = nil end)

    if stateOf(pid).shown then hide(pid)
    elseif batTat then toggle(pid) end
  end)

  API.trace("panel: ESC dang ky qua " .. n .. " duong")
  return n > 0
end

local function bindKey()
  local ten = CFG.PANEL_KEY
  if ten == nil then
    API.trace("panel: khong gan phim chu (CFG.PANEL_KEY = nil), chi ESC")
    return false
  end
  local key = _G["OSKEY_" .. ten]
  if BlzTriggerRegisterPlayerKeyEvent == nil or key == nil then
    API.trace("panel: KHONG co BlzTriggerRegisterPlayerKeyEvent/OSKEY_" ..
              ten .. " -- chi con -c")
    return false
  end
  local t = CreateTrigger()
  for i = 1, #S.pids do
    BlzTriggerRegisterPlayerKeyEvent(t, Player(S.pids[i]), key, 0, true)
  end
  TriggerAddAction(t, function() toggle(GetPlayerId(GetTriggerPlayer())) end)
  API.trace("panel: da gan phim " .. ten)
  return true
end

local function startPanel()
  -- So dong dung san = the dai nhat. Tinh o day chu khong go tay: them
  -- mot he 9 muc thi bang tu rong ra, khong phai nho sua hang so.
  for i = 1, #S.panel.tabs do
    local t = S.panel.tabs[i]
    if t.soMuc ~= nil and t.soMuc > MAX_ITEMS then MAX_ITEMS = t.soMuc end
  end

  S.panel.trig = CreateTrigger()
  TriggerAddAction(S.panel.trig, onClick)
  S.keyBound = bindKey()
  bindEsc()
  API.trace("panel: san sang, " .. #S.panel.tabs .. " the, " .. MAX_ITEMS ..
            " dong, phimE=" .. tostring(S.keyBound))
end

-- Ve lai bang cua MOI nguoi. Khong goi refresh(nil) duoc: stateOf se
-- gan S.panel.byPid[nil] va Lua no loi "table index is nil".
local function refreshAll()
  for i = 1, #S.pids do refresh(S.pids[i]) end
end

API.panelRefreshAll  = refreshAll
API.panelAddTab      = addTab
API.panelPlaceholder = placeholderTab
API.panelRefresh     = refresh
API.panelToggle      = toggle
API.panelOpenTab     = openTab
API.startPanel       = startPanel
end
--#endregion 4_giao_dien/1_panel.lua

--#region 4_giao_dien/2_heroframe.lua
do
-- ============================================================
--  2_heroframe.lua  --  Bang chon hero, mot cot doc
--
--  Dung khi CFG.HERO_PICK_MODE = "frame". Moi hero MOT DONG rong bang
--  ca bang: icon ben trai, ten + vai o tren, ba gach mo ta o duoi.
--
--  VI SAO DOC CHU KHONG PHAI BA THE NGANG.
--
--  Frame chu cua Warcraft KHONG tu xuong dong, va text frame khong dat
--  kich thuoc thi bi can giua quanh diem neo. The ngang rong 0.17 nghia
--  la moi dong mo ta dai hon chung ay tran ra hai ben va de len chu cua
--  the ben canh -- chu cang dai vung de cang rong, nen loi luc co luc
--  khong. No con ep 'mota' phai ngan 3-4 tu, mot rang buoc sinh ra tu
--  han che ky thuat chu khong tu thiet ke.
--
--  Dong rong bang ca bang thi chu luon co cho. Ba cho khac cung sua
--  theo: nen dung template co vien that thay cho o mau phang, chu co
--  ba co de co phan cap, va nhip doc SUY RA tu co icon/co chu chu khong
--  go tay.
--
--  Cung hai rang buoc nhu 3_skillframe, va vi cung mot ly do:
--
--  1. Su kien bam frame CHI no tren may nguoi bam. Nen bam khong doi
--     trang thai -- no gui mot mau tin qua API.syncSend (3_sync.lua),
--     va moi may goi API.applyHeroPick khi nhan duoc. Lech may la bi da
--     ra khoi tran, khong phai loi hien thi.
--
--  2. Moi nguoi mot bang rieng. Lenh/timer chay tren moi may, nen mot
--     bang dung chung se bi nguoi thu hai huy mat.
--
--  Thieu native frame thi tu lui ve popup chu, khong sap.
--
--  Nho: goi ham cua file khac phai qua API.
-- ============================================================

local FRAME_OK = nil

local function checkNatives(list)
  local missing = {}
  for i = 1, #list do
    if list[i][2] == nil then missing[#missing + 1] = list[i][1] end
  end
  return missing
end

local function framesAvailable()
  if FRAME_OK ~= nil then return FRAME_OK end
  local missing = checkNatives({
    { "BlzGetOriginFrame",            BlzGetOriginFrame },
    { "BlzCreateFrameByType",         BlzCreateFrameByType },
    { "BlzFrameSetAbsPoint",          BlzFrameSetAbsPoint },
    { "BlzFrameSetPoint",             BlzFrameSetPoint },
    { "BlzFrameSetSize",              BlzFrameSetSize },
    { "BlzFrameSetTexture",           BlzFrameSetTexture },
    { "BlzFrameSetVisible",           BlzFrameSetVisible },
    { "BlzTriggerRegisterFrameEvent", BlzTriggerRegisterFrameEvent },
    { "BlzGetTriggerFrame",           BlzGetTriggerFrame },
    { "ORIGIN_FRAME_GAME_UI",         ORIGIN_FRAME_GAME_UI },
    { "FRAMEEVENT_CONTROL_CLICK",     FRAMEEVENT_CONTROL_CLICK },
    { "FRAMEPOINT_CENTER",            FRAMEPOINT_CENTER },
    { "FRAMEPOINT_TOP",               FRAMEPOINT_TOP },
    { "FRAMEPOINT_LEFT",              FRAMEPOINT_LEFT },
    { "FRAMEPOINT_TOPLEFT",           FRAMEPOINT_TOPLEFT },
  })
  FRAME_OK = (#missing == 0)
  if not FRAME_OK then
    API.trace("herocard: THIEU " .. table.concat(missing, " "))
  end
  return FRAME_OK
end

local function stateOf(pid)
  local hf = S.hframe
  if hf.byPid[pid] == nil then
    hf.byPid[pid] = { panel = nil, map = {} }
  end
  return hf.byPid[pid]
end

local function destroyPanel(pid)
  local st = stateOf(pid)
  if st.panel ~= nil and BlzDestroyFrame ~= nil then
    BlzDestroyFrame(st.panel)
  end
  st.panel = nil
  st.map = {}
end

local function hideFrame(pid)
  local st = stateOf(pid)
  if st.panel ~= nil and BlzFrameSetVisible ~= nil then
    BlzFrameSetVisible(st.panel, false)
  end
end

-- ---------- Hinh hoc ----------

-- Cao mot dong: SUY RA tu co icon va hai dong chu, khong go tay.
--
-- Truoc day chieu cao la mot hang so trong CFG con vi tri tung dong chu
-- la ba con so roi rac (y, y+0.018, y+0.040). Doi co chu mot cai la ca
-- ba lech het, va do dung la loi bang phim E da dinh mot lan.
local function rowH()
  local text = 2 * CFG.CARD_LINE + 0.006
  local h = (text > CFG.CARD_ICON) and text or CFG.CARD_ICON
  return h + 2 * CFG.CARD_PAD
end

-- Vien trang tri cua backdrop an mat mot phan mep trong. CARD_PAD 0.010
-- khong du, nen tieu de leo len dung duong vien vang.
local function titleTop()
  return CFG.CARD_BORDER + CFG.CARD_PAD
end

local function headH()
  return titleTop() + CFG.CARD_LINE * CFG.CARD_SCALE_TITLE + 0.008
end

-- ---------- Mot dong chu ----------

-- Neo TRAI vao mot o co be ngang THAT.
--
-- Phai dat be ngang: text frame khong co kich thuoc thi Warcraft can
-- giua no quanh diem neo, va chu dai thi tran deu ca hai ben. Co o roi
-- thi BlzFrameSetTextAlignment moi ep duoc ve mep trai.
local function textLine(pid, parent, name, x, y, w, scale, text)
  local f = BlzCreateFrameByType("TEXT", name, parent, "", pid)
  if f == nil then return nil end

  -- CHIA cho ti le phong, CA TOA DO lan kich thuoc -- cung mot bai hoc
  -- voi text() cua bang phim R: BlzFrameSetScale phong luon khoang cach
  -- tu frame toi diem neo cua cha, nen frame dat cach cha x se duoc ve o
  -- x * scale.
  local s = scale or 1.0
  BlzFrameSetPoint(f, FRAMEPOINT_TOPLEFT, parent, FRAMEPOINT_TOPLEFT,
                   x / s, -(y / s))
  BlzFrameSetSize(f, w / s, CFG.CARD_LINE / s)
  if BlzFrameSetTextAlignment ~= nil
     and TEXT_JUSTIFY_TOP ~= nil and TEXT_JUSTIFY_LEFT ~= nil then
    BlzFrameSetTextAlignment(f, TEXT_JUSTIFY_TOP, TEXT_JUSTIFY_LEFT)
  end
  API.frameScale(f, scale)
  BlzFrameSetText(f, text)
  API.frameDead(f)
  return f
end

-- ---------- Mot dong hero ----------
--
--   [icon]  Ten      Vai - Vai tro
--           manh 1  |  manh 2  |  DIEM YEU
local function buildRow(pid, parent, hero, dy)
  local row = BlzCreateFrameByType("GLUEBUTTON", "HeroRow", parent,
                                   CFG.CARD_BUTTON_TEMPLATE, pid)
  if row == nil then return nil end

  local P = CFG.CARD_PAD
  BlzFrameSetSize(row, CFG.CARD_W, rowH())
  BlzFrameSetPoint(row, FRAMEPOINT_TOP, parent, FRAMEPOINT_TOP, 0.0, -dy)

  if hero.icon ~= nil then
    local ic = BlzCreateFrameByType("BACKDROP", "HeroRowIcon", row, "", pid)
    if ic ~= nil then
      BlzFrameSetSize(ic, CFG.CARD_ICON, CFG.CARD_ICON)
      BlzFrameSetPoint(ic, FRAMEPOINT_LEFT, row, FRAMEPOINT_LEFT, P, 0.0)
      BlzFrameSetTexture(ic, hero.icon, 0, true)
      API.frameDead(ic)
    end
  end

  if BlzFrameSetText == nil then return row end

  local x = P + CFG.CARD_ICON + P
  local w = CFG.CARD_W - x - P

  -- Ten va vai nam tren CUNG mot frame. Gop chuoi thi khoi phai do be
  -- ngang cua ten de biet dat vai o dau -- ma do be ngang chu thi
  -- Warcraft khong co native nao lam duoc.
  local head = CFG.C_GOLD .. hero.name .. CFG.C_END
  if hero.role ~= nil then
    head = head .. "   " .. CFG.C_GREY .. hero.role .. CFG.C_END
  end
  textLine(pid, row, "HeroRowName", x, P, w, CFG.CARD_SCALE_NAME, head)

  -- Ba gach noi thanh MOT dong. Gach cuoi luon la diem yeu nen to do --
  -- do la thu duy nhat lam nguoi choi phai nghi xem nen chon con nao.
  local list = (API.lang() == "en" and hero.mota_en) or hero.mota
  if list ~= nil and #list > 0 then
    local parts = {}
    for i = 1, #list do
      local mau = (i == #list) and CFG.C_RED or CFG.C_JADE
      parts[i] = mau .. list[i] .. CFG.C_END
    end
    textLine(pid, row, "HeroRowDesc", x, P + CFG.CARD_LINE + 0.006, w,
             CFG.CARD_SCALE_DESC,
             table.concat(parts, CFG.C_GREY .. "  |  " .. CFG.C_END))
  end

  return row
end

-- ---------- Ca bang ----------

-- Chay tren MOI may. Bang dung giong het nhau khap noi; chi khac o chuyen
-- hien cho ai -- do la UI, khong phai trang thai game, nen dung
-- GetLocalPlayer o day la an toan.
local function buildPanel(pid, list)
  local st = stateOf(pid)
  destroyPanel(pid)

  local parent = BlzGetOriginFrame(ORIGIN_FRAME_GAME_UI, 0)
  if parent == nil then return false end

  local n  = #list
  local P  = CFG.CARD_PAD
  local H  = rowH()
  local hd = headH()

  local bg, how = API.backdrop(CFG.CARD_BACKDROP, parent, pid, CFG.FRAME_BG)
  st.panel = bg
  if st.panel == nil then return false end

  BlzFrameSetAbsPoint(st.panel, FRAMEPOINT_CENTER, CFG.CARD_X, CFG.CARD_Y)
  BlzFrameSetSize(st.panel, CFG.CARD_W + 2 * P,
                  hd + n * H + (n - 1) * CFG.CARD_GAP + P)

  if BlzFrameSetText ~= nil then
    local title = BlzCreateFrameByType("TEXT", "HeroPanelTitle", st.panel, "", pid)
    if title ~= nil then
      -- Neo TRAI vao mot o co be ngang THAT roi can giua bang
      -- SetTextAlignment -- dung ly do da ghi o textLine(). Neo bang
      -- FRAMEPOINT_TOP ma khong dat kich thuoc thi Warcraft can frame
      -- quanh diem neo, va frameScale lai phong quanh TAM, nen mep tren
      -- troi len tren diem neo. Cong voi vien backdrop la chu de len
      -- duong vien vang.
      -- CHIA cho ti le phong, CA TOA DO lan kich thuoc.
      --
      -- BlzFrameSetScale phong luon khoang cach toi diem neo cua cha, va
      -- phong ca kich thuoc. Muon o chu nam dung [P, CARD_W - P] thi
      -- phai chia ca hai: neo P/s de duoc ve o P, rong (CARD_W-2P)/s de
      -- duoc ve rong CARD_W-2P. Luc do chu can GIUA moi roi dung
      -- CARD_W/2.
      --
      -- Ban truoc chi chia be ngang: o thanh [P, P + CARD_W] -- tran ra
      -- ngoai the ben phai dung P, nen chu can giua lech phai P/2.
      local s = CFG.CARD_SCALE_TITLE
      BlzFrameSetPoint(title, FRAMEPOINT_TOPLEFT, st.panel, FRAMEPOINT_TOPLEFT,
                       P / s, -(titleTop() / s))
      BlzFrameSetSize(title, (CFG.CARD_W - 2 * P) / s, CFG.CARD_LINE / s)
      if BlzFrameSetTextAlignment ~= nil
         and TEXT_JUSTIFY_TOP ~= nil and TEXT_JUSTIFY_CENTER ~= nil then
        BlzFrameSetTextAlignment(title, TEXT_JUSTIFY_TOP, TEXT_JUSTIFY_CENTER)
      end
      API.frameScale(title, CFG.CARD_SCALE_TITLE)
      BlzFrameSetText(title, CFG.C_GOLD .. API.t("pick_title") .. CFG.C_END)
      API.frameDead(title)
    end
  end

  st.map = {}
  local made = 0
  for i = 1, n do
    local row = buildRow(pid, st.panel, list[i], hd + (i - 1) * (H + CFG.CARD_GAP))
    if row ~= nil then
      BlzTriggerRegisterFrameEvent(S.hframe.trig, row, FRAMEEVENT_CONTROL_CLICK)
      -- Ghi SO THU TU trong CFG.HEROES, khong phai id: kenh dong bo chi
      -- tai duoc so nho. Xem src/1_nen/3_sync.lua.
      st.map[row] = { pid = pid, idx = API.heroIndex(list[i].id) }
      made = made + 1
    end
  end

  API.trace("herocard: pid " .. pid .. " -- tao " .. made .. "/" .. n ..
            " dong, nen = " .. tostring(how))
  if made == 0 then
    API.msg(nil, CFG.C_RED .. "herocard: khong tao duoc dong nao -- thu doi " ..
      "CFG.CARD_BUTTON_TEMPLATE." .. CFG.C_END)
    destroyPanel(pid)
    return false
  end

  BlzFrameSetVisible(st.panel, false)
  if GetLocalPlayer() == Player(pid) then
    BlzFrameSetVisible(st.panel, true)
  end
  return true
end

local function showFrame(pid)
  if not framesAvailable() then
    API.msg(pid, CFG.C_GOLD .. "Bang chon hero khong ve duoc -- lui ve popup chu."
      .. CFG.C_END)
    return API.showPicker(pid)
  end

  local d = S.p[pid]
  if d == nil or not d.active then return false end
  if CFG.HERO_MAX_PER_PLAYER > 0 and d.heroCount >= CFG.HERO_MAX_PER_PLAYER then
    hideFrame(pid)
    return false
  end

  local list = API.heroesAvailable()
  if #list == 0 then
    hideFrame(pid)
    API.msg(pid, CFG.C_RED .. "Khong con hero nao de chon." .. CFG.C_END)
    return false
  end

  return buildPanel(pid, list)
end

-- CHI chay tren may nguoi bam.
local function onCardClick()
  local f = BlzGetTriggerFrame()
  if f == nil then return end

  local hit = nil
  for _, st in pairs(S.hframe.byPid) do
    if st.map[f] ~= nil then hit = st.map[f]; break end
  end
  if hit == nil then return end
  if hit.idx == nil then return end
  if GetLocalPlayer() ~= Player(hit.pid) then return end

  -- Khong doi gi o day. Chi bao cho moi may biet.
  API.syncSend(hit.pid, CFG.OP_HERO, hit.idx)
end

-- Chay tren MOI may, tu kenh dong bo. Day la cho duy nhat duoc phep doi
-- trang thai game.
local function onPicked(pid, idx)
  local h = CFG.HEROES[idx]
  if h == nil then return end
  API.applyHeroPick(pid, h.id)
end

local function startHeroFrame()
  S.hframe = { trig = nil, syncTrig = nil, byPid = {} }
  if CFG.HERO_PICK_MODE ~= "frame" then return end
  if not framesAvailable() then
    API.msg(nil, CFG.C_RED .. "Khong ve duoc bang chon hero tren ban nay -- " ..
      "se dung popup chu." .. CFG.C_END)
    return
  end

  S.hframe.trig = CreateTrigger()
  TriggerAddAction(S.hframe.trig, onCardClick)

  API.syncOn(CFG.OP_HERO, onPicked)
  API.trace("herocard: trigger san sang, dong bo=" .. API.syncMode())
end

API.showHeroFrame  = showFrame
API.hideHeroFrame  = hideFrame
API.startHeroFrame = startHeroFrame
end
--#endregion 4_giao_dien/2_heroframe.lua

--#region 4_giao_dien/3_skillframe.lua
do
-- ============================================================
--  3_skillframe.lua  --  Giao dien chon ky nang tu ve
--
--  Dung khi CFG.SKILL_MODE = "frame". Ve bang icon bang
--  BlzCreateFrameByType -- khong can file .fdf/.toc, khong phai import
--  gi trong World Editor.
--
--  HAI DIEU QUYET DINH TOAN BO THIET KE FILE NAY:
--
--  1. Frame la giao dien THUAN CLIENT, nam ngoai mo phong. Su kien bam
--     CHI no tren may nguoi bam. Doi trang thai game ngay trong do thi
--     may do re nhanh khoi hai may kia -- Warcraft III chay lockstep,
--     lech la da nguoi choi ra.
--
--     Nen: bam -> chi gui mot mau tin qua API.syncSend. Moi may, ke ca
--     may nguoi bam, nhan duoc roi MOI doi trang thai. Cung mot thay
--     doi, cung mot thu tu, khong lech. Kenh do 3_sync.lua lo.
--
--     (Popup dialog o 07_heropick khong dinh loi nay: dialog la UI cap
--     game, cu bam di qua duong lenh dong bo san.)
--
--  2. Moi nguoi choi phai co BANG RIENG. Lenh chat chay tren moi may,
--     nen mot bang dung chung se bi nguoi thu hai huy mat khi ho cung
--     go -sp.
--
--  Nho: goi ham cua file khac phai qua API.
-- ============================================================

local FRAME_OK = nil   -- nil = chua kiem tra

local function checkNatives(list)
  local missing = {}
  for i = 1, #list do
    if list[i][2] == nil then missing[#missing + 1] = list[i][1] end
  end
  return missing
end

local function framesAvailable()
  if FRAME_OK ~= nil then return FRAME_OK end
  local missing = checkNatives({
    { "BlzGetOriginFrame",           BlzGetOriginFrame },
    { "BlzCreateFrameByType",        BlzCreateFrameByType },
    { "BlzFrameSetAbsPoint",         BlzFrameSetAbsPoint },
    { "BlzFrameSetPoint",            BlzFrameSetPoint },
    { "BlzFrameSetAllPoints",        BlzFrameSetAllPoints },
    { "BlzFrameSetSize",             BlzFrameSetSize },
    { "BlzFrameSetTexture",          BlzFrameSetTexture },
    { "BlzFrameSetVisible",          BlzFrameSetVisible },
    { "BlzTriggerRegisterFrameEvent", BlzTriggerRegisterFrameEvent },
    { "BlzGetTriggerFrame",          BlzGetTriggerFrame },
    { "ORIGIN_FRAME_GAME_UI",        ORIGIN_FRAME_GAME_UI },
    { "FRAMEEVENT_CONTROL_CLICK",    FRAMEEVENT_CONTROL_CLICK },
    { "FRAMEPOINT_CENTER",           FRAMEPOINT_CENTER },
    { "FRAMEPOINT_LEFT",             FRAMEPOINT_LEFT },
  })
  FRAME_OK = (#missing == 0)
  if FRAME_OK then
    API.trace("frame: du native")
  else
    API.trace("frame: THIEU " .. table.concat(missing, " "))
    API.msg(nil, CFG.C_RED .. "Giao dien tu ve khong chay duoc -- thieu: " ..
      table.concat(missing, ", ") .. CFG.C_END)
  end
  return FRAME_OK
end

local function iconOf(choice)
  if choice.icon ~= nil then return choice.icon end
  if BlzGetAbilityIcon ~= nil then
    local p = BlzGetAbilityIcon(choice.id)
    if p ~= nil and p ~= "" then return p end
  end
  return nil
end

-- ---------- Bang rieng tung nguoi ----------

local function slotOf(pid)
  local sf = S.sframe
  if sf.byPid[pid] == nil then
    sf.byPid[pid] = { panel = nil, map = {}, slot = nil }
  end
  return sf.byPid[pid]
end

local function destroyPanel(pid)
  local st = slotOf(pid)
  if st.panel ~= nil and BlzDestroyFrame ~= nil then
    BlzDestroyFrame(st.panel)
  end
  st.panel = nil
  st.map = {}
end

local function hidePanel(pid)
  local st = slotOf(pid)
  if st.panel ~= nil then BlzFrameSetVisible(st.panel, false) end
end

local function nextSlotIndex(pid)
  local d = S.p[pid]
  local slots = API.slotsFor(pid)
  for i = 1, #slots do
    if d.slots[i] == nil then return i, slots end
  end
  return nil, slots
end

-- Chay tren MOI may. Bang duoc tao giong het nhau o khap noi; chi khac
-- o chuyen hien cho ai -- va do la UI, khong phai trang thai game, nen
-- dung GetLocalPlayer o day la an toan.
local function buildPanel(pid, slotIndex)
  local st = slotOf(pid)
  local slot = API.slotsFor(pid)[slotIndex]
  destroyPanel(pid)

  local parent = BlzGetOriginFrame(ORIGIN_FRAME_GAME_UI, 0)
  if parent == nil then
    API.msg(nil, CFG.C_RED .. "frame: khong lay duoc GAME_UI." .. CFG.C_END)
    return false
  end

  st.panel = BlzCreateFrameByType("BACKDROP", "SkillPanel", parent, "", pid)
  if st.panel == nil then
    API.msg(nil, CFG.C_RED .. "frame: BlzCreateFrameByType tra ve nil." .. CFG.C_END)
    return false
  end
  BlzFrameSetAbsPoint(st.panel, FRAMEPOINT_CENTER, CFG.FRAME_X, CFG.FRAME_Y)
  BlzFrameSetSize(st.panel, CFG.FRAME_W, CFG.FRAME_H)
  BlzFrameSetTexture(st.panel, CFG.FRAME_BG, 0, true)

  if BlzFrameSetText ~= nil then
    local title = BlzCreateFrameByType("TEXT", "SkillTitle", st.panel, "", pid)
    if title ~= nil then
      BlzFrameSetPoint(title, FRAMEPOINT_CENTER, st.panel, FRAMEPOINT_CENTER,
                       0.0, CFG.FRAME_H * 0.36)
      BlzFrameSetText(title, slot.name or ("Slot " .. slotIndex))
      API.frameDead(title)
    end
  end

  local n = #slot.choices
  local step = CFG.FRAME_ICON + CFG.FRAME_GAP
  local startX = (CFG.FRAME_W - (n * CFG.FRAME_ICON + (n - 1) * CFG.FRAME_GAP)) * 0.5

  st.map = {}
  local made = 0
  for i = 1, n do
    local choice = slot.choices[i]
    local btn = BlzCreateFrameByType("GLUEBUTTON", "SkillBtn", st.panel,
                                     CFG.FRAME_BUTTON_TEMPLATE, pid)
    if btn ~= nil then
      BlzFrameSetSize(btn, CFG.FRAME_ICON, CFG.FRAME_ICON)
      BlzFrameSetPoint(btn, FRAMEPOINT_LEFT, st.panel, FRAMEPOINT_LEFT,
                       startX + (i - 1) * step, -CFG.FRAME_H * 0.08)

      local path = iconOf(choice)
      if path ~= nil then
        local ic = BlzCreateFrameByType("BACKDROP", "SkillIcon", btn, "", pid)
        if ic ~= nil then
          BlzFrameSetAllPoints(ic, btn)
          BlzFrameSetTexture(ic, path, 0, true)
          API.frameDead(ic)
        end
      end

      if BlzFrameSetTooltip == nil and BlzFrameSetText ~= nil then
        local lbl = BlzCreateFrameByType("TEXT", "SkillLbl", st.panel, "", pid)
        if lbl ~= nil then
          BlzFrameSetPoint(lbl, FRAMEPOINT_CENTER, btn, FRAMEPOINT_CENTER,
                           0.0, -CFG.FRAME_ICON * 0.75)
          BlzFrameSetText(lbl, choice.name)
          API.frameDead(lbl)
        end
      end

      BlzTriggerRegisterFrameEvent(S.sframe.trig, btn, FRAMEEVENT_CONTROL_CLICK)
      -- Ghi SO THU TU cua lua chon, khong phai id ability: kenh dong bo
      -- chi tai duoc so nho. Xem src/1_nen/3_sync.lua.
      st.map[btn] = { pid = pid, slot = slotIndex, ci = i }
      made = made + 1
    end
  end

  API.trace("frame: pid " .. pid .. " slot " .. slotIndex ..
            " -- tao " .. made .. "/" .. n .. " nut")
  if made == 0 then
    API.msg(nil, CFG.C_RED .. "frame: khong tao duoc nut nao -- thu doi " ..
      "CFG.FRAME_BUTTON_TEMPLATE." .. CFG.C_END)
    destroyPanel(pid)
    return false
  end

  st.slot = slotIndex
  BlzFrameSetVisible(st.panel, false)
  if GetLocalPlayer() == Player(pid) then
    BlzFrameSetVisible(st.panel, true)
  end
  return true
end

local function showFrame(pid)
  if not framesAvailable() then
    API.msg(pid, CFG.C_GOLD .. "Lui ve popup chu." .. CFG.C_END)
    API.showSkillPicker(pid)
    return false
  end

  local d = S.p[pid]
  if d == nil or d.hero == nil then
    API.msg(pid, CFG.C_RED .. "Chua co hero de gan ky nang." .. CFG.C_END)
    return false
  end

  local si, slots = nextSlotIndex(pid)
  if #slots == 0 then
    API.msg(pid, CFG.C_RED .. "Hero nay chua khai bao cay skill nao." .. CFG.C_END)
    return false
  end
  if si == nil then
    hidePanel(pid)
    API.msg(pid, CFG.C_GOLD .. "Da chon du " .. #slots .. " slot." .. CFG.C_END)
    return false
  end

  return buildPanel(pid, si)
end

-- ---------- Ap dung lua chon ----------
-- Chay tren MOI may, tu su kien dong bo. Day la cho duy nhat duoc phep
-- doi trang thai game.
local function applyChoice(pid, slotIndex, aid)
  local d = S.p[pid]
  if d == nil or d.hero == nil then return end
  if slotIndex == nil or aid == nil then return end

  -- Bam hai lan truoc khi tin dong bo ve: lan thu hai bi chan o day.
  if d.slots[slotIndex] ~= nil then return end

  if not UnitAddAbility(d.hero, aid) then
    API.msg(pid, CFG.C_RED .. "Khong gan duoc ability " .. API.idToStr(aid) ..
      " -- id sai, hoac unit khong nhan duoc ability nay." .. CFG.C_END)
    return
  end
  SetUnitAbilityLevel(d.hero, aid, 1)
  d.slots[slotIndex] = aid

  hidePanel(pid)
  local slots = API.slotsFor(pid)
  API.msg(nil, CFG.C_GOLD .. GetPlayerName(Player(pid)) .. CFG.C_END ..
    " da hoc " .. CFG.C_JADE .. (slots[slotIndex].name or "?") .. CFG.C_END .. ".")

  if CFG.SKILL_PICK_CHAIN then showFrame(pid) end
end

-- ---------- Bam nut: CHI chay tren may nguoi bam ----------
local function onFrameClick()
  local f = BlzGetTriggerFrame()
  if f == nil then return end

  -- Nut cua nguoi nao thi chi nguoi do thay va bam duoc, nhung van tra
  -- lai cho chac -- xu ly cuc bo thi khong duoc phep doan.
  local hit = nil
  for pid, st in pairs(S.sframe.byPid) do
    if st.map[f] ~= nil then hit = st.map[f]; break end
  end
  if hit == nil then return end
  if GetLocalPlayer() ~= Player(hit.pid) then return end

  -- Khong doi gi o day. Chi bao cho moi may biet.
  API.syncSend(hit.pid, CFG.OP_SKILL, hit.slot * 100 + hit.ci)
end

-- Chay tren MOI may khi co ai gui tin.
local function onPicked(pid, arg)
  local slotIndex = math.floor(arg / 100)
  local ci        = arg - slotIndex * 100

  -- Cay skill lay tu hero dang cam, giong nhau tren moi may.
  local slot = API.slotsFor(pid)[slotIndex]
  if slot == nil or slot.choices[ci] == nil then return end

  applyChoice(pid, slotIndex, slot.choices[ci].id)
end

local function startSkillFrame()
  S.sframe = { trig = nil, syncTrig = nil, byPid = {} }
  if CFG.SKILL_MODE ~= "frame" then return end
  if not framesAvailable() then return end

  S.sframe.trig = CreateTrigger()
  TriggerAddAction(S.sframe.trig, onFrameClick)

  API.syncOn(CFG.OP_SKILL, onPicked)
  API.trace("frame: trigger san sang, dong bo=" .. API.syncMode())
end

API.showSkillFrame  = showFrame
API.startSkillFrame = startSkillFrame
API.framesAvailable = framesAvailable
end
--#endregion 4_giao_dien/3_skillframe.lua

--#region 4_giao_dien/4_fct.lua
do
-- ============================================================
--  4_fct.lua  --  Chu bay: sat thuong gay ra / nhan vao / linh khi
--
--  CAI BAY LON NHAT: Warcraft III chi cho khoang 100 text tag ton tai
--  cung luc. Mot wave co 50 con; ve mot chu moi don danh la trong vai
--  giay dat tran, va tu do KHONG CON chu nao hien nua -- ke ca chu quan
--  trong nhu "nha chinh sap chet".
--
--  Nen o day khong ve tung don. Sat thuong duoc CONG DON theo muc tieu
--  trong CFG.FCT_FLUSH giay, roi moi ve MOT chu -- va moi lan ve cung
--  chi ve toi da CFG.FCT_MAX_TAGS cai, uu tien con dau nhat.
--
--  Chu bay la UI thuan nen hien theo tung nguoi bang GetLocalPlayer --
--  an toan, khong dung toi trang thai game.
--
--  Nho: goi ham cua file khac phai qua API.
-- ============================================================

local EVT_OK = nil

local function eventsAvailable()
  if EVT_OK ~= nil then return EVT_OK end
  EVT_OK = (EVENT_PLAYER_UNIT_DAMAGED ~= nil and GetEventDamage ~= nil
        and GetEventDamageSource ~= nil and CreateTextTag ~= nil)
  if not EVT_OK then API.trace("fct: THIEU su kien sat thuong") end
  return EVT_OK
end

-- 1234 -> "1.2K", 1234567 -> "1.2M". Cuoi game sat thuong len hang van,
-- chu dai che mat man hinh.
local function short(n)
  n = math.floor(n + 0.5)
  if n >= 1000000 then return string.format("%.1fM", n / 1000000) end
  if n >= 1000    then return string.format("%.1fK", n / 1000) end
  return tostring(n)
end

-- Ve mot chu bay. pid = nil thi ai cung thay.
local function tag(x, y, text, r, g, b, pid, rise)
  local tt = CreateTextTag()
  if tt == nil then return end

  SetTextTagText(tt, text, CFG.FCT_SIZE)
  SetTextTagPos(tt, x, y, CFG.FCT_HEIGHT)
  SetTextTagColor(tt, r, g, b, 255)
  SetTextTagVelocity(tt, 0.0, (rise or CFG.FCT_RISE))
  SetTextTagPermanent(tt, false)
  SetTextTagLifespan(tt, CFG.FCT_LIFE)
  SetTextTagFadepoint(tt, CFG.FCT_LIFE * 0.5)

  if pid ~= nil then
    SetTextTagVisibility(tt, GetLocalPlayer() == Player(pid))
  end
end

-- ---------- Cong don ----------

local function keyOf(u) return u end

local function addPending(u, pid, amount, kind)
  local f = S.fct
  local k = keyOf(u)
  local e = f.pending[k]
  if e == nil then
    e = { u = u, pid = pid, dealt = 0.0, taken = 0.0 }
    f.pending[k] = e
    f.count = f.count + 1
  end
  if kind == "dealt" then e.dealt = e.dealt + amount
  else                    e.taken = e.taken + amount end
end

-- Ve toi da MAX_TAGS moi lan, uu tien con dau nhat. Phan con lai bi bo
-- -- co y: chu bay la phan hoi, khong phai so ke toan.
local function flush()
  local f = S.fct
  if f.count == 0 then return end

  local list = {}
  for _, e in pairs(f.pending) do list[#list + 1] = e end
  table.sort(list, function(a, b)
    return (a.dealt + a.taken) > (b.dealt + b.taken)
  end)

  local n = #list
  if n > CFG.FCT_MAX_TAGS then n = CFG.FCT_MAX_TAGS end

  for i = 1, n do
    local e = list[i]
    if e.u ~= nil and API.alive(e.u) then
      local x, y = GetUnitX(e.u), GetUnitY(e.u)
      if e.dealt > 0 then
        tag(x, y, short(e.dealt), 255, 230, 120, e.pid)
      end
      if e.taken > 0 then
        tag(x, y, "-" .. short(e.taken), 255, 90, 90, e.pid)
      end
    end
  end

  f.pending = {}
  f.count = 0
end

-- ---------- Su kien ----------

local function onDamage()
  if not CFG.FCT_ENABLED then return end

  local amount = GetEventDamage()
  if amount == nil or amount < CFG.FCT_MIN then return end

  local target = GetTriggerUnit()
  local source = GetEventDamageSource()
  if target == nil then return end

  -- NHA CHINH: ai cung thay (pid = nil).
  --
  -- Truoc day ham nay chi ve cho hero cua nguoi choi, nen ca tran danh
  -- quanh nha chinh dien ra khong mot con so nao -- thu quan trong nhat
  -- cua van lai la thu duy nhat khong co phan hoi.
  --
  -- Khong gan cho mot pid nao: nha chinh do la ca ba nguoi cung thua,
  -- nen mot nguoi thay so con hai nguoi kia khong thay la sai.
  if S.house ~= nil then
    if target == S.house then
      addPending(target, nil, amount, "taken")
      return
    end
    if source == S.house then
      addPending(target, nil, amount, "dealt")
      return
    end
  end

  -- Sat thuong hero cua nguoi choi NHAN VAO: ve tren dau hero, mau do.
  for i = 1, #S.pids do
    local pid = S.pids[i]
    local d = S.p[pid]
    if d ~= nil and d.hero == target then
      addPending(target, pid, amount, "taken")
      return
    end
  end

  -- Sat thuong hero GAY RA: ve tren dau muc tieu, mau vang.
  if source == nil then return end
  local spid = GetPlayerId(GetOwningPlayer(source))
  local sd = S.p[spid]
  if sd ~= nil and sd.hero == source then
    addPending(target, spid, amount, "dealt")
  end
end

-- Goi tu 04_player moi khi cong linh khi.
local function onLinhKhi(pid, amount)
  if not CFG.FCT_ENABLED or not CFG.FCT_SHOW_GOLD then return end
  if amount == nil or amount <= 0 then return end

  local d = S.p[pid]
  if d == nil or d.hero == nil then return end

  d.fctGold = (d.fctGold or 0) + amount
end

-- Linh khi cong don rieng: 50 con moi wave, ve tung dong la ngap man hinh.
local function flushGold()
  if not CFG.FCT_ENABLED or not CFG.FCT_SHOW_GOLD then return end
  for i = 1, #S.pids do
    local pid = S.pids[i]
    local d = S.p[pid]
    if d ~= nil and d.hero ~= nil and (d.fctGold or 0) > 0 then
      if API.alive(d.hero) then
        tag(GetUnitX(d.hero), GetUnitY(d.hero), "+" .. short(d.fctGold),
            255, 215, 0, pid, CFG.FCT_RISE * 0.6)
      end
      d.fctGold = 0
    end
  end
end

local function startFct()
  S.fct = { pending = {}, count = 0 }
  if not CFG.FCT_ENABLED then return end
  if not eventsAvailable() then
    API.msg(nil, CFG.C_RED .. "Khong bat duoc su kien sat thuong -- tat chu bay."
      .. CFG.C_END)
    return
  end

  local t = CreateTrigger()
  TriggerRegisterAnyUnitEventBJ(t, EVENT_PLAYER_UNIT_DAMAGED)
  TriggerAddAction(t, onDamage)

  S.fctTimer = CreateTimer()
  TimerStart(S.fctTimer, CFG.FCT_FLUSH, true, function()
    flush()
    flushGold()
  end)

  API.trace("fct: san sang, gom moi " .. CFG.FCT_FLUSH .. "s, toi da " ..
            CFG.FCT_MAX_TAGS .. " chu/lan")
end

API.fctOnLinhKhi = onLinhKhi
API.fctTag       = tag
API.startFct     = startFct
end
--#endregion 4_giao_dien/4_fct.lua

--#region 5_khoi_dong/1_events.lua
do
-- ============================================================
--  1_events.lua  --  Trigger
--
--  Hai viec: nha chinh chet, va chan nguoi choi chon nha chinh.
--  Su kien popup chon hero do 07_heropick tu dang ky lay.
--
--  Nho: goi ham cua file khac phai qua API.
-- ============================================================

local function onAnyDeath()
  local u = GetTriggerUnit()
  if u == nil then return end
  if u == S.house then
    API.onHouseDeath()
    return
  end
  API.onMobDeath(u, GetKillingUnit())
end

-- Nha chinh la muc tieu phai giu, khong phai quan de dieu khien. Lot
-- vao Ctrl+A roi lo ra lenh cho no la hong ca van.
--
-- Warcraft III khong co cach danh dau mot unit la "khong chon duoc" ma
-- van cho ke dich danh -- ability Locust lam no vo hinh voi ca hai phia,
-- ma nha chet la thua nen khong dung duoc. Nen phai bo chon thu cong.
local function onSelect()
  if CFG.HOUSE_SELECTABLE then return end
  if S.house == nil or GetTriggerUnit() ~= S.house then return end

  local p = GetTriggerPlayer()
  -- Hoan sang tick sau: doi trang thai ngay trong su kien cua engine la
  -- cong thuc gay loi, xem ADR 0005.
  API.after(0.0, function()
    if S.house ~= nil then SelectUnitRemoveForPlayer(S.house, p) end
  end)
end

-- Lenh thu: "-sp" phat mot diem ky nang cho hero cua nguoi go.
--
-- Tra loi TRONG MOI TRUONG HOP. Lenh thu im lang la thu vo dung nhat:
-- khong biet no that bai hay khong duoc dang ky.
local function onChat()
  local pid = GetPlayerId(GetTriggerPlayer())
  local d = S.p[pid]

  -- Lenh dang ky khop TIEN TO, nen "-spawn" cung roi vao day. Kiem lai
  -- chuoi day du roi hay lam gi -- neu khong thi moi lenh moi bat dau
  -- bang "-sp" deu bi lenh nay nuot.
  local raw = GetEventPlayerChatString()
  if raw ~= nil and raw:match("^%s*%-sp%s*$") == nil then return end

  if d == nil then
    API.msg(pid, CFG.C_RED .. "-sp: ban khong nam trong danh sach nguoi choi." .. CFG.C_END)
    return
  end
  if d.hero == nil then
    API.msg(pid, CFG.C_RED .. "-sp: ban chua chon hero." .. CFG.C_END)
    return
  end
  if CFG.SKILL_MODE == "learn" then
    if API.grantSkillPoints(d.hero, 1) then
      API.msg(pid, CFG.C_GOLD .. "-sp: +1 diem ky nang." .. CFG.C_END ..
        " Bam nut + tren hero de chon.")
      API.msg(pid, CFG.C_GREY .. "Khong thay nut + nghia la Techtree - Hero" ..
        " Abilities cua hero con rong." .. CFG.C_END)
    else
      API.msg(pid, CFG.C_RED .. "-sp: UnitModifySkillPoints tu choi." .. CFG.C_END)
    end

  elseif CFG.SKILL_MODE == "pick" then
    API.showSkillPicker(pid)

  elseif CFG.SKILL_MODE == "frame" then
    API.showSkillFrame(pid)

  else
    API.msg(pid, CFG.C_RED .. "-sp: SKILL_MODE dang la \"" ..
      tostring(CFG.SKILL_MODE) .. "\" -- doi sang \"learn\", \"pick\" hoac \"frame\"."
      .. CFG.C_END)
  end
end

-- Lenh dev "-wave N": nhay thang toi stage N.
-- Khong co no thi khong ai kiem duoc stage 180 -- doi 2 tieng de xem
-- mot con so khong phai la cach lam viec.
local function onWaveCmd()
  local pid = GetPlayerId(GetTriggerPlayer())
  local raw = GetEventPlayerChatString()
  if raw == nil then return end

  local n = tonumber(raw:match("^%s*%-wave%s+(%d+)"))
  if n == nil then
    API.msg(pid, CFG.C_RED .. "Dung: -wave <so tu 1 den " ..
      API.totalStages() .. ">" .. CFG.C_END)
    return
  end
  API.jumpToStage(n)
  API.msg(pid, CFG.C_GOLD .. "Nhay toi stage " .. n .. "." .. CFG.C_END)
end

-- "-lc" mo bang Linh Can, "-lc up" dot pha thang khong can bang.
local function onLinhCanCmd()
  API.linhCanChat(GetPlayerId(GetTriggerPlayer()), GetEventPlayerChatString())
end

-- Lenh dev cho tien: "-lk 5000" Linh Khi, "-go 300" Go, "-vang 5000" Vang.
-- Khong co no thi muon thu bac Linh Can 15 phai cay 155 wave.
local function onMoneyCmd()
  local pid = GetPlayerId(GetTriggerPlayer())
  local raw = GetEventPlayerChatString()
  if raw == nil then return end

  local n = tonumber(raw:match("^%s*%-lk%s+(%d+)"))
  if n ~= nil then
    API.addLinhKhi(pid, n)
    API.msg(pid, CFG.C_GREY .. "[dev] +" .. API.num(n) .. " linh khi -> " ..
      API.num(API.getLinhKhi(pid)) .. CFG.C_END)
    API.panelRefresh(pid)
    return
  end

  n = tonumber(raw:match("^%s*%-go%s+(%d+)"))
  if n ~= nil then
    API.addGo(pid, n)
    API.msg(pid, CFG.C_GREY .. "[dev] +" .. API.num(n) .. " go -> " ..
      API.num(API.getGo(pid)) .. CFG.C_END)
    API.panelRefresh(pid)
    return
  end

  n = tonumber(raw:match("^%s*%-vang%s+(%d+)"))
  if n ~= nil then
    API.addVang(pid, n)
    API.msg(pid, CFG.C_GREY .. "[dev] +" .. API.num(n) .. " vang -> " ..
      API.num(API.getVang(pid)) .. CFG.C_END)
    API.panelRefresh(pid)
    return
  end

  API.msg(pid, CFG.C_RED .. "Dung: -lk <so> | -go <so> | -vang <so>" .. CFG.C_END)
end

local function registerEvents()
  local tDeath = CreateTrigger()
  TriggerRegisterAnyUnitEventBJ(tDeath, EVENT_PLAYER_UNIT_DEATH)
  TriggerAddAction(tDeath, onAnyDeath)

  if not CFG.HOUSE_SELECTABLE then
    local tSelect = CreateTrigger()
    for i = 1, #S.pids do
      TriggerRegisterPlayerUnitEvent(tSelect, Player(S.pids[i]),
                                     EVENT_PLAYER_UNIT_SELECTED, nil)
    end
    TriggerAddAction(tSelect, onSelect)
  end

  if CFG.DEV_COMMANDS then
    local tChat = CreateTrigger()
    for i = 1, #S.pids do
      -- exactMatch = false: "-sp " thua dau cach van an
      TriggerRegisterPlayerChatEvent(tChat, Player(S.pids[i]), "-sp", false)
    end
    TriggerAddAction(tChat, onChat)

    local tWave = CreateTrigger()
    for i = 1, #S.pids do
      TriggerRegisterPlayerChatEvent(tWave, Player(S.pids[i]), "-wave", false)
    end
    TriggerAddAction(tWave, onWaveCmd)
  end

  if CFG.DEV_COMMANDS then
    local tMoney = CreateTrigger()
    for i = 1, #S.pids do
      TriggerRegisterPlayerChatEvent(tMoney, Player(S.pids[i]), "-lk", false)
      TriggerRegisterPlayerChatEvent(tMoney, Player(S.pids[i]), "-go", false)
      TriggerRegisterPlayerChatEvent(tMoney, Player(S.pids[i]), "-vang", false)
    end
    TriggerAddAction(tMoney, onMoneyCmd)
  end

  -- Loi choi, khong phai lenh dev -- luon dang ky.
  local tLC = CreateTrigger()
  for i = 1, #S.pids do
    TriggerRegisterPlayerChatEvent(tLC, Player(S.pids[i]), "-lc", false)
  end
  TriggerAddAction(tLC, onLinhCanCmd)

  -- "-next" goi dot ke tiep. LUON dang ky, khong theo DEV_COMMANDS:
  -- voi CFG.WAVE_WAIT_FIRST thi day la thu duy nhat khoi dong duoc van,
  -- tat no di la ngoi nhin man hinh trong mai mai.
  --
  -- Khong phai lenh cheat: no doi da don sach quai moi goi duoc, nen
  -- khong bo qua duoc phan nao ca.
  do
    local tNext = CreateTrigger()
    for i = 1, #S.pids do
      -- false = khop TIEN TO. Voi true thi go du mot dau cach thua la
      -- khong khop, va khong khop thi im lang hoan toan.
      TriggerRegisterPlayerChatEvent(tNext, Player(S.pids[i]), "-next", false)
    end
    TriggerAddAction(tNext, function()
      local pid = GetPlayerId(GetTriggerPlayer())
      API.trace("-next: pid " .. pid .. ", song=" .. S.alive ..
                ", stage=" .. S.stage)
      -- Chi goi som duoc khi da don sach. Cho phep goi som luc con quai
      -- la cho nguoi choi bo qua phan kho cua wave nay va nhan tien cua
      -- wave sau -- pha dung cai duong cong dang giu ca van.
      if S.alive > 0 then
        API.msg(pid, CFG.C_RED .. API.t("wave_notclear", S.alive) .. CFG.C_END)
        return
      end
      -- Dang o cua so nghi thi -next la thu DUY NHAT di tiep duoc, nen
      -- bao ro ai la nguoi bam.
      local cho = API.waveWaiting()
      if API.waveNow() then
        API.msg(nil, CFG.C_GREY .. GetPlayerName(Player(pid)) ..
          " -> " .. API.t("wave_next") ..
          (cho ~= nil and (" (" .. cho .. ")") or "") .. CFG.C_END)
      end
    end)
  end

  -- "-spawn": tao thang mot con H001 bang CreateUnit, canh hero.
  --
  -- De so sanh voi con dat san trong World Editor: cung loai unit, cung
  -- man hinh, mot con do WE dat, mot con do code tao. Neu chi con do code
  -- tao bi den thi loi nam o cach tao, khong phai o file model.
  if CFG.DEV_COMMANDS then
    local tSpawn = CreateTrigger()
    for i = 1, #S.pids do
      TriggerRegisterPlayerChatEvent(tSpawn, Player(S.pids[i]), "-spawn", false)
    end
    TriggerAddAction(tSpawn, function()
      local pid = GetPlayerId(GetTriggerPlayer())
      local d = S.p[pid]
      local x, y = S.houseX or 0.0, S.houseY or 0.0
      if d ~= nil and d.hero ~= nil then
        x, y = GetUnitX(d.hero) + 200.0, GetUnitY(d.hero)
      end
      local uid = CFG.HEROES[1] and CFG.HEROES[1].id
      local u = CreateUnit(Player(pid), uid, x, y, 270.0)
      API.msg(pid, CFG.C_GREY .. "[dev] CreateUnit " .. API.idToStr(uid) ..
        (u ~= nil and " -> ok" or " -> NIL") .. CFG.C_END)
      API.trace("-spawn: " .. API.idToStr(uid) ..
                (u ~= nil and " tao duoc" or " TAO THAT BAI"))
    end)
  end

  -- "-sync" bao duong dong bo nao dang chay va ping co ve khong. Luon
  -- dang ky: khi bang khong an thi day la cho dau tien phai nhin.
  local tSync = CreateTrigger()
  for i = 1, #S.pids do
    TriggerRegisterPlayerChatEvent(tSync, Player(S.pids[i]), "-sync", true)
  end
  TriggerAddAction(tSync, function()
    API.syncChat(GetPlayerId(GetTriggerPlayer()))
  end)

  -- "-nat" liet ke native ban nay co. Luon dang ky: khi mot he im lang
  -- khong chay, day la cho thu hai phai nhin sau file vet.
  local tNat = CreateTrigger()
  for i = 1, #S.pids do
    -- false = khop TIEN TO. Voi true thi "-nat dam" khong khop gi ca va
    -- trigger khong no -- go lenh xong im lang, tuong la khong co ket qua.
    TriggerRegisterPlayerChatEvent(tNat, Player(S.pids[i]), "-nat", false)
  end
  TriggerAddAction(tNat, function()
    API.nativeChat(GetPlayerId(GetTriggerPlayer()), GetEventPlayerChatString())
  end)

  -- "-reg" DO hoi mau that cua hero. Lenh dev: no ha mau hero xuong nua
  -- va doi chi so trong luc do, khong phai thu de go giua tran.
  if CFG.DEV_COMMANDS then
    local tReg = CreateTrigger()
    for i = 1, #S.pids do
      TriggerRegisterPlayerChatEvent(tReg, Player(S.pids[i]), "-reg", false)
    end
    TriggerAddAction(tReg, function()
      local pid = GetPlayerId(GetTriggerPlayer())
      local raw = GetEventPlayerChatString() or ""
      -- "-reg" mau | "-reg mana" mana | "-reg 5" / "-reg mana 5" doi so giay
      local loai = raw:find("mana", 1, true) and "mana" or "hp"
      API.nativeRegen(pid, tonumber(raw:match("(%d+)")), loai)
    end)
  end

  -- "-vung" in ban do phan vung 25 block va ping minimap theo mau.
  --
  -- Luon dang ky, khong theo DEV_COMMANDS: chua he nao gan vao block,
  -- nen day la cach DUY NHAT nhin thay bang CFG.BLOCKS co dung nhu dinh
  -- khong -- va de doi chieu voi vung Blk.. trong World Editor.
  local tVung = CreateTrigger()
  for i = 1, #S.pids do
    TriggerRegisterPlayerChatEvent(tVung, Player(S.pids[i]), "-vung", true)
  end
  TriggerAddAction(tVung, function()
    local pid = GetPlayerId(GetTriggerPlayer())
    API.msg(pid, CFG.C_GOLD .. "=== Phan vung 25 block ===" .. CFG.C_END)

    local thieu = 0
    -- In tu hang TREN xuong, dung chieu nguoi choi nhin ban do.
    for row = S.grid.rows, 1, -1 do
      local line = ""
      for col = 1, S.grid.cols do
        local idx = API.blockIndex(col, row)
        local d   = API.blockRoleDef(idx)
        if API.blockRegion(idx) == nil then thieu = thieu + 1 end
        line = line .. string.format("%-14s", idx .. " " .. API.pick(d))
      end
      API.msg(pid, line)
    end

    -- Ping tam moi block, mau theo vai tro.
    API.forEachBlock(function(col, row, idx, x0, y0, x1, y1)
      local m = API.blockRoleDef(idx).mau
      PingMinimapEx((x0 + x1) * 0.5, (y0 + y1) * 0.5, 6.0,
                    m[1], m[2], m[3], false)
    end)

    if thieu > 0 then
      API.msg(pid, CFG.C_RED .. "Thieu " .. thieu .. " vung " ..
        CFG.BLOCK_RGN_PREFIX .. ".. trong World Editor." .. CFG.C_END ..
        CFG.C_GREY .. " Chay: python w3region.py gen" .. CFG.C_END)
    end
    API.msg(pid, CFG.C_GREY ..
      "Chua he nao gan vao block -- day moi la ban do." .. CFG.C_END)
  end)

  -- "-c" mo bang nhan vat, duong lui neu phim E khong gan duoc.
  local tPanel = CreateTrigger()
  for i = 1, #S.pids do
    TriggerRegisterPlayerChatEvent(tPanel, Player(S.pids[i]), "-c", true)
  end
  TriggerAddAction(tPanel, function()
    API.panelToggle(GetPlayerId(GetTriggerPlayer()))
  end)

  API.dbg("Trigger da dang ky.")
end

API.registerEvents = registerEvents
end
--#endregion 5_khoi_dong/1_events.lua

--#region 5_khoi_dong/2_init.lua
do
-- ============================================================
--  2_init.lua  --  Khoi dong & moc vao main() cua map
--
--  File nay phai la file cuoi cung: build.py dong khoi do...end ngay
--  sau day.
-- ============================================================

-- In so do luoi ra chat. Day la cach kiem tra buoc 1: doi chieu con so
-- o day voi thuoc do trong World Editor.
local function reportGrid()
  local g = S.grid
  API.msg(nil, CFG.C_GOLD .. "=== Luoi " .. g.cols .. "x" .. g.rows ..
    " (" .. (g.cols * g.rows) .. " o) ===" .. CFG.C_END)
  API.msg(nil, "Vung choi duoc : " .. g.tilesW .. " x " .. g.tilesH .. " o dia hinh"
    .. "  (" .. API.num(g.playMaxX - g.playMinX) .. " x "
    .. API.num(g.playMaxY - g.playMinY) .. " don vi)")
  API.msg(nil, "Moi block      : " .. g.blockTilesW .. " x " .. g.blockTilesH .. " o"
    .. "  (" .. API.num(g.blockW) .. " x " .. API.num(g.blockH) .. " don vi)")
  API.msg(nil, "Long song      : " .. g.riverTiles .. " o  ("
    .. API.num(g.river) .. " don vi)")
  API.msg(nil, "Le hai ben     : " .. g.marginTilesX .. " o ngang, "
    .. g.marginTilesY .. " o doc")
  API.msg(nil, "Goc luoi (1,1) : " .. API.num(g.originX) .. ", " .. API.num(g.originY))
end

-- Ping minimap tam moi block de nhin thay luoi ngay khi vao map.
local function pingBlocks()
  API.forEachBlock(function(col, row, idx, x0, y0, x1, y1)
    local cx, cy = (x0 + x1) * 0.5, (y0 + y1) * 0.5
    PingMinimapEx(cx, cy, 8.0, 255, 200, 0, false)
  end)
end

-- Ket thuc van. Doi 3 giay cho nguoi choi doc duoc ly do truoc khi
-- man hinh ket qua che mat.
local function endGame(win, reason)
  if not S.running then return end
  S.running = false
  API.stopWaves()

  API.msg(nil, " ")
  if win then
    API.msg(nil, CFG.C_GOLD .. "THANG -- " .. reason .. CFG.C_END)
  else
    API.msg(nil, CFG.C_RED .. "THUA -- " .. reason .. CFG.C_END)
  end

  API.after(3.0, function()
    for i = 1, #S.pids do
      local p = Player(S.pids[i])
      if win then
        CustomVictoryBJ(p, reason, true, true)
      else
        CustomDefeatBJ(p, reason)
      end
    end
  end)
end

-- Chay sau khi map da nap xong (goi tu timer 0 giay ben duoi).
local function bootstrap()
  if S.running then return end

  API.trace("bootstrap: bat dau")
  -- In ca DAU THOI GIAN build, khong chi so hieu. CFG.VERSION go tay
  -- nen hai ban build khac nhau van cung mot so -- va luc do "go lenh
  -- moi ma khong thay gi" khong phan biet duoc voi "dang chay ban cu".
  API.msg(nil, CFG.C_GOLD .. "[build " .. CFG.VERSION ..
          (CFG.BUILD and ("  " .. CFG.BUILD) or "") ..
          "] code da chay." .. CFG.C_END)

  -- Mo suong mu. Khong bao gi: day la cach map nay chay binh thuong,
  -- khong phai mot cong tac dev dang bat. Bao moi van mot dong "[dev]"
  -- chi lam nguoi choi tuong minh dang o ban chua xong.
  if CFG.REVEAL_MAP then
    FogEnable(false)
    FogMaskEnable(false)
  end

  local n = API.initPlayers()
  API.trace("initPlayers: " .. n .. " nguoi choi")

  -- Kenh dong bo phai san sang TRUOC moi he khac: cac he dang ky tin
  -- nhan cua minh trong ham start cua chung.
  API.startSync()
  API.langCheck()

  -- Do xem ban nay co nhung native nao. Khong doi gi, chi ghi vet --
  -- nhung moi lan doan thay vi do, du an nay deu doan sai (ADR 0012).
  API.startNatives()

  API.buildGrid()
  API.trace("buildGrid: xong")

  -- Nha chinh dung sau khi co luoi, de bao cao duoc no nam o block nao.
  API.createHouse()
  API.trace("createHouse: tra ve")

  API.resolveEnemyRegion()
  API.trace("resolveEnemyRegion: xong")

  -- Phai chay TRUOC khi nguoi choi kip chon hero.
  --
  -- HAI CACH, vi chua biet cach nao an:
  --   1. Preload() thang duong dan file   <- cach chinh
  --   2. tao mot con moi loai hero roi xoa ngay
  --
  -- PreloadStart/PreloadEnd moi la cap nap THAT. PreloadGenStart/
  -- PreloadGenEnd la de SINH file preload -- lan trong do thi Preload()
  -- chi ghi ten vao file chu khong nap gi ca. Bo ghi vet cua du an nay
  -- dung dung ho PreloadGen*, nen phai goi dung cap o day.
  if CFG.PRELOAD ~= nil and Preload ~= nil then
    if PreloadStart ~= nil then PreloadStart() end
    for i = 1, #CFG.PRELOAD do Preload(CFG.PRELOAD[i]) end
    if PreloadEnd ~= nil then PreloadEnd(0.5) end
    API.trace("preload: da goi Preload cho " .. #CFG.PRELOAD .. " file")
  end

  API.preloadHeroes()

  API.startHeroLock()
  API.trace("startHeroLock: xong")

  -- Cac he dang ky the TRUOC, roi bang moi dung -- bang can biet co
  -- bao nhieu the de chia be ngang.
  -- Thu tu dang ky = thu tu the trong bang. Nam he -- xem
  -- docs/02-he-thong/kinh-te.md
  API.startLinhCan()   -- I.   Linh Khi
  API.startSkills()    -- II.  Go
  API.startTrangBi()   -- III. (tam khoa)
  API.startPhapKhi()   -- IV.  (tam khoa)
  API.startShop()      -- V.   Vang
  API.startDungDo()
  API.startPanel()

  API.startSkillFx()
  API.startFct()
  API.startWaves()
  API.startHeroFrame()
  API.startSkillFrame()
  API.startSkillPicking()
  API.startPicking()
  API.trace("startPicking: tra ve")

  API.registerEvents()
  API.trace("registerEvents: xong")

  S.running = true
  API.trace("BOOTSTRAP HOAN TAT")

  if CFG.DEBUG then
    reportGrid()
    pingBlocks()
    API.report()
    API.heroPickReport()
    API.dbg(n .. " nguoi choi vao map.")
  end
end

API.endGame    = endGame
API.reportGrid = reportGrid
API.pingBlocks = pingBlocks
API.bootstrap  = bootstrap

-- ---------- Moc vao vong doi cua map ----------
-- Khoi code nay chay luc nap chunk, truoc khi main() duoc goi. Ta boc
-- InitGlobals (main() goi no ngay sau InitBlizzard), roi hen timer 0 giay
-- de bootstrap chay khi map thuc su san sang.
-- Vet nay chay luc NAP CHUNK, truoc ca main(). No phan biet duoc hai
-- truong hop rat khac nhau:
--   co dong nay, khong co "bootstrap" -> chunk nap duoc nhung moc hong
--   khong co dong nao ca              -> map khong he chua code nay
API.trace("chunk: da nap, dang moc InitGlobals")

do
  local function chay()
    TimerStart(CreateTimer(), 0.00, false, function()
      DestroyTimer(GetExpiredTimer())
      bootstrap()   -- tu chan neu da chay roi (S.running)
    end)
  end

  -- HAI DUONG, chu khong mot.
  --
  -- Khi code duoc nhet vao war3map.wct (o custom script cua World
  -- Editor), World Editor quyet dinh dat no o dau trong war3map.lua --
  -- va no co the dat TRUOC "function InitGlobals()". Luc do
  -- prevInitGlobals bat duoc nil, roi dinh nghia that cua InitGlobals
  -- de len ban thay the cua ta: moc mat, khong bao gi.
  --
  -- Nen ngoai moc do con hen thang mot timer ngay luc nap chunk. Cai
  -- nao toi truoc thi chay, bootstrap tu chan lan thu hai.
  local prevInitGlobals = InitGlobals
  InitGlobals = function()
    if prevInitGlobals ~= nil then prevInitGlobals() end
    chay()
  end

  chay()
end
end
--#endregion 5_khoi_dong/2_init.lua

-- build.py --lang en
CFG.LANG = "en"

CFG.BUILD = "2026-09-17 08:37:02"

end
